import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum EquipmentCondition {
  NEW = "Novo",
  USED = "Usado"
}

export interface Equipment {
  type: string;
  brand: string;
  model: string;
  serial: string;
  processor: string;
  condition: EquipmentCondition;
  memory: string;
}

export interface AssetExchange {
  id: string;
  name: string;
  email: string;
  date: string;
  delivered: Equipment;
  returned: Equipment;
  timestamp: number;
}

export type View = 'form' | 'inventory';

import { jsPDF } from 'jspdf';
import { AssetExchange } from '../types';

export const generateAssetPDF = (exchange: AssetExchange) => {
  const doc = new jsPDF();
  const primaryColor = "#1e293b";

  // Header
  doc.setFontSize(22);
  doc.setTextColor(primaryColor);
  doc.text("TERMO DE ENTREGA E DEVOLUÇÃO DE EQUIPAMENTO", 105, 20, { align: "center" });

  doc.setFontSize(10);
  doc.setTextColor("#64748b");
  doc.text(`ID do Registro: ${exchange.id} | Data: ${new Date(exchange.date).toLocaleDateString('pt-BR')}`, 105, 28, { align: "center" });

  // User Info
  doc.setDrawColor("#e2e8f0");
  doc.line(20, 35, 190, 35);

  doc.setFontSize(12);
  doc.setTextColor(primaryColor);
  doc.text("DADOS DO COLABORADOR", 20, 45);
  doc.setFontSize(10);
  doc.text(`Nome: ${exchange.name}`, 20, 52);
  doc.text(`E-mail: ${exchange.email}`, 20, 57);

  // Delivered Equipment
  doc.setFontSize(12);
  doc.text("EQUIPAMENTO ENTREGUE (NOVO ATIVO)", 20, 70);
  doc.setFontSize(10);
  const del = exchange.delivered;
  doc.text(`Tipo: ${del.type}`, 20, 77);
  doc.text(`Marca/Modelo: ${del.brand} - ${del.model}`, 20, 82);
  doc.text(`Série: ${del.serial}`, 20, 87);
  doc.text(`Processador: ${del.processor} | Memória: ${del.memory}`, 20, 92);
  doc.text(`Estado: ${del.condition}`, 20, 97);

  // Returned Equipment
  doc.setFontSize(12);
  doc.text("EQUIPAMENTO DEVOLVIDO (ATIVO ANTIGO)", 20, 110);
  doc.setFontSize(10);
  const ret = exchange.returned;
  doc.text(`Tipo: ${ret.type}`, 20, 117);
  doc.text(`Marca/Modelo: ${ret.brand} - ${ret.model}`, 20, 122);
  doc.text(`Série: ${ret.serial}`, 20, 127);
  doc.text(`Processador: ${ret.processor} | Memória: ${ret.memory}`, 20, 132);
  doc.text(`Estado: ${ret.condition}`, 20, 137);

  // Declarations
  doc.setFontSize(10);
  const declaration = "Declaro ter recebido o equipamento acima descrito em perfeitas condições de uso e funcionamento, comprometendo-me a zelar pelo mesmo e utilizá-lo exclusivamente para fins profissionais.";
  const splitText = doc.splitTextToSize(declaration, 170);
  doc.text(splitText, 20, 155);

  // Signatures
  doc.line(20, 200, 90, 200);
  doc.text("Assinatura do Colaborador", 35, 205);

  doc.line(120, 200, 190, 200);
  doc.text("Assinatura do Responsável TI", 135, 205);

  // Save the PDF
  doc.save(`Termo_Ativo_${exchange.name.replace(/\s/g, '_')}.pdf`);
};

import * as XLSX from 'xlsx';
import { AssetExchange } from '../types';

export const exportToExcel = (data: AssetExchange[]) => {
  const flattenedData = data.map(item => ({
    "ID": item.id,
    "Nome": item.name,
    "Email": item.email,
    "Data Troca": item.date,
    "Entregue - Tipo": item.delivered.type,
    "Entregue - Marca": item.delivered.brand,
    "Entregue - Modelo": item.delivered.model,
    "Entregue - Serial": item.delivered.serial,
    "Entregue - CPU": item.delivered.processor,
    "Entregue - RAM": item.delivered.memory,
    "Entregue - Estado": item.delivered.condition,
    "Devolvido - Tipo": item.returned.type,
    "Devolvido - Marca": item.returned.brand,
    "Devolvido - Modelo": item.returned.model,
    "Devolvido - Serial": item.returned.serial,
    "Devolvido - CPU": item.returned.processor,
    "Devolvido - RAM": item.returned.memory,
    "Devolvido - Estado": item.returned.condition,
    "Data Registro": new Date(item.timestamp).toLocaleString('pt-BR')
  }));

  const worksheet = XLSX.utils.json_to_sheet(flattenedData);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Inventário de Trocas");

  // Create filename with current date
  const filename = `Inventario_Ativos_${new Date().toISOString().split('T')[0]}.xlsx`;
  XLSX.writeFile(workbook, filename);
};

import React, { useState, useEffect } from 'react';
import { Layout, PlusCircle, ClipboardList, Database, LogOut, CheckCircle2, AlertCircle } from 'lucide-react';
import { View, AssetExchange, EquipmentCondition } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('asset_exchanges');
    if (saved) {
      setExchanges(JSON.parse(saved));
    }
  }, []);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const handleSaveExchange = (exchange: AssetExchange) => {
    const updated = [exchange, ...exchanges];
    setExchanges(updated);
    localStorage.setItem('asset_exchanges', JSON.stringify(updated));
    showNotification("Registro de troca salvo com sucesso!");
    setCurrentView('inventory');
  };

  const handleDeleteExchange = (id: string) => {
    if (confirm("Tem certeza que deseja excluir este registro?")) {
      const updated = exchanges.filter(e => e.id !== id);
      setExchanges(updated);
      localStorage.setItem('asset_exchanges', JSON.stringify(updated));
      showNotification("Registro excluído.", "error");
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 font-sans">
      {/* Sidebar */}
      <aside className="w-full md:w-64 bg-slate-900 text-white flex-shrink-0 flex flex-col">
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <Database className="text-white" size={24} />
          </div>
          <h1 className="text-xl font-bold tracking-tight">AssetFlow</h1>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4">
          <button
            onClick={() => setCurrentView('form')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'form' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
            <PlusCircle size={20} />
            <span className="font-medium">Nova Troca</span>
          </button>

          <button
            onClick={() => setCurrentView('inventory')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'inventory' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
            <ClipboardList size={20} />
            <span className="font-medium">Inventário</span>
          </button>
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-red-400 transition-colors">
            <LogOut size={20} />
            <span className="font-medium">Sair</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-auto relative">
        {/* Notification Toast */}
        {notification && (
          <div className={`fixed top-6 right-6 z-50 flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl animate-bounce-short border ${notification.type === 'success' ? 'bg-emerald-50 text-emerald-800 border-emerald-100' : 'bg-rose-50 text-rose-800 border-rose-100'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            <p className="font-medium">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto p-6 md:p-10">
          <header className="mb-8">
            <h2 className="text-3xl font-bold text-slate-900">
              {currentView === 'form' ? 'Registrar Troca de Equipamento' : 'Inventário de Ativos'}
            </h2>
            <p className="text-slate-500 mt-1">
              {currentView === 'form' ? 'Preencha os campos abaixo para documentar a entrega e devolução.' : 'Visualize e gerencie todos os registros de trocas efetuadas.'}
            </p>
          </header>

          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            {currentView === 'form' ? (
              <AssetForm onSave={handleSaveExchange} />
            ) : (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDeleteExchange} 
                onNotify={showNotification}
              />
            )}
          </div>
        </div>
      </main>

      <style>{`
        @keyframes bounce-short {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-5px); }
        }
        .animate-bounce-short {
          animation: bounce-short 0.5s ease-in-out infinite;
          animation-iteration-count: 2;
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Equipment, AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS } from '../constants';
import { User, Package, History, Send } from 'lucide-react';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => void;
}

const initialEquipment: Equipment = {
  type: EQUIPMENT_TYPES[0],
  brand: BRANDS[0],
  model: MODELS[BRANDS[0]][0],
  serial: '',
  processor: '',
  condition: EquipmentCondition.NEW,
  memory: ''
};

const AssetForm: React.FC<AssetFormProps> = ({ onSave }) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    date: new Date().toISOString().split('T')[0]
  });

  const [delivered, setDelivered] = useState<Equipment>({ ...initialEquipment });
  const [returned, setReturned] = useState<Equipment>({ ...initialEquipment, condition: EquipmentCondition.USED });

  const handleBrandChange = (brand: string, type: 'delivered' | 'returned') => {
    const models = MODELS[brand] || ["Outro"];
    if (type === 'delivered') {
      setDelivered({ ...delivered, brand, model: models[0] });
    } else {
      setReturned({ ...returned, brand, model: models[0] });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const exchange: AssetExchange = {
      id: Math.random().toString(36).substr(2, 9).toUpperCase(),
      ...formData,
      delivered,
      returned,
      timestamp: Date.now()
    };
    onSave(exchange);
  };

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-6 pb-2 border-b border-slate-100">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={20} className="text-white" />
      </div>
      <h3 className="text-lg font-semibold text-slate-800">{title}</h3>
    </div>
  );

  return (
    <form onSubmit={handleSubmit} className="p-8 space-y-12">
      {/* Colaborador Section */}
      <section>
        <SectionHeader icon={User} title="Dados do Colaborador" color="bg-indigo-600" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Nome Completo</label>
            <input 
              required
              className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all bg-slate-50 focus:bg-white"
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
              placeholder="Ex: João Silva"
            />
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">E-mail Corporativo</label>
            <input 
              required
              type="email"
              className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all bg-slate-50 focus:bg-white"
              value={formData.email}
              onChange={e => setFormData({ ...formData, email: e.target.value })}
              placeholder="joao.silva@empresa.com"
            />
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-slate-700">Data da Troca</label>
            <input 
              required
              type="date"
              className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-all bg-slate-50 focus:bg-white"
