import React, { useEffect, useRef, useState } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { X, Loader2, Camera } from 'lucide-react';

interface BarcodeScannerModalProps {
  onScan: (decodedText: string) => void;
  onClose: () => void;
  title: string;
}

const BarcodeScannerModal: React.FC<BarcodeScannerModalProps> = ({ onScan, onClose, title }) => {
  const [isInitializing, setIsInitializing] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const scannerRef = useRef<Html5Qrcode | null>(null);
  const elementId = "qr-reader-container";

  useEffect(() => {
    const startScanner = async () => {
      try {
        const html5QrCode = new Html5Qrcode(elementId);
        scannerRef.current = html5QrCode;

        const config = {
          fps: 15,
          // Box size optimized for barcodes (wide) and QR codes
          qrbox: { width: 300, height: 200 },
          aspectRatio: 1.0
        };

        await html5QrCode.start(
          { facingMode: "environment" },
          config,
          (decodedText) => {
            // Success!
            if (scannerRef.current) {
              scannerRef.current.stop().then(() => {
                onScan(decodedText);
              }).catch(e => {
                console.error("Stop error", e);
                onScan(decodedText);
              });
            }
          },
          () => {
            // Error callback - ignored for high frequency scanning
          }
        );

        setIsInitializing(false);
      } catch (err: any) {
        console.error("Scanner init error", err);
        setError("Não foi possível acessar a câmera. Verifique as permissões.");
        setIsInitializing(false);
      }
    };

    // Small delay to ensure DOM is ready
    const timeout = setTimeout(startScanner, 300);

    return () => {
      clearTimeout(timeout);
      if (scannerRef.current && scannerRef.current.isScanning) {
        scannerRef.current.stop().catch(e => console.error("Cleanup stop error", e));
      }
    };
  }, [onScan]);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
        <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-slate-50/80">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg">
              <Camera size={20} />
            </div>
            <div>
              <h3 className="font-bold text-slate-800 leading-none">Scanner de Ativos</h3>
              <p className="text-xs text-slate-500 mt-1">{title}</p>
            </div>
          </div>
          <button 
            onClick={onClose}
            className="p-2 hover:bg-slate-200 rounded-xl transition-colors text-slate-500"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-8 relative min-h-[350px] flex flex-col items-center justify-center">
          {isInitializing && (
            <div className="absolute inset-0 z-10 bg-white flex flex-col items-center justify-center gap-3">
              <Loader2 className="text-indigo-600 animate-spin" size={40} />
              <p className="text-slate-500 font-medium">Iniciando câmera...</p>
            </div>
          )}

          {error ? (
            <div className="text-center p-6 bg-rose-50 border border-rose-100 rounded-2xl text-rose-700">
              <p className="font-semibold">{error}</p>
              <button 
                onClick={onClose}
                className="mt-4 px-6 py-2 bg-rose-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-rose-200"
              >
                Fechar
              </button>
            </div>
          ) : (
            <>
              <div 
                id={elementId} 
                className="w-full max-w-sm aspect-square overflow-hidden rounded-2xl border-4 border-slate-100 bg-black shadow-inner relative"
              >
                {/* Visual scan target overlay */}
                <div className="absolute inset-0 z-20 pointer-events-none border-[40px] border-black/40">
                  <div className="w-full h-full border-2 border-indigo-400 rounded-sm relative">
                    <div className="absolute top-1/2 left-0 w-full h-0.5 bg-indigo-500/50 shadow-[0_0_10px_rgba(99,102,241,0.5)] animate-pulse"></div>
                  </div>
                </div>
              </div>
              <p className="mt-6 text-center text-sm text-slate-500 max-w-xs leading-relaxed">
                Centralize o código de barras ou QR Code na área demarcada para leitura automática.
              </p>
            </>
          )}
        </div>

        <div className="p-5 bg-slate-50 border-t border-slate-100 flex justify-center gap-3">
          <button 
            onClick={onClose}
            className="px-8 py-2.5 bg-slate-800 text-white rounded-xl text-sm font-bold hover:bg-slate-700 transition-all shadow-lg shadow-slate-200"
          >
            Cancelar
          </button>
        </div>
      </div>
    </div>
  );
};

