            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3.5 rounded-2xl font-semibold shadow-xl shadow-indigo-600/20 transition-all hover:scale-[1.02] active:scale-95"
          >
            <Send size={20} />
            Salvar Registro de Troca
          </button>
        </div>
      </form>

      {/* Barcode Scanner Modal */}
      {scannerConfig.isOpen && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'delivered' ? 'Equipamento Entregue' : 'Equipamento Devolvido'}
          onScan={handleScanSuccess}
          onClose={() => setScannerConfig({ ...scannerConfig, isOpen: false })}
        />
      )}
    </>
  );
};

