import React, { useState } from 'react';
import { AssetExchange } from '../types';
import { FileDown, Share2, Trash2, Search, FileSpreadsheet, ClipboardList, Pencil } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';
import { exportToExcel } from '../services/excelService';

interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isSendingToDocusign, setIsSendingToDocusign] = useState<string | null>(null);

  const filtered = exchanges.filter(e => 
    e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.delivered.serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDocuSign = (id: string) => {
    setIsSendingToDocusign(id);
    // Simulate API call
    setTimeout(() => {
      setIsSendingToDocusign(null);
      onNotify("PDF enviado para assinatura no DocuSign com sucesso!", "success");
    }, 2000);
  };

  const handleExcelExport = () => {
    if (exchanges.length === 0) {
      onNotify("Não há dados para exportar.", "error");
      return;
    }
    exportToExcel(exchanges);
    onNotify("Planilha Excel gerada e baixada.", "success");
  };

  if (exchanges.length === 0) {
    return (
      <div className="p-20 flex flex-col items-center justify-center text-center">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <ClipboardList className="text-slate-400" size={32} />
        </div>
        <h3 className="text-xl font-bold text-slate-800">Nenhum registro encontrado</h3>
        <p className="text-slate-500 mt-2 max-w-xs">Comece adicionando uma nova troca de equipamento no menu lateral.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text"
            placeholder="Buscar por nome, e-mail ou serial..."
            className="w-full pl-10 pr-4 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <button 
          onClick={handleExcelExport}
          className="flex items-center gap-2 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 px-4 py-2 rounded-xl border border-emerald-100 font-semibold transition-all"
        >
          <FileSpreadsheet size={18} />
          Exportar Excel
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50/50 border-b border-slate-100">
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Colaborador</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Ativo Entregue</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Ativo Devolvido</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Data</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(exchange => (
              <tr key={exchange.id} className="hover:bg-slate-50/80 transition-colors group">
                <td className="px-6 py-5">
                  <div className="flex flex-col">
                    <span className="font-semibold text-slate-800">{exchange.name}</span>
                    <span className="text-xs text-slate-500">{exchange.email}</span>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <div className="flex flex-col">
                    <span className="text-sm font-medium text-emerald-700">{exchange.delivered.brand} {exchange.delivered.model}</span>
                    <span className="text-xs text-slate-400 font-mono">SN: {exchange.delivered.serial}</span>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <div className="flex flex-col">
                    <span className="text-sm font-medium text-rose-700">{exchange.returned.brand} {exchange.returned.model}</span>
                    <span className="text-xs text-slate-400 font-mono">SN: {exchange.returned.serial}</span>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <span className="text-sm text-slate-600">{new Date(exchange.date + 'T00:00:00').toLocaleDateString('pt-BR')}</span>
                </td>
                <td className="px-6 py-5">
                  <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button 
                      title="Editar Registro"
                      onClick={() => onEdit(exchange)}
                      className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                    >
                      <Pencil size={18} />
                    </button>
                    <button 
                      title="Gerar PDF (Salvar/Imprimir)"
                      onClick={() => generateAssetPDF(exchange)}
                      className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
                    >
                      <FileDown size={18} />
                    </button>
                    <button 
                      title="Enviar para DocuSign"
                      disabled={isSendingToDocusign === exchange.id}
                      onClick={() => handleDocuSign(exchange.id)}
                      className={`p-2 rounded-lg transition-colors ${isSendingToDocusign === exchange.id ? 'text-slate-300 animate-pulse' : 'text-blue-600 hover:bg-blue-50'}`}
                    >
                      <Share2 size={18} />
                    </button>
                    <button 
                      title="Excluir Registro"
                      onClick={() => onDelete(exchange.id)}
                      className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {filtered.length === 0 && (
        <div className="p-10 text-center text-slate-500 italic">
          Nenhum resultado para "{searchTerm}"
        </div>
      )}
    </div>
  );
};

export default InventoryTable;

