import React, { useState } from 'react';
import { X, PenLine, Send, Loader2, ShieldCheck } from 'lucide-react';
import { AssetExchange } from '../types';

interface SenderSignatureModalProps {
  exchange: AssetExchange;
  onClose: () => void;
  onConfirm: (id: string) => void;
}

const SenderSignatureModal: React.FC<SenderSignatureModalProps> = ({ exchange, onClose, onConfirm }) => {
  const [step, setStep] = useState<'sign' | 'sending'>('sign');
  const [senderName, setSenderName] = useState('Responsável TI - AssetFlow');

  const handleSignAndSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!senderName.trim()) return;

    setStep('sending');
    // Simula o processamento do envelope DocuSign e envio de e-mail
    setTimeout(() => {
      onConfirm(exchange.id);
    }, 2500);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/80">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-100 text-blue-600 rounded-lg">
              <PenLine size={20} />
            </div>
            <h3 className="font-bold text-slate-800">Assinatura do Remetente</h3>
          </div>
          <button 
            onClick={onClose} 
            disabled={step === 'sending'}
            className="p-2 hover:bg-slate-200 rounded-xl transition-colors text-slate-500 disabled:opacity-30"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 'sign' ? (
            <form onSubmit={handleSignAndSend} className="space-y-6">
              <div className="p-4 bg-blue-50 border border-blue-100 rounded-2xl">
                <p className="text-sm text-blue-800 leading-relaxed">
                  Você está assinando como remetente o termo de troca para <strong>{exchange.name}</strong>.
                </p>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Digite sua Assinatura Digital</label>
                <div className="relative">
                  <input
                    autoFocus
                    type="text"
                    value={senderName}
                    onChange={(e) => setSenderName(e.target.value)}
                    placeholder="Seu nome ou cargo"
                    className="w-full h-24 bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl px-4 text-center font-serif text-2xl text-slate-700 focus:border-blue-500 focus:bg-white focus:outline-none transition-all"
                  />
                  <div className="absolute bottom-2 right-2 text-[10px] text-slate-300 flex items-center gap-1">
                    <ShieldCheck size={10} /> Autenticado via AssetFlow
                  </div>
                </div>
                {!senderName.trim() && (
                  <p className="text-[10px] text-rose-500">A assinatura não pode estar vazia.</p>
                )}
              </div>

              <p className="text-xs text-slate-500 text-center">
                Ao clicar no botão abaixo, sua assinatura será aplicada e o documento será enviado para <strong>{exchange.email}</strong> via DocuSign.
              </p>

              <button
                type="submit"
                disabled={!senderName.trim()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 group disabled:bg-slate-300 disabled:shadow-none"
              >
                <Send size={18} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
                Assinar e Enviar para Colaborador
              </button>
            </form>
          ) : (
            <div className="py-10 flex flex-col items-center justify-center text-center space-y-6">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center text-blue-600">
                  <Send size={32} className="animate-pulse" />
                </div>
              </div>
              <div className="space-y-2">
                <h4 className="font-bold text-slate-800 text-xl">Enviando Documento</h4>
                <p className="text-slate-500 text-sm max-w-[250px] mx-auto">
                  Estamos integrando sua assinatura e disparando o e-mail para o colaborador...
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SenderSignatureModal;

export enum EquipmentCondition {
  NEW = "Novo",
  USED = "Usado"
}

export interface Equipment {
  type: string;
  brand: string;
  model: string;
  serial: string;
  processor: string;
  condition: EquipmentCondition;
  memory: string;
}

export interface AssetExchange {
  id: string;
  name: string;
  email: string;
  date: string;
  delivered: Equipment;
  returned: Equipment;
  timestamp: number;
}

export interface MockEmail {
  id: string;
  to: string;
  subject: string;
  body: string;
  sentAt: number;
  read: boolean;
  exchangeId: string;
}

export type View = 'form' | 'inventory' | 'emails';

import React, { useState, useEffect } from 'react';
import { Layout, PlusCircle, ClipboardList, Database, LogOut, CheckCircle2, AlertCircle, Mail } from 'lucide-react';
import { View, AssetExchange, MockEmail } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';
import MockInbox from './components/MockInbox';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [emails, setEmails] = useState<MockEmail[]>([]);
  const [editingExchange, setEditingExchange] = useState<AssetExchange | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    const savedExchanges = localStorage.getItem('asset_exchanges');
    if (savedExchanges) setExchanges(JSON.parse(savedExchanges));

    const savedEmails = localStorage.getItem('asset_mock_emails');
    if (savedEmails) setEmails(JSON.parse(savedEmails));
  }, []);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  const handleSaveExchange = (exchange: AssetExchange) => {
    let updated: AssetExchange[];
    const isUpdate = exchanges.some(e => e.id === exchange.id);

    if (isUpdate) {
      updated = exchanges.map(e => e.id === exchange.id ? exchange : e);
      showNotification("Registro atualizado com sucesso!");
    } else {
      updated = [exchange, ...exchanges];
      showNotification("Registro de troca salvo com sucesso!");
    }

    setExchanges(updated);
    localStorage.setItem('asset_exchanges', JSON.stringify(updated));
    setEditingExchange(null);
    setCurrentView('inventory');
  };

  const handleSendEmail = (exchange: AssetExchange) => {
    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      to: exchange.email,
      subject: `DocuSign: Termo de Entrega de Equipamento - ${exchange.name}`,
      body: `Olá ${exchange.name},\n\nO Responsável de TI enviou um documento para sua assinatura referente à troca de equipamentos realizada em ${new Date(exchange.date).toLocaleDateString('pt-BR')}.\n\nEquipamento Entregue: ${exchange.delivered.brand} ${exchange.delivered.model} (SN: ${exchange.delivered.serial})\n\nPor favor, revise o documento em anexo e aplique sua assinatura digital.`,
      sentAt: Date.now(),
      read: false,
      exchangeId: exchange.id
    };

    const updatedEmails = [newEmail, ...emails];
    setEmails(updatedEmails);
    localStorage.setItem('asset_mock_emails', JSON.stringify(updatedEmails));
    showNotification(`E-mail simulado enviado para ${exchange.email}. Veja na aba E-mails!`, "success");
  };

  const handleEditExchange = (exchange: AssetExchange) => {
    setEditingExchange(exchange);
    setCurrentView('form');
