      <main className="flex-1 overflow-auto relative">
        {notification && (
          <div className={`fixed top-6 right-6 z-[200] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border animate-in slide-in-from-top-4 ${notification.type === 'success' ? 'bg-emerald-50 text-emerald-800 border-emerald-100' : 'bg-rose-50 text-rose-800 border-rose-100'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            <p className="font-medium">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto p-6 md:p-10">
          <header className="mb-8">
            <h2 className="text-3xl font-bold text-slate-900">
              {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
               currentView === 'inventory' ? 'Inventário' : 'Caixa de Entrada de Testes'}
            </h2>
          </header>

          <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
            {currentView === 'form' && (
              <AssetForm onSave={handleSaveExchange} editingExchange={editingExchange} onCancel={() => setCurrentView('inventory')} />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDeleteExchange} 
                onEdit={handleEditExchange} 
                onNotify={showNotification}
                onSendEmail={handleSendEmail}
              />
            )}
            {currentView === 'emails' && (
              <MockInbox emails={emails} onUpdateEmails={(updated) => {
                setEmails(updated);
                localStorage.setItem('asset_mock_emails', JSON.stringify(updated));
              }} />
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

