import React, { useState } from 'react';
import { AssetExchange } from '../types';
import { FileDown, Share2, Trash2, Search, FileSpreadsheet, ClipboardList, Pencil, PenLine } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';
import { exportToExcel } from '../services/excelService';
import SenderSignatureModal from './SenderSignatureModal';

interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
  onSendEmail: (exchange: AssetExchange) => void;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify, onSendEmail }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);

  const filtered = exchanges.filter(e => 
    e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.delivered.serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDocuSignComplete = (id: string) => {
    if (signingExchange) {
      onSendEmail(signingExchange);
    }
    setSigningExchange(null);
  };

  const handleExcelExport = () => {
    if (exchanges.length === 0) {
      onNotify("Não há dados para exportar.", "error");
      return;
    }
    exportToExcel(exchanges);
    onNotify("Planilha Excel gerada e baixada.", "success");
  };

  if (exchanges.length === 0) {
    return (
      <div className="p-20 flex flex-col items-center justify-center text-center">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <ClipboardList className="text-slate-400" size={32} />
        </div>
        <h3 className="text-xl font-bold text-slate-800">Nenhum registro encontrado</h3>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text"
            placeholder="Buscar..."
            className="w-full pl-10 pr-4 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button onClick={handleExcelExport} className="flex items-center gap-2 bg-emerald-50 text-emerald-700 px-4 py-2 rounded-xl border border-emerald-100 font-semibold">
          <FileSpreadsheet size={18} />
          Excel
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Colaborador</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Entregue</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Devolvido</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(exchange => (
              <tr key={exchange.id} className="hover:bg-slate-50/80 group">
                <td className="px-6 py-4">
                  <div className="flex flex-col">
                    <span className="font-semibold text-slate-800">{exchange.name}</span>
                    <span className="text-xs text-slate-500">{exchange.email}</span>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className="text-sm font-medium text-emerald-700">{exchange.delivered.brand}</span>
                </td>
                <td className="px-6 py-4">
                  <span className="text-sm font-medium text-rose-700">{exchange.returned.brand}</span>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100">
                    <button onClick={() => setSigningExchange(exchange)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><PenLine size={18} /></button>
                    <button onClick={() => onEdit(exchange)} className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Pencil size={18} /></button>
                    <button onClick={() => generateAssetPDF(exchange)} className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg"><FileDown size={18} /></button>
                    <button onClick={() => onDelete(exchange.id)} className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg"><Trash2 size={18} /></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {signingExchange && (
        <SenderSignatureModal 
          exchange={signingExchange}
          onClose={() => setSigningExchange(null)}
          onConfirm={handleDocuSignComplete}
        />
      )}
    </div>
  );
};

export default InventoryTable;

import React, { useState } from 'react';
import { MockEmail } from '../types';
import { Mail, Trash2, ChevronRight, User, Clock, Paperclip } from 'lucide-react';

interface MockInboxProps {
  emails: MockEmail[];
  onUpdateEmails: (emails: MockEmail[]) => void;
}

const MockInbox: React.FC<MockInboxProps> = ({ emails, onUpdateEmails }) => {
  const [selectedId, setSelectedId] = useState<string | null>(emails[0]?.id || null);

  const selectedEmail = emails.find(e => e.id === selectedId);

  const markAsRead = (id: string) => {
    const updated = emails.map(e => e.id === id ? { ...e, read: true } : e);
    onUpdateEmails(updated);
    setSelectedId(id);
  };

  const deleteEmail = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = emails.filter(e => e.id !== id);
    onUpdateEmails(updated);
    if (selectedId === id) setSelectedId(updated[0]?.id || null);
  };

  if (emails.length === 0) {
    return (
      <div className="p-20 flex flex-col items-center justify-center text-center bg-white h-[600px]">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <Mail className="text-slate-300" size={32} />
        </div>
        <h3 className="text-xl font-bold text-slate-800">Sua caixa de testes está vazia</h3>
        <p className="text-slate-500 mt-2 max-w-xs">Os e-mails disparados pelo DocuSign aparecerão aqui para validação visual.</p>
      </div>
    );
  }

  return (
    <div className="flex h-[700px] bg-white">
      {/* Sidebar List */}
      <div className="w-1/3 border-r border-slate-100 flex flex-col">
        <div className="p-4 bg-slate-50/50 border-b border-slate-100">
          <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Caixa de Entrada (Demo)</span>
        </div>
        <div className="flex-1 overflow-auto">
          {emails.map(email => (
            <div
              key={email.id}
              onClick={() => markAsRead(email.id)}
              className={`p-4 cursor-pointer border-b border-slate-50 transition-colors relative group ${selectedId === email.id ? 'bg-indigo-50/50' : 'hover:bg-slate-50'}`}
            >
              {!email.read && <div className="absolute left-1 top-1/2 -translate-y-1/2 w-1.5 h-1.5 bg-indigo-600 rounded-full"></div>}
              <div className="flex justify-between items-start mb-1">
                <span className={`text-sm ${!email.read ? 'font-bold text-slate-900' : 'text-slate-600'}`}>DocuSign</span>
                <span className="text-[10px] text-slate-400">{new Date(email.sentAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <h4 className={`text-xs truncate ${!email.read ? 'font-bold text-slate-800' : 'text-slate-500'}`}>{email.subject}</h4>
              <p className="text-xs text-slate-400 truncate mt-1">Para: {email.to}</p>

              <button 
                onClick={(e) => deleteEmail(email.id, e)}
                className="absolute right-2 bottom-2 p-1.5 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* Email Body */}
      <div className="flex-1 flex flex-col bg-white">
        {selectedEmail ? (
          <div className="flex flex-col h-full animate-in fade-in slide-in-from-right-2 duration-300">
            <div className="p-8 border-b border-slate-100">
              <h2 className="text-2xl font-bold text-slate-800 mb-6">{selectedEmail.subject}</h2>
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-indigo-600 rounded-full flex items-center justify-center text-white font-bold text-lg">
                  DS
                </div>
                <div className="flex-1">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-slate-900">DocuSign via AssetFlow</span>
                    <div className="flex items-center gap-1 text-xs text-slate-400">
                      <Clock size={12} />
                      {new Date(selectedEmail.sentAt).toLocaleString('pt-BR')}
                    </div>
                  </div>
                  <div className="text-sm text-slate-500">Para: {selectedEmail.to}</div>
                </div>
              </div>
            </div>

            <div className="flex-1 p-8 overflow-auto">
              <div className="max-w-2xl bg-white border border-slate-100 rounded-2xl shadow-sm p-8 whitespace-pre-wrap text-slate-700 leading-relaxed font-sans">
                {selectedEmail.body}

                <div className="mt-12 pt-8 border-t border-slate-100">
                  <p className="text-sm font-semibold text-slate-900 mb-4">Anexo (1):</p>
                  <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-xl border border-slate-200 w-fit group cursor-pointer hover:border-indigo-300 transition-colors">
