const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);

  const filtered = exchanges.filter(e => 
    e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.delivered.serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.returned.serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleDocuSignComplete = (id: string) => {
    onNotify(`Termo para ${signingExchange?.name} assinado e enviado para processamento.`, "success");
