                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Marca</label>
                <select className="w-full px-3 py-2 rounded-lg border" value={returned.brand} onChange={e => handleBrandChange(e.target.value, 'returned')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Modelo</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.model} onChange={e => setReturned({ ...returned, model: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">S/N / IMEI</label>
                <div className="relative">
                  <input required className="w-full pl-3 pr-10 py-2 rounded-lg border" value={returned.serial} onChange={e => setReturned({ ...returned, serial: e.target.value })} />
                  <button type="button" onClick={() => setScannerConfig({ isOpen: true, target: 'returned' })} className="absolute right-1 top-1/2 -translate-y-1/2 p-1.5 text-slate-400"><ScanLine size={18} /></button>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Processador</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.processor} onChange={e => setReturned({ ...returned, processor: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Memória (RAM)</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.memory} onChange={e => setReturned({ ...returned, memory: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tamanho do HD/SSD</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.storage} onChange={e => setReturned({ ...returned, storage: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Estado</label>
                <select className="w-full px-3 py-2 rounded-lg border" value={returned.condition} onChange={e => setReturned({ ...returned, condition: e.target.value as EquipmentCondition })}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
            </div>
            <div className="mt-6">
              <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Acessórios Devolvidos</label>
              <div className="grid grid-cols-2 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label key={acc} className="flex items-center gap-2 p-2 bg-white rounded-lg border cursor-pointer hover:bg-slate-50 transition-colors">
                    <input type="checkbox" checked={returned.accessories?.includes(acc)} onChange={() => handleAccessoryToggle(acc, 'returned')} className="rounded text-rose-600" />
                    <span className="text-xs font-medium text-slate-700">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>
        </div>

        <section>
          <SectionHeader icon={MousePointer2} title="Observações" color="bg-slate-700" />
          <textarea 
            className="w-full p-4 rounded-2xl border bg-slate-50 focus:bg-white transition-all h-24" 
            placeholder="Alguma observação adicional sobre o estado dos itens?"
            value={formData.observations}
            onChange={e => setFormData({ ...formData, observations: e.target.value })}
          />
        </section>

        <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
          <button type="submit" className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3.5 rounded-2xl font-bold shadow-xl transition-all">
            <Send size={20} />
            {editingExchange ? 'Atualizar Registro' : 'Salvar Registro de Troca'}
          </button>
        </div>
      </form>

      {scannerConfig.isOpen && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'delivered' ? 'Equipamento Entregue' : 'Equipamento Devolvido'}
          onScan={handleScanSuccess}
          onClose={() => setScannerConfig({ ...scannerConfig, isOpen: false })}
        />
      )}
    </>
  );
};

export default AssetForm;

import { jsPDF } from 'jspdf';
import { AssetExchange } from '../types';

export const generateAssetPDF = (exchange: AssetExchange) => {
  const doc = new jsPDF();
  const primaryColor = "#1a1a1a";
  const cirionBlue = "#2b3481";
  const cirionMagenta = "#e3007e";

  const drawCheckbox = (x: number, y: number, checked: boolean, label: string) => {
    doc.setDrawColor(cirionBlue);
    doc.rect(x, y - 3, 4, 4);
    if (checked) {
      doc.setFont("helvetica", "bold");
      doc.text("X", x + 0.8, y + 0.2);
    }
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.text(label, x + 6, y);
  };

  const drawField = (label: string, value: string, y: number) => {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.setTextColor(primaryColor);
    doc.text(`${label}:`, 20, y);

    // Campo visual (caixa de input)
    doc.setDrawColor(cirionBlue);
    doc.rect(45, y - 5, 140, 7);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(value || "", 48, y);
  };

  const generatePage = (type: 'Entrega' | 'Devolução', equipment: any) => {
    if (doc.internal.pages.length > 1) doc.addPage();

    // Header Logo Mockup
    doc.setFont("helvetica", "bold");
    doc.setFontSize(24);
    doc.setTextColor(cirionBlue);
    doc.text("cirion", 40, 25);
    doc.setDrawColor(cirionMagenta);
    doc.setLineWidth(1.5);
    doc.line(60, 18, 60, 26); // Detalhe do logo

    // Header Titles
    doc.setFontSize(11);
    doc.setTextColor(cirionBlue);
    doc.text("Declaração de Equipamento Cirion", 85, 20);

    drawCheckbox(85, 27, type === 'Entrega', "Entrega");
    drawCheckbox(105, 27, type === 'Devolução', "Devolução");

    // Declaration Text
    doc.setFontSize(9);
    doc.setTextColor(primaryColor);
    doc.setFont("helvetica", "normal");
    const intro = `Eu, ________________________________________________ declaro ter recebido/devolvido o equipamento e acessórios abaixo descritos, em perfeitas condições de funcionamento.`;
    doc.text(doc.splitTextToSize(intro, 170), 20, 45);
    doc.setFont("helvetica", "bold");
    doc.text(exchange.name, 26, 45); // Nome preenchido na linha

    // Technical Fields
    let currentY = 60;
    drawField("Tipo", equipment.type, currentY); currentY += 10;
    drawField("Marca", equipment.brand, currentY); currentY += 10;
    drawField("Modelo", equipment.model, currentY); currentY += 10;
    drawField("Número de Serie / Imei", equipment.serial, currentY); currentY += 10;
    drawField("Estado", equipment.condition.toUpperCase(), currentY); currentY += 10;

    // Grid Specs
    doc.setFont("helvetica", "bold");
    doc.text("Tamanho do HD:", 20, currentY);
    doc.rect(55, currentY - 5, 35, 7);
    doc.setFont("helvetica", "normal");
    doc.text(equipment.storage || "", 58, currentY);

    currentY += 10;
    doc.setFont("helvetica", "bold");
    doc.text("Processador:", 20, currentY);
    doc.rect(48, currentY - 5, 137, 7);
    doc.setFont("helvetica", "normal");
    doc.text(equipment.processor || "", 51, currentY);

    currentY += 10;
    doc.setFont("helvetica", "bold");
    doc.text("Memória:", 20, currentY);
    doc.rect(42, currentY - 5, 35, 7);
    doc.setFont("helvetica", "normal");
    doc.text(equipment.memory || "", 45, currentY);

    // Accessories Section
    currentY += 20;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Acessórios:", 90, currentY);

    const boxY = currentY + 5;
    doc.setDrawColor(cirionBlue);
    doc.setLineWidth(0.5);
    doc.rect(45, boxY, 115, 25);

    const accs = ["Mouse", "Teclado", "Headset", "Mochila", "DockStation", "Monitor"];
    accs.forEach((acc, i) => {
      const col = i % 2;
      const row = Math.floor(i / 2);
      drawCheckbox(65 + (col * 40), boxY + 8 + (row * 7), equipment.accessories?.includes(acc), acc);
    });

    // Observations
    currentY += 45;
    doc.setFont("helvetica", "bold");
    doc.text("Obs:", 20, currentY);
    doc.rect(35, currentY - 5, 150, 8);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.text(exchange.observations || "", 38, currentY);

    // Legal Terms
    currentY += 20;
    doc.setFontSize(8);
    const legalText = `_________________________________ compromete-se a usar e devolver os equipamentos e acessórios fornecidos pela empresa em perfeitas condições e com todas as informações, arquivos, contatos, arquivos de dados pessoais, e-mails, documentos de propriedades da Cirion Technologies. e / ou qualquer uma das suas filiais, no término do seu contrato de trabalho ou no final do período de autorização, sem as alterar, modificar, copiar, transferir, no estado em que foram entregues e sempre observando o princípio da confidencialidade. Se compromete em notificar o responsável de TI em caso de perda ou destruição do laptop, para que as medidas de segurança necessárias para a proteção de dados sejam aplicadas.`;
    const splitLegal = doc.splitTextToSize(legalText, 170);
    doc.text(splitLegal, 20, currentY);
    doc.setFont("helvetica", "bold");
    doc.text(exchange.name, 21, currentY);

    // Footer
    currentY += 35;
    const formattedDate = new Date(exchange.date + 'T00:00:00').toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' });
    doc.setFontSize(10);
    doc.text(`Data: ${formattedDate}`, 20, currentY);

    currentY += 25;
    doc.setLineWidth(0.2);
    doc.line(20, currentY, 90, currentY);
    doc.line(120, currentY, 190, currentY);

    doc.setFontSize(8);
    doc.text(exchange.name, 20, currentY + 4);
    doc.text("Responsável de TI", 120, currentY + 4);
  };

  // Gerar página de Entrega
  generatePage('Entrega', exchange.delivered);

  // Gerar página de Devolução
  generatePage('Devolução', exchange.returned);

  doc.save(`Termo_Cirion_${exchange.name.replace(/\s/g, '_')}.pdf`);
};

import { jsPDF } from 'jspdf';
import { AssetExchange, Equipment } from '../types';

export const generateAssetPDF = (exchange: AssetExchange) => {
  const doc = new jsPDF({
    orientation: 'p',
    unit: 'mm',
    format: 'a4'
  });

  const cirionBlue = "#2b3481";
  const cirionMagenta = "#e3007e";
  const textColor = "#000000";
  const borderColor = "#2b3481";

  const drawCheckbox = (x: number, y: number, checked: boolean, label: string) => {
    doc.setDrawColor(borderColor);
    doc.setLineWidth(0.3);
    doc.rect(x, y - 3.5, 4, 4);
    if (checked) {
      doc.setFont("helvetica", "bold");
      doc.setFontSize(10);
      doc.text("X", x + 0.8, y - 0.5);
    }
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(textColor);
    doc.text(label, x + 6, y - 0.5);
  };

  const drawLabeledField = (label: string, value: string, y: number, xStart: number = 20, width: number = 170) => {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.setTextColor(textColor);
    doc.text(label + ":", xStart, y);

    const labelWidth = doc.getTextWidth(label + ":") + 2;
    const fieldX = xStart + labelWidth;
    const fieldWidth = width - labelWidth;

    doc.setDrawColor(borderColor);
    doc.setLineWidth(0.3);
    doc.rect(fieldX, y - 5, fieldWidth, 7);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(11);
    doc.text(value || "", fieldX + 2, y);
  };

