    // Título e Checkboxes de topo
    doc.setFontSize(12);
    doc.setTextColor(cirionBlue);
    doc.text("Declaração de Equipamento Cirion", 70, 20);

    drawCheckbox(70, 28, type === 'Entrega', "Entrega");
    drawCheckbox(95, 28, type === 'Devolução', "Devolução");

    // 2. Texto de Abertura
    doc.setFontSize(10);
    doc.setTextColor(textColor);
    doc.setFont("helvetica", "normal");
    const introText = `Eu, ________________________________________________ declaro ter recebido/devolvido o equipamento e acessórios abaixo descritos, em perfeitas condições de funcionamento.`;
    doc.text(doc.splitTextToSize(introText, 175), 20, 45);
    // Nome preenchido na linha
    doc.setFont("helvetica", "bold");
    doc.text(exchange.name, 28, 45);

    // 3. Campos Técnicos (Grid vertical conforme imagem)
    let yPos = 60;
    drawLabeledField("Tipo", equipment.type, yPos); yPos += 10;
    drawLabeledField("Marca", equipment.brand.toUpperCase(), yPos); yPos += 10;
    drawLabeledField("Modelo", equipment.model, yPos); yPos += 10;
    drawLabeledField("Número de Serie / Imei", equipment.serial, yPos); yPos += 10;
    drawLabeledField("Estado", (equipment.condition || "USADO").toUpperCase(), yPos); yPos += 10;

    // Campos de tamanho variável
    // Tamanho do HD
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Tamanho do HD:", 20, yPos);
    doc.rect(55, yPos - 5, 35, 7);
    doc.setFont("helvetica", "normal");
    doc.text(equipment.storage || "", 57, yPos);
    yPos += 10;

    // Processador
    drawLabeledField("Processador", equipment.processor, yPos); yPos += 10;

    // Memória
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Memória:", 20, yPos);
    doc.rect(42, yPos - 5, 25, 7);
    doc.setFont("helvetica", "normal");
    doc.text(equipment.memory || "", 44, yPos);

    // 4. Seção de Acessórios
    yPos += 15;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(14);
    doc.text("Acessórios:", 85, yPos);

    yPos += 4;
    doc.setDrawColor(cirionBlue);
    doc.setLineWidth(0.4);
    doc.rect(45, yPos, 115, 25);

    const accessoriesList = [
      { label: "Mouse", x: 65, y: yPos + 7 },
      { label: "Teclado", x: 65, y: yPos + 14 },
      { label: "Headset", x: 65, y: yPos + 21 },
      { label: "Mochila", x: 110, y: yPos + 7 },
      { label: "DockStation", x: 110, y: yPos + 14 },
      { label: "Monitor", x: 110, y: yPos + 21 },
    ];

    accessoriesList.forEach(acc => {
      const isChecked = equipment.accessories?.includes(acc.label);
      drawCheckbox(acc.x, acc.y, isChecked, acc.label);
    });

    // 5. Observações
    yPos += 40;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Obs:", 20, yPos);
    doc.rect(32, yPos - 5, 158, 8);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(exchange.observations || "", 35, yPos);

    // 6. Texto Legal
    yPos += 20;
    doc.setFontSize(9);
    doc.setTextColor(textColor);
    const legalText = `_________________________________ compromete-se a usar e devolver os equipamentos e acessórios fornecidos pela empresa em perfeitas condições e com todas as informações, arquivos, contatos, arquivos de dados pessoais, e-mails, documentos de propriedades da Cirion Technologies. e / ou qualquer uma das suas filiais, no término do seu contrato de trabalho ou no final do período de autorização, sem as alterar, modificar, copiar, transferir, no estado em que foram entregues e sempre observando o princípio da confidencialidade. Se compromete em notificar o responsável de TI em caso de perda ou destruição do laptop, para que as medidas de segurança necessárias para a proteção de dados sejam aplicadas.`;
    const legalLines = doc.splitTextToSize(legalText, 170);
    doc.text(legalLines, 20, yPos);
    // Nome do usuário sobre a linha pontilhada do compromisso
    doc.setFont("helvetica", "bold");
    doc.text(exchange.name, 21, yPos);

    // 7. Data
    yPos += 35;
    const dateFormatted = new Date(exchange.date + 'T00:00:00').toLocaleDateString('pt-BR', { 
      day: 'numeric', 
      month: 'long', 
      year: 'numeric' 
    });
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.text(`Data: ${dateFormatted}`, 20, yPos);

    // 8. Assinaturas
    yPos += 25;
    doc.setLineWidth(0.3);
    doc.line(20, yPos, 90, yPos);   // Linha Colaborador
    doc.line(120, yPos, 190, yPos); // Linha TI

    doc.setFontSize(9);
    doc.setFont("helvetica", "bold");
    doc.text(exchange.name, 20, yPos + 5);
    doc.text("TI Cirion Technologies", 120, yPos + 5);
  };

  // Gerar primeira página (Entrega)
  renderEquipmentPage('Entrega', exchange.delivered);

  // Gerar segunda página (Devolução)
  renderEquipmentPage('Devolução', exchange.returned);

  // Download
  const filename = `Termo_Cirion_${exchange.name.replace(/\s+/g, '_')}.pdf`;
  doc.save(filename);
};

