    const accessoriesList = [
      { label: "Mouse", x: 60, y: yPos + 7 },
      { label: "Teclado", x: 60, y: yPos + 14 },
      { label: "Headset", x: 60, y: yPos + 21 },
      { label: "Mochila", x: 110, y: yPos + 7 },
