            <SectionHeader icon={History} title="Equipamento Devolvido" color="bg-rose-600" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tipo</label>
                <select className="w-full px-3 py-2 rounded-lg border" value={returned.type} onChange={e => setReturned({ ...returned, type: e.target.value })}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Marca</label>
                <select className="w-full px-3 py-2 rounded-lg border" value={returned.brand} onChange={e => handleBrandChange(e.target.value, 'returned')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Modelo</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.model} onChange={e => setReturned({ ...returned, model: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">S/N / IMEI</label>
                <div className="relative">
                  <input required className="w-full pl-3 pr-10 py-2 rounded-lg border" value={returned.serial} onChange={e => setReturned({ ...returned, serial: e.target.value })} />
                  <button type="button" onClick={() => setScannerConfig({ isOpen: true, target: 'returned' })} className="absolute right-1 top-1/2 -translate-y-1/2 p-1.5 text-slate-400"><ScanLine size={18} /></button>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Processador</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.processor} onChange={e => setReturned({ ...returned, processor: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Memória (RAM)</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.memory} onChange={e => setReturned({ ...returned, memory: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tamanho do HD/SSD</label>
                <input className="w-full px-3 py-2 rounded-lg border" value={returned.storage} onChange={e => setReturned({ ...returned, storage: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Estado</label>
                <select className="w-full px-3 py-2 rounded-lg border" value={returned.condition} onChange={e => setReturned({ ...returned, condition: e.target.value as EquipmentCondition })}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
            </div>
            <div className="mt-6">
              <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Acessórios Devolvidos</label>
              <div className="grid grid-cols-2 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label key={acc} className="flex items-center gap-2 p-2 bg-white rounded-lg border cursor-pointer hover:bg-slate-50 transition-colors">
                    <input type="checkbox" checked={returned.accessories?.includes(acc)} onChange={() => handleAccessoryToggle(acc, 'returned')} className="rounded text-rose-600" />
                    <span className="text-xs font-medium text-slate-700">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>
        </div>

        <section>
          <SectionHeader icon={MousePointer2} title="Observações" color="bg-slate-700" />
          <textarea 
            className="w-full p-4 rounded-2xl border bg-slate-50 focus:bg-white transition-all h-24" 
            placeholder="Alguma observação adicional sobre o estado dos itens?"
            value={formData.observations}
            onChange={e => setFormData({ ...formData, observations: e.target.value })}
          />
        </section>

        <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
          <button type="submit" className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3.5 rounded-2xl font-bold shadow-xl transition-all">
            <Send size={20} />
            {editingExchange ? 'Atualizar Registro' : 'Salvar Registro de Troca'}
          </button>
        </div>
      </form>

      {scannerConfig.isOpen && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'delivered' ? 'Equipamento Entregue' : 'Equipamento Devolvido'}
          onScan={handleScanSuccess}
          onClose={() => setScannerConfig({ ...scannerConfig, isOpen: false })}
        />
      )}
    </>
  );
};

export default AssetForm;

{
  "name": "AssetFlow - Gestão de Ativos",
  "description": "Um sistema robusto para gestão de troca de ativos (notebooks, smartphones, PCs), permitindo registro de entregas/devoluções, exportação para Excel e geração de termos em PDF para assinatura manual ou via DocuSign.",
  "requestFramePermissions": []
}

import React, { useState } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { FileDown, Trash2, Search, FileSpreadsheet, ClipboardList, Pencil, Mail, Laptop, Smartphone, Monitor, Cpu, CheckCircle2, Clock, Lock } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';
import { exportToExcel } from '../services/excelService';
import SenderSignatureModal from './SenderSignatureModal';

interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
  onSignSender: (id: string, signature: string) => void;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify, onSignSender }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);

  const filtered = exchanges.filter(e => 
    e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.delivered.serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.returned.serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSenderSignComplete = (id: string, signature: string) => {
    onSignSender(id, signature);
    setSigningExchange(null);
  };

  const getEquipmentIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('note')) return <Laptop size={14} />;
    if (t.includes('smart') || t.includes('phone')) return <Smartphone size={14} />;
    if (t.includes('monit')) return <Monitor size={14} />;
    return <Cpu size={14} />;
  };

  const StatusBadge = ({ status }: { status: string }) => {
    if (status === 'completed') return (
      <span className="flex items-center gap-1.5 px-2.5 py-1 bg-emerald-50 text-emerald-700 text-[10px] font-bold rounded-full border border-emerald-100">
        <CheckCircle2 size={12} /> CONCLUÍDO
      </span>
    );
    if (status === 'pending_receiver') return (
      <span className="flex items-center gap-1.5 px-2.5 py-1 bg-amber-50 text-amber-700 text-[10px] font-bold rounded-full border border-amber-100">
        <Clock size={12} /> AGUARDANDO COLAB.
      </span>
    );
    return (
      <span className="flex items-center gap-1.5 px-2.5 py-1 bg-slate-100 text-slate-500 text-[10px] font-bold rounded-full border border-slate-200">
        RASCUNHO
      </span>
    );
  };

  if (exchanges.length === 0) {
    return (
      <div className="p-20 flex flex-col items-center justify-center text-center">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <ClipboardList className="text-slate-400" size={32} />
        </div>
        <h3 className="text-xl font-bold text-slate-800">Nenhum registro encontrado</h3>
        <p className="text-slate-500 mt-2">Inicie uma nova troca para popular seu inventário.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text"
            placeholder="Buscar por nome ou serial..."
            className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => exportToExcel(exchanges)} 
          className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-emerald-600/10 transition-all"
        >
          <FileSpreadsheet size={18} />
          Exportar Excel
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest">Nome / Status</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest">Ativo Entregue</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest">Ativo Devolvido</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest text-center">DATA DA TROCA</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(exchange => (
              <tr key={exchange.id} className="hover:bg-slate-50/50 group transition-colors">
                <td className="px-6 py-5 align-middle">
                  <div className="flex flex-col gap-2">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 leading-tight">{exchange.name}</span>
                      <span className="text-[10px] text-slate-400 truncate max-w-[150px]">{exchange.email}</span>
                    </div>
                    <StatusBadge status={exchange.status} />
                  </div>
                </td>

                <td className="px-6 py-5 align-middle">
                  <div className="flex flex-col gap-1">
                    <span className="flex items-center gap-1 text-[10px] font-bold text-emerald-600 uppercase">
                      {getEquipmentIcon(exchange.delivered.type)}
                      {exchange.delivered.type}
                    </span>
                    <div className="text-sm font-semibold text-slate-800">
                      {exchange.delivered.brand} {exchange.delivered.model}
                    </div>
                    <div className="text-[10px] text-indigo-700 font-mono bg-indigo-50 px-2 py-0.5 rounded w-fit">S/N: {exchange.delivered.serial}</div>
                  </div>
                </td>

                <td className="px-6 py-5 align-middle">
                  <div className="flex flex-col gap-1">
                    <span className="flex items-center gap-1 text-[10px] font-bold text-rose-600 uppercase">
                      {getEquipmentIcon(exchange.returned.type)}
                      {exchange.returned.type}
                    </span>
                    <div className="text-sm font-semibold text-slate-700">
                      {exchange.returned.brand} {exchange.returned.model}
                    </div>
                    <div className="text-[10px] text-slate-600 font-mono bg-slate-100 px-2 py-0.5 rounded w-fit">S/N: {exchange.returned.serial}</div>
                  </div>
                </td>

                <td className="px-6 py-5 align-middle text-center">
                  <span className="text-sm font-bold text-slate-700">
                    {new Date(exchange.date + 'T00:00:00').toLocaleDateString('pt-BR')}
                  </span>
                </td>

                <td className="px-6 py-5 align-middle text-right">
                  <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    {exchange.status === 'draft' && (
                      <button 
                        onClick={() => setSigningExchange(exchange)} 
                        className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-xl transition-colors"
                        title="Assinar e Enviar Outlook"
                      >
                        <Mail size={18} />
                      </button>
                    )}

                    {exchange.status !== 'completed' ? (
                      <button 
                        onClick={() => onEdit(exchange)} 
                        className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors"
                        title="Editar"
                      >
                        <Pencil size={18} />
                      </button>
                    ) : (
                      <div className="p-2.5 text-slate-300 cursor-not-allowed" title="Edição bloqueada (Documento assinado)">
                        <Lock size={18} />
                      </div>
                    )}

                    <button 
                      onClick={() => generateAssetPDF(exchange)} 
                      className="p-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors"
                      title="Baixar PDF"
                    >
                      <FileDown size={18} />
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); onDelete(exchange.id); }} 
                      className="p-2.5 text-rose-600 hover:bg-rose-50 rounded-xl transition-colors"
                      title="Excluir"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="p-6 bg-slate-50 border-t border-slate-100 text-[10px] text-slate-400 flex justify-between items-center">
        <p>Total de trocas: <strong>{filtered.length}</strong></p>
        <p>AssetFlow - Sistema de Gestão de Ativos</p>
      </div>

      {signingExchange && (
        <SenderSignatureModal 
          exchange={signingExchange}
          onClose={() => setSigningExchange(null)}
          onConfirm={handleSenderSignComplete}
        />
      )}
    </div>
  );
};

export default InventoryTable;

import React, { useState, useEffect, useMemo } from 'react';
import { Equipment, AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS } from '../constants';
import { User, Package, History, Send, ScanLine, X, MousePointer2, Clock, Lock, AlertCircle } from 'lucide-react';
import BarcodeScannerModal from './BarcodeScannerModal';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = [
  "Mouse", "Teclado", "Headset", "Mochila", "DockStation", "Monitor"
];

const initialEquipment: Equipment = {
  type: EQUIPMENT_TYPES[0],
  brand: BRANDS[0],
  model: MODELS[BRANDS[0]][0],
  serial: '',
  processor: '',
  condition: EquipmentCondition.NEW,
  memory: '',
  storage: '',
  accessories: []
};

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel, exchanges = [] }) => {
  const isReadOnly = editingExchange?.status === 'completed';

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    date: new Date().toISOString().split('T')[0],
    observations: ''
  });

  const [delivered, setDelivered] = useState<Equipment>({ ...initialEquipment });
  const [returned, setReturned] = useState<Equipment>({ ...initialEquipment, condition: EquipmentCondition.USED });

  const [scannerConfig, setScannerConfig] = useState<{ isOpen: boolean; target: 'delivered' | 'returned' }>({
    isOpen: false,
    target: 'delivered'
  });

  // Histórico de pessoas (Nome + Email) extraído dos registros existentes
  const peopleHistory = useMemo(() => {
    const historyMap = new Map<string, string>();
    exchanges.forEach(ex => {
      if (ex.email && ex.name) {
        historyMap.set(ex.email.toLowerCase(), ex.name);
      }
    });

    return Array.from(historyMap.entries())
      .map(([email, name]) => ({ email, name }))
      .sort((a, b) => a.name.localeCompare(b.name)); 
  }, [exchanges]);

  useEffect(() => {
    if (editingExchange) {
      setFormData({
        name: editingExchange.name,
        email: editingExchange.email,
        date: editingExchange.date,
        observations: editingExchange.observations || ''
      });
      setDelivered({ ...editingExchange.delivered });
      setReturned({ ...editingExchange.returned });
    } else {
      setFormData({
        name: '',
        email: '',
        date: new Date().toISOString().split('T')[0],
        observations: ''
      });
      setDelivered({ ...initialEquipment });
      setReturned({ ...initialEquipment, condition: EquipmentCondition.USED });
    }
  }, [editingExchange]);

  const handleBrandChange = (brand: string, type: 'delivered' | 'returned') => {
    if (isReadOnly) return;
    const models = MODELS[brand] || ["Outro"];
    if (type === 'delivered') {
      setDelivered({ ...delivered, brand, model: models[0] });
    } else {
      setReturned({ ...returned, brand, model: models[0] });
    }
  };

  const handleAccessoryToggle = (acc: string, type: 'delivered' | 'returned') => {
    if (isReadOnly) return;
    if (type === 'delivered') {
      const current = delivered.accessories || [];
      const updated = current.includes(acc) ? current.filter(item => item !== acc) : [...current, acc];
      setDelivered({ ...delivered, accessories: updated });
    } else {
      const current = returned.accessories || [];
      const updated = current.includes(acc) ? current.filter(item => item !== acc) : [...current, acc];
      setReturned({ ...returned, accessories: updated });
    }
  };

  const handleEmailChange = (email: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({ ...prev, email }));
    const match = peopleHistory.find(h => h.email.toLowerCase() === email.toLowerCase());
    if (match) {
      setFormData(prev => ({ ...prev, name: match.name }));
    }
  };

  const handleNameChange = (name: string) => {
    if (isReadOnly) return;
    setFormData(prev => ({ ...prev, name }));
    const match = peopleHistory.find(h => h.name.toLowerCase() === name.toLowerCase());
    if (match) {
      setFormData(prev => ({ ...prev, email: match.email }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (isReadOnly) return;
    const exchange: AssetExchange = {
      id: editingExchange ? editingExchange.id : Math.random().toString(36).substr(2, 9).toUpperCase(),
      ...formData,
      delivered,
      returned,
      timestamp: editingExchange ? editingExchange.timestamp : Date.now(),
      status: editingExchange ? editingExchange.status : 'draft'
    };
    onSave(exchange);
  };

  const handleScanSuccess = (text: string) => {
    if (isReadOnly) return;
    const processedText = text.trim().slice(-8);
    if (scannerConfig.target === 'delivered') {
      setDelivered({ ...delivered, serial: processedText });
    } else {
      setReturned({ ...returned, serial: processedText });
    }
    setScannerConfig({ ...scannerConfig, isOpen: false });
  };

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-6 pb-2 border-b border-slate-100">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={20} className="text-white" />
      </div>
      <h3 className="text-lg font-semibold text-slate-800">{title}</h3>
    </div>
  );

  return (
    <>
      <form onSubmit={handleSubmit} className="p-8 space-y-12 relative">
        {isReadOnly && (
          <div className="bg-amber-50 border border-amber-200 p-4 rounded-2xl flex items-center gap-4 mb-8 animate-in fade-in slide-in-from-top-4">
            <div className="bg-amber-100 p-2 rounded-full text-amber-700">
              <Lock size={20} />
            </div>
            <div>
              <p className="font-bold text-amber-900 text-sm">Registro Bloqueado</p>
              <p className="text-amber-800 text-xs">Este documento já foi assinado por ambas as partes e não pode mais ser editado para garantir a integridade do termo.</p>
            </div>
          </div>
        )}

        <section>
          <SectionHeader icon={User} title="Dados do Colaborador" color="bg-indigo-600" />
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Nome Completo</label>
              <div className="relative">
                <input 
                  disabled={isReadOnly}
                  required
                  list="name-history-list"
                  className={`w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 bg-slate-50 transition-all ${isReadOnly ? 'opacity-70 cursor-not-allowed' : ''}`}
                  value={formData.name}
                  onChange={e => handleNameChange(e.target.value)}
                  placeholder="Ex: Gilberto Araujo"
                />
                {!isReadOnly && (
                  <datalist id="name-history-list">
                    {peopleHistory.map(h => (
                      <option key={`name-${h.email}`} value={h.name}>{h.email}</option>
                    ))}
                  </datalist>
                )}
                <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-300">
                   <Clock size={16} />
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">E-mail Corporativo</label>
              <div className="relative">
                <input 
                  disabled={isReadOnly}
                  required
                  type="email"
                  list="email-history-list"
                  className={`w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 bg-slate-50 transition-all ${isReadOnly ? 'opacity-70 cursor-not-allowed' : ''}`}
                  value={formData.email}
                  onChange={e => handleEmailChange(e.target.value)}
                  placeholder="usuario@cirion.com"
                />
                {!isReadOnly && (
                  <datalist id="email-history-list">
                    {peopleHistory.map(h => (
                      <option key={`email-${h.email}`} value={h.email}>{h.name}</option>
                    ))}
                  </datalist>
                )}
                <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-300">
                   <Clock size={16} />
                </div>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Data da Troca</label>
              <input 
                disabled={isReadOnly}
                required
                type="date"
                className={`w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 bg-slate-50 ${isReadOnly ? 'opacity-70 cursor-not-allowed' : ''}`}
                value={formData.date}
                onChange={e => setFormData({ ...formData, date: e.target.value })}
              />
            </div>
          </div>
          {!isReadOnly && (
            <p className="text-[10px] text-slate-400 mt-2 px-1">
              * O histórico sugere dados baseados em trocas anteriores, priorizando o nome completo.
            </p>
          )}
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
          {/* Delivered */}
          <section className="p-6 rounded-2xl bg-slate-50 border border-slate-100">
            <SectionHeader icon={Package} title="Equipamento Entregue" color="bg-emerald-600" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tipo</label>
                <select disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white" value={delivered.type} onChange={e => setDelivered({ ...delivered, type: e.target.value })}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
