              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">S/N / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly} required className="w-full pl-3 pr-10 py-2 rounded-lg border bg-white text-slate-900 font-mono" value={delivered.serial} onChange={e => setDelivered({ ...delivered, serial: e.target.value })} />
                  {!isReadOnly && (
                    <button type="button" onClick={() => setScannerConfig({ isOpen: true, target: 'delivered' })} className="absolute right-1 top-1/2 -translate-y-1/2 p-1.5 text-slate-400"><ScanLine size={18} /></button>
                  )}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Processador</label>
                <input disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={delivered.processor} onChange={e => setDelivered({ ...delivered, processor: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Memória (RAM)</label>
                <input disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={delivered.memory} onChange={e => setDelivered({ ...delivered, memory: e.target.value })} placeholder="Ex: 32GB" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tamanho do HD/SSD</label>
                <input disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={delivered.storage} onChange={e => setDelivered({ ...delivered, storage: e.target.value })} placeholder="Ex: 1TB" />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Estado</label>
                <select disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={delivered.condition} onChange={e => setDelivered({ ...delivered, condition: e.target.value as EquipmentCondition })}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
            </div>
            <div className="mt-6">
              <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Acessórios Entregues</label>
