                <label className="text-xs font-bold text-slate-500 uppercase">Modelo</label>
                <input disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={returned.model} onChange={e => setReturned({ ...returned, model: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">S/N / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly} required className="w-full pl-3 pr-10 py-2 rounded-lg border bg-white text-slate-900 font-mono" value={returned.serial} onChange={e => setReturned({ ...returned, serial: e.target.value })} />
                  {!isReadOnly && (
                    <button type="button" onClick={() => setScannerConfig({ isOpen: true, target: 'returned' })} className="absolute right-1 top-1/2 -translate-y-1/2 p-1.5 text-slate-400"><ScanLine size={18} /></button>
                  )}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Processador</label>
                <input disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={returned.processor} onChange={e => setReturned({ ...returned, processor: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Memória (RAM)</label>
                <input disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={returned.memory} onChange={e => setReturned({ ...returned, memory: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tamanho do HD/SSD</label>
                <input disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={returned.storage} onChange={e => setReturned({ ...returned, storage: e.target.value })} />
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Estado</label>
                <select disabled={isReadOnly} className="w-full px-3 py-2 rounded-lg border bg-white text-slate-900" value={returned.condition} onChange={e => setReturned({ ...returned, condition: e.target.value as EquipmentCondition })}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
            </div>
            <div className="mt-6">
              <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Acessórios Devolvidos</label>
              <div className="grid grid-cols-2 gap-2">
