                  <label key={acc} className={`flex items-center gap-2 p-2 bg-white rounded-lg border ${isReadOnly ? 'cursor-not-allowed' : 'cursor-pointer hover:bg-slate-50'} transition-colors`}>
                    <input disabled={isReadOnly} type="checkbox" checked={returned.accessories?.includes(acc)} onChange={() => handleAccessoryToggle(acc, 'returned')} className="rounded text-rose-600" />
                    <span className="text-xs font-medium text-slate-700">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>
        </div>

        <section>
          <SectionHeader icon={MousePointer2} title="Observações" color="bg-slate-700" />
          <textarea 
            disabled={isReadOnly}
            className={`w-full p-4 rounded-2xl border bg-white text-slate-900 focus:ring-2 focus:ring-indigo-500 transition-all h-24 ${isReadOnly ? 'opacity-70 cursor-not-allowed' : ''}`} 
            placeholder="Alguma observação adicional sobre o estado dos itens?"
            value={formData.observations}
            onChange={e => setFormData({ ...formData, observations: e.target.value })}
          />
        </section>

        <div className="pt-8 border-t border-slate-100 flex justify-end gap-4">
          <button 
            type="button" 
            onClick={onCancel}
            className="px-8 py-3.5 rounded-2xl font-bold text-slate-500 hover:bg-slate-100 transition-all"
          >
            Voltar
          </button>
          {!isReadOnly && (
            <button type="submit" className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3.5 rounded-2xl font-bold shadow-xl transition-all">
              <Send size={20} />
              {editingExchange ? 'Atualizar Registro' : 'Salvar Registro de Troca'}
            </button>
          )}
        </div>
      </form>

      {scannerConfig.isOpen && !isReadOnly && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'delivered' ? 'Equipamento Entregue' : 'Equipamento Devolvido'}
          onScan={handleScanSuccess}
          onClose={() => setScannerConfig({ ...scannerConfig, isOpen: false })}
        />
      )}
    </>
  );
};

