import React, { useState } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { FileDown, Trash2, Search, FileSpreadsheet, ClipboardList, Pencil, Mail, Laptop, Smartphone, Monitor, Cpu, CheckCircle2, Clock, Lock } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';
import { exportToExcel } from '../services/excelService';
import SenderSignatureModal from './SenderSignatureModal';

interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
  onSignSender: (id: string, signature: string) => void;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify, onSignSender }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);

  const filtered = exchanges.filter(e => 
    e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.delivered.serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.returned.serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSenderSignComplete = (id: string, signature: string) => {
    onSignSender(id, signature);
    setSigningExchange(null);
  };

  const getEquipmentIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('note')) return <Laptop size={14} />;
    if (t.includes('smart') || t.includes('phone')) return <Smartphone size={14} />;
    if (t.includes('monit')) return <Monitor size={14} />;
    return <Cpu size={14} />;
  };

  const StatusBadge = ({ status }: { status: string }) => {
    if (status === 'completed') return (
      <span className="flex items-center gap-1.5 px-2.5 py-1 bg-emerald-50 text-emerald-700 text-[10px] font-bold rounded-full border border-emerald-100">
        <CheckCircle2 size={12} /> CONCLUÍDO
      </span>
    );
    if (status === 'pending_receiver') return (
      <span className="flex items-center gap-1.5 px-2.5 py-1 bg-amber-50 text-amber-700 text-[10px] font-bold rounded-full border border-amber-100">
        <Clock size={12} /> AGUARDANDO COLAB.
      </span>
    );
    return (
      <span className="flex items-center gap-1.5 px-2.5 py-1 bg-slate-100 text-slate-500 text-[10px] font-bold rounded-full border border-slate-200">
        RASCUNHO
      </span>
    );
  };

  if (exchanges.length === 0) {
    return (
      <div className="p-20 flex flex-col items-center justify-center text-center">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <ClipboardList className="text-slate-400" size={32} />
        </div>
        <h3 className="text-xl font-bold text-slate-800">Nenhum registro encontrado</h3>
        <p className="text-slate-500 mt-2">Inicie uma nova troca para popular seu inventário.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text"
            placeholder="Buscar por nome ou serial..."
            className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 bg-white text-slate-900 outline-none transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => exportToExcel(exchanges)} 
          className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-emerald-600/10 transition-all"
        >
          <FileSpreadsheet size={18} />
          Exportar Excel
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest">Nome / Status</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest">Ativo Entregue</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest">Ativo Devolvido</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest text-center">DATA DA TROCA</th>
              <th className="px-6 py-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map(exchange => (
              <tr key={exchange.id} className="hover:bg-slate-50/50 group transition-colors">
                <td className="px-6 py-5 align-middle">
                  <div className="flex flex-col gap-2">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 leading-tight">{exchange.name}</span>
                      <span className="text-[10px] text-slate-400 truncate max-w-[150px]">{exchange.email}</span>
                    </div>
                    <StatusBadge status={exchange.status} />
                  </div>
                </td>

                <td className="px-6 py-5 align-middle">
                  <div className="flex flex-col gap-1">
                    <span className="flex items-center gap-1 text-[10px] font-bold text-emerald-600 uppercase">
                      {getEquipmentIcon(exchange.delivered.type)}
                      {exchange.delivered.type}
                    </span>
                    <div className="text-sm font-semibold text-slate-800">
                      {exchange.delivered.brand} {exchange.delivered.model}
                    </div>
                    <div className="text-[10px] text-indigo-700 font-mono bg-indigo-50 px-2 py-0.5 rounded w-fit">S/N: {exchange.delivered.serial}</div>
                  </div>
                </td>

                <td className="px-6 py-5 align-middle">
                  <div className="flex flex-col gap-1">
                    <span className="flex items-center gap-1 text-[10px] font-bold text-rose-600 uppercase">
                      {getEquipmentIcon(exchange.returned.type)}
                      {exchange.returned.type}
                    </span>
                    <div className="text-sm font-semibold text-slate-700">
                      {exchange.returned.brand} {exchange.returned.model}
                    </div>
                    <div className="text-[10px] text-slate-600 font-mono bg-slate-100 px-2 py-0.5 rounded w-fit">S/N: {exchange.returned.serial}</div>
                  </div>
                </td>

                <td className="px-6 py-5 align-middle text-center">
                  <span className="text-sm font-bold text-slate-700">
                    {new Date(exchange.date + 'T00:00:00').toLocaleDateString('pt-BR')}
                  </span>
                </td>

                <td className="px-6 py-5 align-middle text-right">
                  <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    {exchange.status === 'draft' && (
                      <button 
                        onClick={() => setSigningExchange(exchange)} 
                        className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-xl transition-colors"
                        title="Assinar e Enviar Outlook"
                      >
                        <Mail size={18} />
                      </button>
                    )}

                    {exchange.status !== 'completed' ? (
                      <button 
                        onClick={() => onEdit(exchange)} 
                        className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors"
                        title="Editar"
                      >
                        <Pencil size={18} />
                      </button>
                    ) : (
                      <div className="p-2.5 text-slate-300 cursor-not-allowed" title="Edição bloqueada (Documento assinado)">
                        <Lock size={18} />
                      </div>
                    )}

                    <button 
                      onClick={() => generateAssetPDF(exchange)} 
                      className="p-2.5 text-slate-600 hover:bg-slate-100 rounded-xl transition-colors"
                      title="Baixar PDF"
                    >
                      <FileDown size={18} />
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); onDelete(exchange.id); }} 
                      className="p-2.5 text-rose-600 hover:bg-rose-50 rounded-xl transition-colors"
                      title="Excluir"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="p-6 bg-slate-50 border-t border-slate-100 text-[10px] text-slate-400 flex justify-between items-center">
        <p>Total de trocas: <strong>{filtered.length}</strong></p>
        <p>AssetFlow - Sistema de Gestão de Ativos</p>
      </div>

      {signingExchange && (
        <SenderSignatureModal 
          exchange={signingExchange}
          onClose={() => setSigningExchange(null)}
          onConfirm={handleSenderSignComplete}
        />
      )}
    </div>
  );
};

export default InventoryTable;

import React, { useState } from 'react';
import { X, PenLine, Send, Loader2, ShieldCheck, Mail } from 'lucide-react';
import { AssetExchange } from '../types';

interface SenderSignatureModalProps {
  exchange: AssetExchange;
  onClose: () => void;
  onConfirm: (id: string, signature: string) => void;
}

const SenderSignatureModal: React.FC<SenderSignatureModalProps> = ({ exchange, onClose, onConfirm }) => {
  const [step, setStep] = useState<'sign' | 'sending'>('sign');
  const [senderSignature, setSenderSignature] = useState('Gilberto Araujo');

  const handleSignAndSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!senderSignature.trim()) return;

    setStep('sending');
    // Simula o processamento e "envio via Outlook"
    setTimeout(() => {
      onConfirm(exchange.id, senderSignature);
    }, 2000);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-white">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 text-white rounded-lg shadow-lg shadow-blue-200">
              <Mail size={20} />
            </div>
            <div>
              <h3 className="font-bold text-slate-800 leading-none">Outlook AssetFlow</h3>
              <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-wider font-bold">Assinatura de TI</p>
            </div>
          </div>
          <button 
            onClick={onClose} 
            disabled={step === 'sending'}
            className="p-2 hover:bg-slate-100 rounded-xl transition-colors text-slate-500 disabled:opacity-30"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 'sign' ? (
            <form onSubmit={handleSignAndSend} className="space-y-6">
              <div className="p-4 bg-blue-50 border border-blue-100 rounded-2xl">
                <p className="text-sm text-blue-800 leading-relaxed">
                  Ao assinar, o sistema anexará o PDF no seu Outlook e enviará para <strong>{exchange.email}</strong> solicitando a assinatura do colaborador.
                </p>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Sua Assinatura (TI)</label>
                <div className="relative">
                  <input
                    autoFocus
                    type="text"
                    value={senderSignature}
                    onChange={(e) => setSenderSignature(e.target.value)}
                    placeholder="Seu nome completo"
                    className="w-full h-24 bg-white border-2 border-dashed border-slate-200 rounded-xl px-4 text-center font-serif text-3xl text-indigo-900 focus:border-blue-500 focus:bg-white focus:outline-none transition-all italic"
                  />
                  <div className="absolute bottom-2 right-2 text-[10px] text-slate-300 flex items-center gap-1">
                    <ShieldCheck size={10} /> Validado pela Infra TI
                  </div>
                </div>
              </div>

              <button
                type="submit"
                disabled={!senderSignature.trim()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 group disabled:bg-slate-300"
              >
                <Send size={18} className="group-hover:translate-x-1 transition-transform" />
                Assinar e Enviar via Outlook
              </button>
            </form>
          ) : (
            <div className="py-10 flex flex-col items-center justify-center text-center space-y-6">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-blue-50 border-t-blue-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center text-blue-600">
                  <Mail size={32} className="animate-pulse" />
                </div>
              </div>
              <div className="space-y-2">
                <h4 className="font-bold text-slate-800 text-xl">Integração Outlook</h4>
                <p className="text-slate-500 text-sm max-w-[250px] mx-auto">
                  Gerando PDF assinado e disparando e-mail para o colaborador...
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SenderSignatureModal;

import React, { useState } from 'react';
import { MockEmail, AssetExchange } from '../types';
import { Mail, Trash2, Clock, Paperclip, PenLine, ShieldCheck, X } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';

interface MockInboxProps {
  emails: MockEmail[];
  exchanges: AssetExchange[];
  onUpdateEmails: (emails: MockEmail[]) => void;
  onSignReceiver: (id: string, signature: string) => void;
}

const MockInbox: React.FC<MockInboxProps> = ({ emails, onUpdateEmails, exchanges, onSignReceiver }) => {
  const [selectedId, setSelectedId] = useState<string | null>(emails[0]?.id || null);
  const [signingExchangeId, setSigningExchangeId] = useState<string | null>(null);
  const [receiverSignature, setReceiverSignature] = useState('');

  const selectedEmail = emails.find(e => e.id === selectedId);
  const currentExchange = exchanges.find(ex => ex.id === selectedEmail?.exchangeId);

  const markAsRead = (id: string) => {
    const updated = emails.map(e => e.id === id ? { ...e, read: true } : e);
    onUpdateEmails(updated);
    setSelectedId(id);
  };

  const handleReceiverSign = (e: React.FormEvent) => {
    e.preventDefault();
    if (!receiverSignature.trim() || !signingExchangeId) return;

    onSignReceiver(signingExchangeId, receiverSignature);
    setSigningExchangeId(null);
    setReceiverSignature('');
  };

  if (emails.length === 0) {
    return (
      <div className="p-20 flex flex-col items-center justify-center text-center bg-white h-[600px]">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <Mail className="text-slate-300" size={32} />
        </div>
        <h3 className="text-xl font-bold text-slate-800">Sua caixa do Outlook está vazia</h3>
        <p className="text-slate-500 mt-2 max-w-xs">E-mails de termos enviados para assinatura aparecerão aqui.</p>
      </div>
    );
  }

  return (
    <div className="flex h-[700px] bg-white text-slate-900">
      {/* Sidebar List */}
      <div className="w-1/3 border-r border-slate-100 flex flex-col">
        <div className="p-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Inbox - Outlook</span>
        </div>
        <div className="flex-1 overflow-auto">
          {emails.map(email => (
            <div
              key={email.id}
              onClick={() => markAsRead(email.id)}
              className={`p-4 cursor-pointer border-b border-slate-50 transition-colors relative group ${selectedId === email.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
            >
              {!email.read && <div className="absolute left-1 top-1/2 -translate-y-1/2 w-1.5 h-1.5 bg-blue-600 rounded-full"></div>}
              <div className="flex justify-between items-start mb-1">
                <span className={`text-xs truncate max-w-[120px] ${!email.read ? 'font-bold text-slate-900' : 'text-slate-600'}`}>{email.from.split('<')[0]}</span>
                <span className="text-[10px] text-slate-400">{new Date(email.sentAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <h4 className={`text-xs truncate ${!email.read ? 'font-bold text-slate-800' : 'text-slate-500'}`}>{email.subject}</h4>

              <button 
                onClick={(e) => { e.stopPropagation(); onUpdateEmails(emails.filter(em => em.id !== email.id)); }}
                className="absolute right-2 bottom-2 p-1.5 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* Email Body */}
      <div className="flex-1 flex flex-col bg-white">
        {selectedEmail ? (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            <div className="p-8 border-b border-slate-100 bg-slate-50">
              <h2 className="text-2xl font-bold text-slate-800 mb-6">{selectedEmail.subject}</h2>
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold text-lg shadow-lg">
                  {selectedEmail.from.charAt(0)}
                </div>
                <div className="flex-1">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-slate-900">{selectedEmail.from}</span>
                    <div className="flex items-center gap-1 text-xs text-slate-400">
                      <Clock size={12} />
                      {new Date(selectedEmail.sentAt).toLocaleString('pt-BR')}
                    </div>
                  </div>
                  <div className="text-sm text-slate-500 font-medium">Para: Você ({selectedEmail.to})</div>
                </div>
              </div>
            </div>

            <div className="flex-1 p-8 overflow-auto">
              <div className="max-w-2xl bg-white border border-slate-100 rounded-2xl shadow-sm p-8 whitespace-pre-wrap text-slate-700 leading-relaxed font-sans">
                {selectedEmail.body}

                {selectedEmail.attachment && currentExchange && (
                  <div className="mt-12 pt-8 border-t border-slate-100">
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Anexo Seguro (PDF):</p>
                    <div 
                      onClick={() => generateAssetPDF(currentExchange)}
                      className="flex items-center gap-3 p-4 bg-slate-50 rounded-xl border border-slate-200 w-fit group cursor-pointer hover:border-blue-300 transition-colors"
                    >
                      <div className="bg-rose-100 text-rose-600 p-2 rounded-lg">
                        <Paperclip size={20} />
                      </div>
                      <div>
                        <p className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors">Termo_Ativos_Cirion.pdf</p>
                        <p className="text-[10px] text-slate-500">142 KB - PDF Gerado com Assinatura de TI</p>
                      </div>
                    </div>
                  </div>
                )}

                {currentExchange && currentExchange.status === 'pending_receiver' && (
