            <Database className="text-white" size={24} />
          </div>
          <h1 className="text-xl font-bold tracking-tight">AssetFlow</h1>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4">
          <button
            onClick={() => { setEditingExchange(null); setCurrentView('form'); }}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'form' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
            <PlusCircle size={20} />
            <span className="font-medium">Nova Troca</span>
          </button>

          <button
            onClick={() => setCurrentView('inventory')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'inventory' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
