            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all relative ${currentView === 'inbox' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
