import { View, AssetExchange, MockEmail } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';
import MockInbox from './components/MockInbox';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [emails, setEmails] = useState<MockEmail[]>([]);
  const [editingExchange, setEditingExchange] = useState<AssetExchange | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    const savedExchanges = localStorage.getItem('asset_exchanges');
    if (savedExchanges) {
      const parsed = JSON.parse(savedExchanges);
      setExchanges(parsed);
    }
    const savedEmails = localStorage.getItem('mock_emails');
    if (savedEmails) setEmails(JSON.parse(savedEmails));
  }, []);

  useEffect(() => {
    localStorage.setItem('asset_exchanges', JSON.stringify(exchanges));
  }, [exchanges]);

  useEffect(() => {
    localStorage.setItem('mock_emails', JSON.stringify(emails));
  }, [emails]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  const handleSaveExchange = (exchange: AssetExchange) => {
    let updated: AssetExchange[];
    const isUpdate = exchanges.some(e => e.id === exchange.id);

    if (isUpdate) {
      updated = exchanges.map(e => e.id === exchange.id ? exchange : e);
      showNotification("Registro atualizado com sucesso.");
    } else {
      updated = [{ ...exchange, status: 'draft' }, ...exchanges];
      showNotification("Registro de troca salvo com sucesso.");
    }

    setExchanges(updated);
    setEditingExchange(null);
    setCurrentView('inventory');
  };

  const handleSignSender = (id: string, signature: string) => {
    const updatedExchanges = exchanges.map(ex => {
      if (ex.id === id) {
        return { ...ex, senderSignature: signature, status: 'pending_receiver' as const };
      }
      return ex;
    });
    setExchanges(updatedExchanges);

    const exchange = updatedExchanges.find(e => e.id === id)!;
    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: id,
      from: 'TI Infra - AssetFlow <infra@cirion.com>',
      to: exchange.email,
      subject: `[AÇÃO NECESSÁÍA] Termo de Troca de Ativos - ${exchange.name}`,
      body: `Olá ${exchange.name},\n\nO seu novo equipamento foi registrado. Por favor, revise o termo de entrega e devolução em anexo, assine digitalmente e retorne para nós.\n\nAtenciosamente,\nEquipe de TI Cirion Technologies`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([newEmail, ...emails]);
    showNotification("Termo assinado por TI e enviado via Outlook.");
  };

  const handleSignReceiver = (exchangeId: string, signature: string) => {
    const updatedExchanges = exchanges.map(ex => {
      if (ex.id === exchangeId) {
        return { ...ex, receiverSignature: signature, status: 'completed' as const };
      }
      return ex;
    });
    setExchanges(updatedExchanges);

    const exchange = updatedExchanges.find(e => e.id === exchangeId)!;
    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.name} <${exchange.email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.name}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.name}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador e devolvido ao TI.");
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-900 font-sans">
      <aside className="w-full md:w-64 bg-slate-950 text-white flex-shrink-0 flex flex-col border-r border-slate-800 z-20">
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <Database className="text-white" size={24} />
          </div>
          <h1 className="text-xl font-bold tracking-tight">AssetFlow</h1>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4">
          <button
            onClick={() => { setEditingExchange(null); setCurrentView('form'); }}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'form' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
            <PlusCircle size={20} />
            <span className="font-medium">Nova Troca</span>
          </button>

          <button
            onClick={() => setCurrentView('inventory')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${currentView === 'inventory' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
            <ClipboardList size={20} />
            <span className="font-medium">Inventário</span>
          </button>

          <button
            onClick={() => setCurrentView('inbox')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all relative ${currentView === 'inbox' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
          >
            <Mail size={20} />
            <span className="font-medium">Outlook Mock</span>
            {emails.some(e => !e.read) && (
              <span className="absolute right-3 top-1/2 -translate-y-1/2 w-2 h-2 bg-indigo-400 rounded-full"></span>
            )}
          </button>
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button className="w-full flex items-center gap-3 px-4 py-3 text-slate-500 hover:text-red-400 transition-colors">
            <LogOut size={20} />
            <span className="font-medium">Sair</span>
          </button>
        </div>
      </aside>

      <main 
        className="flex-1 overflow-auto relative min-h-screen bg-slate-900"
        style={{
          // Overlay muito mais claro (30%) para garantir a visibilidade da imagem dos racks
          backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.3), rgba(15, 23, 42, 0.3)), url('https://images.unsplash.com/photo-1558494949-ef010cbdcc48?q=80&w=2000')`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat'
        }}
      >
        {notification && (
          <div className={`fixed top-6 right-6 z-[200] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border animate-in slide-in-from-top-4 ${notification.type === 'success' ? 'bg-emerald-50 text-emerald-800 border-emerald-100' : 'bg-rose-50 text-rose-800 border-rose-100'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            <p className="font-medium">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto p-6 md:p-10 relative z-10">
          <header className="mb-8 bg-slate-950/60 backdrop-blur-xl p-8 rounded-[2rem] border border-white/10 shadow-2xl">
            <h2 className="text-4xl font-extrabold text-white tracking-tight drop-shadow-xl">
              {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
               currentView === 'inventory' ? 'Inventário de Ativos' : 'Outlook Simulation'}
            </h2>
            <div className="flex items-center gap-2 mt-2">
               <div className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse"></div>
               <p className="text-indigo-200 font-bold uppercase tracking-[0.2em] text-xs">Cirion Technologies - Data Center Excellence</p>
            </div>
          </header>

          <div className="bg-white/95 backdrop-blur-md rounded-[2.5rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] border border-white/40 overflow-hidden">
            {currentView === 'form' && (
              <AssetForm 
                onSave={handleSaveExchange} 
                editingExchange={editingExchange} 
                onCancel={() => setCurrentView('inventory')} 
                exchanges={exchanges}
              />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={(id) => {
                  if (window.confirm("Você tem certeza que deseja excluir permanentemente este registro de troca?")) {
                    setExchanges(prev => prev.filter(e => e.id !== id));
                    setEmails(prev => prev.filter(email => email.exchangeId !== id));
                    showNotification("Registro removido do inventário.", "error");
                  }
                }} 
                onEdit={(ex) => { setEditingExchange(ex); setCurrentView('form'); }} 
                onNotify={showNotification}
                onSignSender={handleSignSender}
              />
            )}
            {currentView === 'inbox' && (
              <MockInbox 
                emails={emails} 
                onUpdateEmails={setEmails} 
                exchanges={exchanges}
                onSignReceiver={handleSignReceiver}
              />
            )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

