    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.name} <${exchange.email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.name}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.name}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador e devolvido ao TI.");
  };

  return (
    <div className="relative min-h-screen font-sans overflow-hidden bg-slate-950">
      {/* CAMADA DE FUNDO - IMAGEM DE DATACENTER DE ALTA QUALIDADE */}
      <div 
        className="fixed inset-0 z-0 scale-105"
        style={{
          backgroundImage: `linear-gradient(rgba(10, 20, 40, 0.4), rgba(10, 20, 40, 0.7)), url('https://images.unsplash.com/photo-1558494949-ef010cbdcc48?q=80&w=2500')`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          filter: 'brightness(0.9) contrast(1.1)'
        }}
      />

      <div className="relative z-10 flex flex-col md:flex-row min-h-screen">
        {/* SIDEBAR - EFEITO VIDRO ESCURO */}
