          <div className="p-10 flex flex-col items-center gap-2">
            <div className="w-16 h-16 bg-gradient-to-tr from-indigo-600 to-cyan-500 rounded-2xl flex items-center justify-center shadow-2xl shadow-indigo-500/30 mb-2">
              <Database className="text-white" size={32} />
            </div>
            <div className="text-center">
              <h1 className="text-2xl font-black tracking-tighter bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">AssetFlow</h1>
              <div className="flex items-center justify-center gap-1.5 mt-1">
                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></div>
                <span className="text-[10px] text-indigo-300 font-bold tracking-widest uppercase">Cirion Infrastructure</span>
              </div>
            </div>
          </div>

          <nav className="flex-1 px-6 space-y-4 py-6">
            <button
              onClick={() => { setEditingExchange(null); setCurrentView('form'); }}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all duration-300 group ${currentView === 'form' ? 'bg-indigo-600 shadow-2xl shadow-indigo-500/40 text-white translate-x-2' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}
            >
              <PlusCircle size={22} className={currentView === 'form' ? 'text-white' : 'group-hover:text-indigo-400'} />
              <span className="font-bold tracking-tight">Nova Troca</span>
            </button>

            <button
              onClick={() => setCurrentView('inventory')}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all duration-300 group ${currentView === 'inventory' ? 'bg-indigo-600 shadow-2xl shadow-indigo-500/40 text-white translate-x-2' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}
