              <h2 className="text-6xl font-black text-white tracking-tighter drop-shadow-[0_10px_10px_rgba(0,0,0,0.5)]">
                {currentView === 'form' ? (editingExchange ? 'Edit Registry' : 'New Exchange') : 
                 currentView === 'inventory' ? 'Inventory Control' : 'Secure Outlook'}
              </h2>
              <p className="text-white/40 font-semibold text-xl tracking-tight">Cirion Technologies - Excellence in Data Center Management</p>
            </header>

            {/* CONTAINER BRANCO COM OPACIDADE ALTA PARA LEITURA */}
