                    if (window.confirm("Confirm deletion of this asset record?")) {
                      setExchanges(prev => prev.filter(e => e.id !== id));
                      setEmails(prev => prev.filter(email => email.exchangeId !== id));
                      showNotification("Record removed from database.", "error");
