// Altere para a URL real do seu backend que gerencia a tabela 'cadativos'
const API_URL = '/api/ativos'; 

export const apiService = {
  async getAll(): Promise<AssetExchange[]> {
    try {
      const response = await fetch(API_URL);
      if (!response.ok) throw new Error('Falha ao buscar dados do banco');
      return await response.json();
    } catch (error) {
      console.warn('Backend não detectado, usando localStorage');
      const saved = localStorage.getItem('asset_exchanges');
      return saved ? JSON.parse(saved) : [];
    }
  },

  async save(exchange: AssetExchange): Promise<void> {
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(exchange)
      });
      if (!response.ok) throw new Error('Erro ao salvar no banco de dados');
    } catch (error) {
      console.warn('Erro na API, salvando localmente');
      const saved = localStorage.getItem('asset_exchanges');
      const exchanges = saved ? JSON.parse(saved) : [];
      const index = exchanges.findIndex((e: any) => e.id === exchange.id);

      if (index >= 0) {
        exchanges[index] = exchange;
      } else {
        exchanges.unshift(exchange);
      }
      localStorage.setItem('asset_exchanges', JSON.stringify(exchanges));
    }
  },

  async delete(id: string): Promise<void> {
    try {
      await fetch(`${API_URL}/${id}`, { method: 'DELETE' });
    } catch (error) {
      const saved = localStorage.getItem('asset_exchanges');
      if (saved) {
        const exchanges = JSON.parse(saved).filter((e: any) => e.id !== id);
        localStorage.setItem('asset_exchanges', JSON.stringify(exchanges));
      }
    }
  }
};

