import { jsPDF } from 'jspdf';
import { AssetExchange, EquipmentCondition } from '../types';

export const generateAssetPDF = (exchange: AssetExchange, download: boolean = true) => {
  const doc = new jsPDF({ orientation: 'p', unit: 'mm', format: 'a4' });

  const cirionBlue = "#2b3481";
  const cirionMagenta = "#e3007e";
  const textColor = "#000000";
  const borderColor = "#2b3481";
  const inkBlue = "#003087";

  const renderPage = (type: 'Entrega' | 'Devolução') => {
    const isEntregue = type === 'Entrega';
    const prefix = isEntregue ? 'entregue_' : 'devolvido_';

    // Logo e Header
    doc.setFont("helvetica", "bold");
    doc.setFontSize(28);
    doc.setTextColor(cirionBlue);
    doc.text("cirion", 20, 25);
    doc.setDrawColor(cirionMagenta); doc.setLineWidth(1.5); doc.line(42, 17, 42, 27); 

    doc.setFontSize(11);
    doc.text(`Termo de ${type} de Equipamento`, 70, 20);

    // Texto Legal e Dados
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(textColor);
    doc.text(`Eu, ${exchange.colaborador_nome} (${exchange.colaborador_email}), declaro a ${type.toLowerCase()} do:`, 20, 45);

    let y = 60;
    const fields = [
      ["Tipo", exchange[`${prefix}tipo` as keyof AssetExchange]],
      ["Marca", exchange[`${prefix}marca` as keyof AssetExchange]],
      ["Modelo", exchange[`${prefix}modelo` as keyof AssetExchange]],
      ["Serial", exchange[`${prefix}serial` as keyof AssetExchange]],
      ["Estado", exchange[`${prefix}condicao` as keyof AssetExchange]],
    ];

    fields.forEach(([label, value]) => {
      doc.setFont("helvetica", "bold"); doc.text(`${label}:`, 20, y);
      doc.setFont("helvetica", "normal"); doc.text(String(value), 50, y);
      y += 10;
    });

    y += 10;
    doc.setFont("helvetica", "bold"); doc.text("Acessórios:", 20, y);
    const accs = (exchange[`${prefix}acessorios` as keyof AssetExchange] as string[]) || [];
    doc.setFont("helvetica", "normal"); doc.text(accs.join(", ") || "Nenhum", 50, y);

    y += 20;
    doc.setFontSize(8);
    const legalText = "Comprometo-me a utilizar o equipamento de acordo com as políticas de segurança da Cirion Technologies.";
    doc.text(doc.splitTextToSize(legalText, 170), 20, y);

    y += 40;
    doc.setLineWidth(0.3);
    doc.line(20, y, 90, y); doc.line(120, y, 190, y);
    doc.setFontSize(9);
    doc.text("Colaborador", 45, y + 5, {align: 'center'});
    doc.text("Responsável TI", 155, y + 5, {align: 'center'});

    // Renderizar Assinaturas
    if (exchange.assinatura_colaborador) {
      doc.setFont("times", "italic"); doc.setFontSize(22); doc.setTextColor(inkBlue);
      doc.text(exchange.assinatura_colaborador, 55, y - 2, {align: 'center'});
    }
    if (exchange.assinatura_ti) {
      doc.setFont("times", "italic"); doc.setFontSize(22); doc.setTextColor(inkBlue);
      doc.text(exchange.assinatura_ti, 155, y - 2, {align: 'center'});
    }
  };

  renderPage('Entrega');
  doc.addPage();
  renderPage('Devolução');

  if (download) {
    doc.save(`Termo_${exchange.colaborador_nome.replace(/\s+/g, '_')}.pdf`);
  }
  return doc.output('datauristring');
};

import * as XLSX from 'xlsx';
import { AssetExchange } from '../types';

export const exportToExcel = (data: AssetExchange[]) => {
  // Mapeia os dados para refletir as colunas da tabela de inventário
  // Fixed property names to match AssetExchange interface
  const flattenedData = data.map(item => ({
    "Colaborador": item.colaborador_nome,
    "E-mail": item.colaborador_email,
    "Ativo Entregue": `${item.entregue_marca} ${item.entregue_modelo}`,
    "Serial Entregue": item.entregue_serial,
    "Ativo Devolvido": `${item.devolvido_marca} ${item.devolvido_modelo}`,
    "Serial Devolvido": item.devolvido_serial,
    "Data da Troca": new Date(item.data_troca + 'T00:00:00').toLocaleDateString('pt-BR'),
    "ID do Registro": item.id
  }));

  const worksheet = XLSX.utils.json_to_sheet(flattenedData);

  // Ajusta a largura das colunas para melhor visualização
  const wscols = [
    { wch: 30 }, // Colaborador
    { wch: 30 }, // E-mail
    { wch: 25 }, // Ativo Entregue
    { wch: 15 }, // Serial Entregue
    { wch: 25 }, // Ativo Devolvido
    { wch: 15 }, // Serial Devolvido
    { wch: 15 }, // Data da Troca
    { wch: 15 }  // ID
  ];
  worksheet['!cols'] = wscols;

  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Inventário de Trocas");

  // Gera o nome do arquivo com a data atual
  const filename = `Inventario_Ativos_${new Date().toISOString().split('T')[0]}.xlsx`;
  XLSX.writeFile(workbook, filename);
};

import { AssetExchange } from '../types';

// Altere para a URL real do seu backend que gerencia a tabela 'cadativos'
const API_URL = '/api/ativos'; 

export const apiService = {
  async getAll(): Promise<AssetExchange[]> {
    console.log('API: Buscando todos os ativos...');
    try {
      const response = await fetch(API_URL);
      if (!response.ok) throw new Error(`Falha na API: ${response.statusText}`);
      const data = await response.json();
      console.log('API: Dados carregados do MySQL', data.length, 'registros.');
      return data;
    } catch (error) {
      console.warn('API: Backend não detectado ou erro na conexão, usando fallback localStorage', error);
      const saved = localStorage.getItem('asset_exchanges');
      return saved ? JSON.parse(saved) : [];
    }
  },

  async save(exchange: AssetExchange): Promise<void> {
    console.log('API: Iniciando salvamento do ativo:', exchange.id);
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(exchange)
      });
      if (!response.ok) throw new Error(`Erro ao salvar no banco: ${response.statusText}`);
      console.log('API: Registro salvo com sucesso no MySQL.');
    } catch (error) {
      console.warn('API: Erro ao persistir no MySQL, salvando no localStorage como contingência.', error);
      const saved = localStorage.getItem('asset_exchanges');
      const exchanges = saved ? JSON.parse(saved) : [];
      const index = exchanges.findIndex((e: any) => e.id === exchange.id);

      if (index >= 0) {
        exchanges[index] = exchange;
      } else {
        exchanges.unshift(exchange);
      }
      localStorage.setItem('asset_exchanges', JSON.stringify(exchanges));
    }
  },

  async delete(id: string): Promise<void> {
    console.log('API: Excluindo ativo:', id);
    try {
      const response = await fetch(`${API_URL}/${id}`, { method: 'DELETE' });
      if (!response.ok) throw new Error('Erro na exclusão remota');
      console.log('API: Registro removido do MySQL.');
    } catch (error) {
      console.warn('API: Falha na exclusão remota, limpando localmente.', error);
      const saved = localStorage.getItem('asset_exchanges');
      if (saved) {
        const exchanges = JSON.parse(saved).filter((e: any) => e.id !== id);
        localStorage.setItem('asset_exchanges', JSON.stringify(exchanges));
      }
    }
  }
};

import React, { useState, useEffect } from 'react';
