              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white font-mono" value={formData.devolvido_serial} onChange={e => setFormData({...formData, devolvido_serial: e.target.value})} />
                  {!isReadOnly && !isSubmitting && <button type="button" onClick={() => setScannerConfig({isOpen: true, target: 'devolvido'})} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-rose-600 transition-colors"><ScanLine size={16}/></button>}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Estado</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white" value={formData.devolvido_condicao} onChange={e => setFormData({...formData, devolvido_condicao: e.target.value as EquipmentCondition})}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
            </div>
            <div className="mt-4 grid grid-cols-3 gap-2">
              {ACCESSORIES_OPTIONS.map(acc => (
                <label key={acc} className={`flex items-center gap-2 text-[10px] p-1 rounded border cursor-pointer transition-colors ${formData.devolvido_acessorios.includes(acc) ? 'bg-rose-50 border-rose-200' : 'bg-white'}`}>
                  <input type="checkbox" checked={formData.devolvido_acessorios.includes(acc)} onChange={() => handleAccessoryToggle(acc, 'devolvido')} disabled={isReadOnly || isSubmitting} />
                  {acc}
                </label>
              ))}
            </div>
          </section>
        </div>

        <section>
          <SectionHeader icon={MousePointer2} title="Observações Internas" color="bg-slate-700" />
          <textarea 
            disabled={isReadOnly || isSubmitting}
            placeholder="Detalhes adicionais sobre a troca ou estado físico dos equipamentos..."
            className="w-full p-4 rounded-2xl border bg-white h-24 focus:ring-2 focus:ring-slate-100 transition-all resize-none" 
            value={formData.observacoes}
            onChange={e => setFormData({ ...formData, observacoes: e.target.value })}
          />
        </section>

        <div className="flex justify-end items-center gap-4">
          <button 
            type="button" 
            onClick={onCancel} 
            disabled={isSubmitting}
            className="px-8 py-3 rounded-2xl font-bold text-slate-500 hover:bg-slate-100 transition-colors disabled:opacity-30"
          >
            Cancelar
          </button>
          {!isReadOnly && (
            <button 
              type="submit" 
              disabled={isSubmitting}
              className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-10 py-3 rounded-2xl font-bold shadow-xl shadow-indigo-600/20 transition-all active:scale-95 disabled:bg-indigo-400 disabled:shadow-none"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="animate-spin" size={20} />
                  <span>Processando...</span>
                </>
              ) : (
                <>
                  <Send size={20} />
                  <span>{editingExchange ? 'Salvar no Banco' : 'Registrar no Banco'}</span>
                </>
              )}
            </button>
          )}
        </div>
      </form>

      {scannerConfig.isOpen && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'entregue' ? 'Lendo Serial Entregue' : 'Lendo Serial Devolvido'}
          onScan={(text) => {
            const processed = text.trim();
            if (scannerConfig.target === 'entregue') setFormData({...formData, entregue_serial: processed});
            else setFormData({...formData, devolvido_serial: processed});
            setScannerConfig({...scannerConfig, isOpen: false});
          }}
          onClose={() => setScannerConfig({...scannerConfig, isOpen: false})}
        />
      )}
    </>
  );
};

