interface AssetFormProps {
  onSave: (exchange: AssetExchange) => void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = ["Mouse", "Teclado", "Headset", "Mochila", "DockStation", "Monitor"];

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel, exchanges = [] }) => {
  const isReadOnly = editingExchange?.status === 'completed';
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState<AssetExchange>({
    id: '',
    status: 'draft',
    timestamp: Date.now(),
    colaborador_nome: '',
    colaborador_email: '',
    data_troca: new Date().toISOString().split('T')[0],
    observacoes: '',
    entregue_tipo: EQUIPMENT_TYPES[0],
    entregue_marca: BRANDS[0],
    entregue_modelo: MODELS[BRANDS[0]][0],
    entregue_serial: '',
    entregue_processador: '',
    entregue_condicao: EquipmentCondition.NEW,
    entregue_memoria: '',
    entregue_armazenamento: '',
    entregue_acessorios: [],
    devolvido_tipo: EQUIPMENT_TYPES[0],
    devolvido_marca: BRANDS[0],
    devolvido_modelo: MODELS[BRANDS[0]][0],
    devolvido_serial: '',
    devolvido_processador: '',
    devolvido_condicao: EquipmentCondition.USED,
    devolvido_memoria: '',
    devolvido_armazenamento: '',
    devolvido_acessorios: []
  });

