  const handleBrandChange = (brand: string, target: 'entregue' | 'devolvido') => {
    const models = MODELS[brand] || ["Outro"];
    if (target === 'entregue') {
      setFormData({ ...formData, entregue_marca: brand, entregue_modelo: models[0] });
    } else {
      setFormData({ ...formData, devolvido_marca: brand, devolvido_modelo: models[0] });
