import { jsPDF } from 'jspdf';
import { AssetExchange } from '../types';

export const generateAssetPDF = (exchange: AssetExchange, download: boolean = true) => {
  const doc = new jsPDF({ orientation: 'p', unit: 'mm', format: 'a4' });

  const cirionBlue = "#2b3481";
  const cirionMagenta = "#e3007e";
  const textColor = "#000000";
  const inkBlue = "#003087";

  const renderPage = (type: 'Entrega' | 'Devolução') => {
    const isEntregue = type === 'Entrega';
    const prefix = isEntregue ? 'entregue_' : 'devolvido_';

    // Logo e Header
    doc.setFont("helvetica", "bold");
    doc.setFontSize(28);
    doc.setTextColor(cirionBlue);
    doc.text("cirion", 20, 25);
    doc.setDrawColor(cirionMagenta); doc.setLineWidth(1.5); doc.line(42, 17, 42, 27); 

    doc.setFontSize(11);
    doc.text(`Termo de ${type} de Equipamento`, 70, 20);

    // Texto Legal e Dados
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(textColor);
    doc.text(`Eu, ${exchange.colaborador_nome} (${exchange.colaborador_email}), declaro a ${type.toLowerCase()} do:`, 20, 45);

    let y = 60;
    const fields = [
      ["Tipo", exchange[`${prefix}tipo` as keyof AssetExchange]],
      ["Marca", exchange[`${prefix}marca` as keyof AssetExchange]],
      ["Modelo", exchange[`${prefix}modelo` as keyof AssetExchange]],
      ["Serial", exchange[`${prefix}serial` as keyof AssetExchange]],
      ["Estado", exchange[`${prefix}condicao` as keyof AssetExchange]],
    ];

    fields.forEach(([label, value]) => {
      doc.setFont("helvetica", "bold"); doc.text(`${label}:`, 20, y);
      doc.setFont("helvetica", "normal"); doc.text(String(value), 50, y);
      y += 10;
    });

    y += 10;
    doc.setFont("helvetica", "bold"); doc.text("Acessórios:", 20, y);
    const accs = (exchange[`${prefix}acessorios` as keyof AssetExchange] as string[]) || [];
    doc.setFont("helvetica", "normal"); doc.text(accs.join(", ") || "Nenhum", 50, y);

    y += 20;
    doc.setFontSize(8);
    const legalText = "Comprometo-me a utilizar o equipamento de acordo com as políticas de segurança da Cirion Technologies.";
    doc.text(doc.splitTextToSize(legalText, 170), 20, y);

    y += 40;
    doc.setLineWidth(0.3);
    doc.line(20, y, 90, y); doc.line(120, y, 190, y);
    doc.setFontSize(9);
    doc.text("Colaborador", 45, y + 5, {align: 'center'});
    doc.text("Responsável TI", 155, y + 5, {align: 'center'});

    // Renderizar Assinaturas
    if (exchange.assinatura_colaborador) {
      doc.setFont("times", "italic"); doc.setFontSize(22); doc.setTextColor(inkBlue);
      doc.text(exchange.assinatura_colaborador, 55, y - 2, {align: 'center'});
    }
    if (exchange.assinatura_ti) {
      doc.setFont("times", "italic"); doc.setFontSize(22); doc.setTextColor(inkBlue);
      doc.text(exchange.assinatura_ti, 155, y - 2, {align: 'center'});
    }
  };

  renderPage('Entrega');
  doc.addPage();
  renderPage('Devolução');

  if (download) {
    doc.save(`Termo_${exchange.colaborador_nome.replace(/\s+/g, '_')}.pdf`);
  }
  return doc.output('datauristring');
};

import React, { useState, useEffect } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS } from '../constants';
import { User, Package, History, Send, ScanLine, Lock, MousePointer2, Loader2, CheckSquare } from 'lucide-react';
import BarcodeScannerModal from './BarcodeScannerModal';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => Promise<void> | void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = ["Mouse", "Teclado", "Headset", "Mochila", "DockStation", "Monitor"];

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel }) => {
  const isReadOnly = editingExchange?.status === 'completed';
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState<AssetExchange>({
    id: '',
    status: 'draft',
    timestamp: Date.now(),
    colaborador_nome: '',
    colaborador_email: '',
    data_troca: new Date().toISOString().split('T')[0],
    observacoes: '',
    entregue_tipo: EQUIPMENT_TYPES[0],
    entregue_marca: BRANDS[0],
    entregue_modelo: MODELS[BRANDS[0]][0],
    entregue_serial: '',
    entregue_processador: '',
    entregue_condicao: EquipmentCondition.NEW,
    entregue_memoria: '',
    entregue_armazenamento: '',
    entregue_acessorios: [],
    devolvido_tipo: EQUIPMENT_TYPES[0],
    devolvido_marca: BRANDS[0],
    devolvido_modelo: MODELS[BRANDS[0]][0],
    devolvido_serial: '',
    devolvido_processador: '',
    devolvido_condicao: EquipmentCondition.USED,
    devolvido_memoria: '',
    devolvido_armazenamento: '',
    devolvido_acessorios: []
  });

  const [scannerConfig, setScannerConfig] = useState<{ isOpen: boolean; target: 'entregue' | 'devolvido' }>({
    isOpen: false,
    target: 'entregue'
  });

  useEffect(() => {
    if (editingExchange) {
      setFormData({ ...editingExchange });
    }
  }, [editingExchange]);

  const handleBrandChange = (brand: string, target: 'entregue' | 'devolvido') => {
    const models = MODELS[brand] || ["Outro"];
    if (target === 'entregue') {
      setFormData({ ...formData, entregue_marca: brand, entregue_modelo: models[0] });
    } else {
      setFormData({ ...formData, devolvido_marca: brand, devolvido_modelo: models[0] });
    }
  };

  const handleAccessoryToggle = (acc: string, target: 'entregue' | 'devolvido') => {
    const field = target === 'entregue' ? 'entregue_acessorios' : 'devolvido_acessorios';
    const current = formData[field] as string[];
    const updated = current.includes(acc) ? current.filter(i => i !== acc) : [...current, acc];
    setFormData({ ...formData, [field]: updated });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload = {
        ...formData,
        id: formData.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        timestamp: formData.timestamp || Date.now()
      };
      await onSave(payload);
    } catch (err) {
      console.error("Erro ao salvar formulário:", err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-6 pb-2 border-b border-slate-100">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={20} className="text-white" />
      </div>
      <h3 className="text-lg font-semibold text-slate-800">{title}</h3>
    </div>
  );

  return (
    <>
      <form onSubmit={handleSubmit} className="p-8 space-y-12">
        {isReadOnly && (
          <div className="bg-amber-50 border border-amber-200 p-4 rounded-2xl flex items-center gap-4 mb-8">
            <Lock size={20} className="text-amber-700" />
            <p className="text-amber-900 text-sm font-bold">Registro Bloqueado por Assinatura</p>
          </div>
        )}

        <section>
          <SectionHeader icon={User} title="Dados do Colaborador" color="bg-indigo-600" />
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Nome Completo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required
                placeholder="Ex: João Silva"
                className="w-full px-4 py-2.5 rounded-xl border bg-white focus:ring-2 focus:ring-indigo-100 transition-all"
                value={formData.colaborador_nome}
                onChange={e => setFormData({ ...formData, colaborador_nome: e.target.value })}
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">E-mail Corporativo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="email"
                placeholder="joao.silva@cirion.com"
                className="w-full px-4 py-2.5 rounded-xl border bg-white focus:ring-2 focus:ring-indigo-100 transition-all"
                value={formData.colaborador_email}
                onChange={e => setFormData({ ...formData, colaborador_email: e.target.value })}
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-sm font-medium text-slate-700">Data da Troca</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="date"
                className="w-full px-4 py-2.5 rounded-xl border bg-white focus:ring-2 focus:ring-indigo-100 transition-all"
                value={formData.data_troca}
                onChange={e => setFormData({ ...formData, data_troca: e.target.value })}
              />
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
          {/* Entregue */}
          <section className="p-6 rounded-2xl bg-slate-50 border border-slate-100">
            <SectionHeader icon={Package} title="Equipamento Entregue" color="bg-emerald-600" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white" value={formData.entregue_tipo} onChange={e => setFormData({...formData, entregue_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white" value={formData.entregue_marca} onChange={e => handleBrandChange(e.target.value, 'entregue')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1 md:col-span-2">
                <label className="text-xs font-bold text-slate-500 uppercase">Modelo</label>
                <input disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white" value={formData.entregue_modelo} onChange={e => setFormData({...formData, entregue_modelo: e.target.value})} />
              </div>
              <div className="space-y-1 md:col-span-2">
                <label className="text-xs font-bold text-slate-500 uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white font-mono" value={formData.entregue_serial} onChange={e => setFormData({...formData, entregue_serial: e.target.value})} />
                  {!isReadOnly && !isSubmitting && <button type="button" onClick={() => setScannerConfig({isOpen: true, target: 'entregue'})} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors"><ScanLine size={16}/></button>}
                </div>
              </div>
            </div>

            <div className="mt-6">
              <label className="text-xs font-bold text-slate-500 uppercase block mb-3">Acessórios Entregues</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label 
                    key={acc} 
                    className={`flex items-center gap-2 px-3 py-2 rounded-xl border cursor-pointer transition-all text-xs font-medium ${formData.entregue_acessorios.includes(acc) ? 'bg-emerald-50 border-emerald-200 text-emerald-700 ring-2 ring-emerald-100' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-200'}`}
                  >
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={formData.entregue_acessorios.includes(acc)} 
                      onChange={() => handleAccessoryToggle(acc, 'entregue')} 
                      disabled={isReadOnly || isSubmitting} 
                    />
                    <CheckSquare size={14} className={formData.entregue_acessorios.includes(acc) ? 'opacity-100' : 'opacity-20'} />
                    {acc}
                  </label>
                ))}
              </div>
            </div>
          </section>

          {/* Devolvido */}
          <section className="p-6 rounded-2xl bg-slate-50 border border-slate-100">
            <SectionHeader icon={History} title="Equipamento Devolvido" color="bg-rose-600" />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Tipo</label>
