// PDF generation function
export const generateAssetPDF = async (exchange: AssetExchange) => {
  const doc = new jsPDF();
  const primaryColor = [1, 33, 105]; // Cirion Blue (Navy)
  const secondaryColor = [0, 155, 224]; // Cirion Light Blue

  // Helper function for text wrapping
  const wrapText = (text: string, maxWidth: number) => {
    return doc.splitTextToSize(text || '-', maxWidth);
  };

  // Add Header
  doc.setFillColor(primaryColor[0], primaryColor[1], primaryColor[2]);
  doc.rect(0, 0, 210, 40, 'F');

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.text('TERMO DE RESPONSABILIDADE', 105, 20, { align: 'center' });
  doc.setFontSize(12);
  doc.text('CONTROLE DE ATIVOS DE TI', 105, 30, { align: 'center' });

  // Reset text color
  doc.setTextColor(0, 0, 0);
  let yPos = 55;

  // Employee Info
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('1. DADOS DO COLABORADOR', 20, yPos);
  doc.setDrawColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
  doc.line(20, yPos + 2, 190, yPos + 2);

  yPos += 12;
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Nome: ${exchange.colaborador_nome}`, 25, yPos);
  yPos += 8;
  doc.text(`E-mail: ${exchange.colaborador_email}`, 25, yPos);
  yPos += 8;
  doc.text(`Data da Movimentação: ${new Date(exchange.data_troca).toLocaleDateString('pt-BR')}`, 25, yPos);

  // Delivered Equipment
  yPos += 20;
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('2. EQUIPAMENTO ENTREGUE', 20, yPos);
  doc.line(20, yPos + 2, 190, yPos + 2);

  yPos += 12;
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  const deliveredData = [
    `Tipo: ${exchange.entregue_tipo}`,
    `Marca: ${exchange.entregue_marca}`,
    `Modelo: ${exchange.entregue_modelo}`,
    `Serial/IMEI: ${exchange.entregue_serial}`,
    `Condição: ${exchange.entregue_condicao}`,
    `Configuração: CPU ${exchange.entregue_processador || '-'}, RAM ${exchange.entregue_memoria || '-'}, DISCO ${exchange.entregue_armazenamento || '-'}`,
    `Acessórios: ${exchange.entregue_acessorios.join(', ') || 'Nenhum'}`
  ];

  deliveredData.forEach(line => {
    doc.text(line, 25, yPos);
    yPos += 7;
  });

  // Returned Equipment
  yPos += 10;
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('3. EQUIPAMENTO DEVOLVIDO', 20, yPos);
  doc.line(20, yPos + 2, 190, yPos + 2);

  yPos += 12;
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  const returnedData = [
    `Tipo: ${exchange.devolvido_tipo}`,
    `Marca: ${exchange.devolvido_marca}`,
    `Modelo: ${exchange.devolvido_modelo}`,
    `Serial/IMEI: ${exchange.devolvido_serial}`,
    `Condição: ${exchange.devolvido_condicao}`,
    `Acessórios: ${exchange.devolvido_acessorios.join(', ') || 'Nenhum'}`
  ];

  returnedData.forEach(line => {
    doc.text(line, 25, yPos);
    yPos += 7;
  });

  // Observations
  if (exchange.observacoes) {
    yPos += 10;
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('4. OBSERVAÇÕES', 20, yPos);
    doc.line(20, yPos + 2, 190, yPos + 2);
    yPos += 10;
    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    const splitObs = wrapText(exchange.observacoes, 165);
    doc.text(splitObs, 25, yPos);
    yPos += (splitObs.length * 5) + 5;
  }

  // Terms and Conditions
  yPos = 210;
  doc.setFontSize(8);
  const terms = wrapText(
    "O colaborador declara ter recebido os equipamentos acima descritos em perfeito estado de conservação e funcionamento, comprometendo-se a zelar pelos mesmos e utilizá-los exclusivamente para fins profissionais. Em caso de dano por negligência, perda ou roubo sem a devida apresentação de Boletim de Ocorrência, o colaborador poderá ser responsabilizado pelos custos de reparo ou reposição.",
    170
  );
  doc.text(terms, 20, yPos);

  // Signatures
  yPos += 25;
  doc.setDrawColor(200, 200, 200);

  // TI Signature
  doc.line(30, yPos + 15, 90, yPos + 15);
  doc.setFontSize(9);
  doc.text('Assinatura Responsável TI', 60, yPos + 20, { align: 'center' });
  if (exchange.assinatura_ti) {
    doc.addFileToVFS('GreatVibes-Regular.ttf', GREAT_VIBES_FONT);
    doc.addFont('GreatVibes-Regular.ttf', 'GreatVibes', 'normal');
    doc.setFont('GreatVibes', 'normal');
    doc.setFontSize(24);
    doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.text(exchange.assinatura_ti, 60, yPos + 12, { align: 'center' });
    doc.setTextColor(0, 0, 0);
  }

  // Colaborador Signature
  doc.setFont('helvetica', 'normal');
  doc.line(120, yPos + 15, 180, yPos + 15);
  doc.setFontSize(9);
  doc.text('Assinatura Colaborador', 150, yPos + 20, { align: 'center' });
  if (exchange.assinatura_colaborador) {
    doc.addFileToVFS('GreatVibes-Regular.ttf', GREAT_VIBES_FONT);
    doc.addFont('GreatVibes-Regular.ttf', 'GreatVibes', 'normal');
    doc.setFont('GreatVibes', 'normal');
    doc.setFontSize(24);
    doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.text(exchange.assinatura_colaborador, 150, yPos + 12, { align: 'center' });
    doc.setTextColor(0, 0, 0);
  }

  // Footer
  doc.setFont('helvetica', 'italic');
  doc.setFontSize(7);
  doc.text(`Documento gerado em ${new Date().toLocaleString('pt-BR')} - ID: ${exchange.id}`, 105, 285, { align: 'center' });

  doc.save(`Termo_Ativos_${exchange.colaborador_nome.replace(/\s+/g, '_')}_${exchange.id}.pdf`);
};
]]></content>
  </change>
</changes>

