        ["Serial/IMEI:", String(exchange[`${prefix}serial` as keyof AssetExchange])],
        ["Condição:", String(exchange[`${prefix}condicao` as keyof AssetExchange])],
        ["Processador:", String(exchange[`${prefix}processador` as keyof AssetExchange] || "-")],
        ["Memória:", String(exchange[`${prefix}memoria` as keyof AssetExchange] || "-")],
        ["HD/SSD:", String(exchange[`${prefix}armazenamento` as keyof AssetExchange] || "-")],
      ];

      doc.setFontSize(10);
      fields.forEach(([label, value]) => {
        doc.setFont("helvetica", "bold");
        doc.text(label, 25, y);
        doc.setFont("helvetica", "normal");
        doc.text(value, 60, y);
        y += 7;
      });

      // Acessórios
      y += 5;
      doc.setFont("helvetica", "bold");
      doc.text("Acessórios:", 25, y);
      const accs = (exchange[`${prefix}acessorios` as keyof AssetExchange] as string[]) || [];
      doc.setFont("helvetica", "normal");
      doc.text(accs.length > 0 ? accs.join(", ") : "Nenhum", 60, y);

      // Observações
      y += 15;
      doc.setFont("helvetica", "bold");
      doc.text("Observações:", 20, y);
      y += 5;
      doc.setFont("helvetica", "normal");
      const splitObs = doc.splitTextToSize(exchange.observacoes || "Sem observações adicionais.", 170);
      doc.text(splitObs, 20, y);

      // Rodapé de Assinatura
      y = 240;
      doc.setDrawColor(0, 0, 0);
      doc.line(25, y, 90, y);
      doc.line(120, y, 185, y);

      doc.setFontSize(8);
      doc.text("Responsável TI", 57.5, y + 5, { align: 'center' });
      doc.text("Assinatura do Colaborador", 152.5, y + 5, { align: 'center' });

      // Desenho das Assinaturas Digitais (usando Times Italic para simular caneta)
      doc.setFontSize(22);
      doc.setTextColor(0, 48, 135); // Azul Caneta

      if (exchange.assinatura_ti) {
        doc.setFont("times", "italic");
        doc.text(exchange.assinatura_ti, 57.5, y - 2, { align: 'center' });
      }

      if (exchange.assinatura_colaborador) {
        doc.setFont("times", "italic");
        doc.text(exchange.assinatura_colaborador, 152.5, y - 2, { align: 'center' });
      }
    };

    // Página 1: Entrega
    renderPage(true);

    // Página 2: Devolução
    doc.addPage();
    renderPage(false);

    doc.save(`Termo_Troca_${exchange.colaborador_nome.replace(/\s+/g, '_')}.pdf`);
  } catch (error) {
    console.error("Erro ao gerar PDF:", error);
    alert("Ocorreu um erro ao gerar o arquivo PDF. Verifique o console.");
  }
};

import React, { useState, useRef } from 'react';
import { AssetExchange } from '../types';
import { FileDown, Trash2, Search, FileSpreadsheet, Pencil, Mail, Laptop, Smartphone, Cpu, Clock, Lock, FileCheck, Upload } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';
import { exportToExcel, importFromExcel } from '../services/excelService';
import SenderSignatureModal from './SenderSignatureModal';

interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
  onSignSender: (id: string, signature: string) => void;
  onBulkImport: (data: AssetExchange[]) => void;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify, onSignSender, onBulkImport }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = exchanges.filter(e => 
    e.colaborador_nome.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.entregue_serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.devolvido_serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const data = await importFromExcel(file);
      if (confirm(`Deseja importar ${data.length} registros? Isso poderá sobrescrever dados existentes com o mesmo ID.`)) {
        onBulkImport(data);
        onNotify("Base de dados sincronizada com sucesso!", "success");
      }
    } catch (err) {
      onNotify("Erro ao ler arquivo Excel. Verifique o formato.", "error");
    }
    e.target.value = ''; // Reset input
  };

  const getIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('note')) return <Laptop size={14} />;
    if (t.includes('smart')) return <Smartphone size={14} />;
    return <Cpu size={14} />;
  };

  return (
    <div className="flex flex-col h-full">
      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            placeholder="Buscar no banco de dados..."
            className="w-full pl-10 pr-4 py-2 rounded-xl border"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-2">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept=".xlsx, .xls" 
            className="hidden" 
          />
          <button 
            onClick={handleImportClick}
            className="flex items-center gap-2 bg-slate-100 text-slate-600 px-4 py-2 rounded-xl font-bold border border-slate-200 transition-all hover:bg-slate-200 active:scale-95"
          >
            <Upload size={18} /> Importar Base
          </button>
          <button 
            onClick={() => exportToExcel(exchanges)} 
            className="flex items-center gap-2 bg-emerald-600 text-white px-5 py-2 rounded-xl font-bold shadow-lg shadow-emerald-100 transition-all hover:bg-emerald-700 active:scale-95"
          >
            <FileSpreadsheet size={18} /> Exportar Excel
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Colaborador</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Entregue</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Devolvido</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-center">Status</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-slate-400 italic">Nenhum registro encontrado.</td>
              </tr>
            ) : (
              filtered.map(ex => (
                <tr key={ex.id} className="hover:bg-slate-50 group transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900">{ex.colaborador_nome}</span>
                      <span className="text-[10px] text-slate-400">{ex.colaborador_email}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-[10px] font-bold text-emerald-600 uppercase flex items-center gap-1">
                        {getIcon(ex.entregue_tipo)} {ex.entregue_tipo}
                      </span>
                      <span className="text-sm font-semibold">{ex.entregue_marca} {ex.entregue_modelo}</span>
                      <span className="text-[10px] font-mono text-slate-400">S/N: {ex.entregue_serial}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-[10px] font-bold text-rose-600 uppercase flex items-center gap-1">
                        {getIcon(ex.devolvido_tipo)} {ex.devolvido_tipo}
                      </span>
                      <span className="text-sm font-semibold">{ex.devolvido_marca} {ex.devolvido_modelo}</span>
                      <span className="text-[10px] font-mono text-slate-400">S/N: {ex.devolvido_serial}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    {ex.status === 'completed' ? (
                      <button 
                        onClick={() => generateAssetPDF(ex)}
                        className="inline-flex items-center gap-2 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-emerald-100 shadow-sm hover:bg-emerald-100 transition-all active:scale-95"
                      >
                        <FileCheck size={14} />
                        TERMO ASSINADO
                      </button>
                    ) : ex.status === 'pending_receiver' ? (
                      <span className="inline-flex items-center gap-2 bg-blue-50 text-blue-700 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-blue-100">
                        <Clock size={14} />
                        AGUARDANDO ASSINATURA
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-2 bg-slate-100 text-slate-600 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-slate-200">
                        <Pencil size={14} />
                        RASCUNHO
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      {ex.status === 'draft' && (
                        <button onClick={() => setSigningExchange(ex)} title="Enviar para assinatura" className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><Mail size={16}/></button>
                      )}
                      {ex.status !== 'completed' ? (
                        <button onClick={() => onEdit(ex)} title="Editar registro" className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Pencil size={16}/></button>
                      ) : (
                        <div className="p-2 text-slate-300" title="Registro Finalizado"><Lock size={16}/></div>
                      )}
                      <button onClick={() => generateAssetPDF(ex)} title="Gerar PDF" className="p-2 text-slate-600 hover:bg-slate-50 rounded-lg"><FileDown size={16}/></button>
                      <button onClick={() => onDelete(ex.id)} title="Excluir" className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg"><Trash2 size={16}/></button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {signingExchange && (
        <SenderSignatureModal 
          exchange={signingExchange}
          onClose={() => setSigningExchange(null)}
          onConfirm={(id, sig) => { onSignSender(id, sig); setSigningExchange(null); }}
        />
      )}
    </div>
  );
};

export default InventoryTable;

import { jsPDF } from 'jspdf';
import { AssetExchange } from '../types';

export const generateAssetPDF = (exchange: AssetExchange) => {
  try {
    const doc = new jsPDF({
      orientation: 'p',
      unit: 'mm',
      format: 'a4'
    });

    const cirionBlue = "#2b3481";
    const cirionMagenta = "#e3007e";
    const inkBlue = "#003087";

    const renderPage = (isEntregue: boolean) => {
      const prefix = isEntregue ? 'entregue_' : 'devolvido_';

      // 1. Logo e Cabeçalho
      // Simulando o logo Cirion com formas e texto
      doc.setFont("helvetica", "bold");
      doc.setFontSize(28);
      doc.setTextColor(cirionBlue);
      doc.text("ciri", 35, 25);
      doc.text("n", 56, 25);

      // O ponto magenta do logo
      doc.setFillColor(cirionMagenta);
      doc.circle(53, 20.5, 1.5, 'F');

      // Título e Checkboxes de tipo de termo
      doc.setFontSize(11);
      doc.setTextColor(cirionBlue);
      doc.text("Declaração de Equipamento Cirion", 85, 20);

      doc.setDrawColor(cirionBlue);
      doc.setLineWidth(0.3);

      // Checkbox Entrega
      doc.rect(85, 23, 3, 3);
      if (isEntregue) doc.text("x", 86, 25.5);
      doc.setFontSize(9);
      doc.text("Entrega", 90, 25.5);

      // Checkbox Devolução
      doc.rect(110, 23, 3, 3);
      if (!isEntregue) doc.text("x", 111, 25.5);
      doc.text("Devolução", 115, 25.5);

      // 2. Texto de Introdução
      doc.setFontSize(9);
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "normal");
      doc.text("Eu, ", 20, 40);
      doc.line(26, 40.5, 95, 40.5);
      doc.setFont("helvetica", "bold");
      doc.text(exchange.colaborador_nome, 28, 40);
      doc.setFont("helvetica", "normal");
      doc.text("declaro ter recebido/devolvido o", 97, 40);
      doc.text("equipamento e acessórios abaixo descritos, em perfeitas condições de funcionamento.", 20, 45);

      // 3. Campos de Dados (Boxes Azuis)
      let y = 55;
      const LABEL_X = 20;
      const FIELD_X = 40;
      const BOX_WIDTH = 100;

      const drawField = (label: string, value: string, width: number = BOX_WIDTH, customX: number = FIELD_X) => {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(0, 0, 0);
        doc.text(label, LABEL_X, y + 4.5);

        doc.setDrawColor(cirionBlue);
        doc.rect(customX, y, width, 6);
        doc.setFont("helvetica", "normal");
        doc.text(value || "", customX + 2, y + 4.5);
        y += 8;
      };

      drawField("Tipo:", String(exchange[`${prefix}tipo` as keyof AssetExchange]), 110);
      drawField("Marca:", String(exchange[`${prefix}marca` as keyof AssetExchange]), 110);
      drawField("Modelo:", String(exchange[`${prefix}modelo` as keyof AssetExchange]), 110);
      drawField("Número de Serie / Imei:", String(exchange[`${prefix}serial` as keyof AssetExchange]), 82, 68);
      drawField("Estado:", String(exchange[`${prefix}condicao` as keyof AssetExchange]), 25);

      // Campos de Configuração (Tamanho HD, Processador, Memória)
      y += 2;
      doc.setFont("helvetica", "bold");
      doc.text("Tamanho do HD:", 20, y + 4.5);
      doc.rect(58, y, 30, 6);
      doc.setFont("helvetica", "normal");
      doc.text(String(exchange[`${prefix}armazenamento` as keyof AssetExchange]), 60, y + 4.5);
      y += 8;

      drawField("Processador:", String(exchange[`${prefix}processador` as keyof AssetExchange]), 150, 50);

      doc.setFont("helvetica", "bold");
      doc.text("Memória:", 20, y + 4.5);
      doc.rect(42, y, 25, 6);
      doc.setFont("helvetica", "normal");
      doc.text(String(exchange[`${prefix}memoria` as keyof AssetExchange]), 44, y + 4.5);
      y += 15;

      // 4. Caixa de Acessórios
      doc.setFontSize(12);
      doc.setFont("helvetica", "bold");
      doc.text("Acessórios:", 105, y, { align: "center" });
      y += 4;

      doc.setDrawColor(cirionBlue);
      doc.rect(45, y, 120, 20);

      const accessories = ["Mouse", "Teclado", "Headset", "Mochila", "DockStation", "Monitor"];
      const selectedAccs = (exchange[`${prefix}acessorios` as keyof AssetExchange] as string[]) || [];

      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      let accX = 65;
      let accY = y + 5;

      accessories.forEach((acc, index) => {
        doc.rect(accX, accY - 2.5, 3, 3);
        if (selectedAccs.includes(acc)) doc.text("x", accX + 0.8, accY);
        doc.text(acc, accX + 5, accY);

        if (index === 2) {
          accX = 110;
          accY = y + 5;
        } else {
          accY += 6;
        }
      });

      y += 35;

      // 5. Observações
      doc.setFontSize(11);
      doc.setFont("helvetica", "bold");
      doc.text("Obs:", 20, y + 4.5);
      doc.rect(32, y, 150, 6);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.text(exchange.observacoes || "", 34, y + 4.5);

      y += 25;

      // 6. Rodapé Legal
      doc.setFontSize(8);
      doc.line(20, y, 85, y);
      doc.text("compromete-se a usar e devolver os equipamentos e acessórios", 87, y);
      y += 4;
      const footerText = "fornecidos pela empresa em perfeitas condições e com todas as informações, arquivos, contatos, arquivos de dados pessoais, e-mails, documentos de propriedades da Cirion Technologies. e / ou qualquer uma das suas filiais, no término do seu contrato de trabalho ou no final do período de autorização, sem as alterar, modificar, copiar, transferir, no estado em que foram entregues e sempre observando o princípio da confidencialidade. Se compromete em notificar o responsável de TI em caso de perda ou destruição do laptop, para que as medidas de segurança necessárias para a proteção de dados sejam aplicadas.";
      const splitText = doc.splitTextToSize(footerText, 175);
      doc.text(splitText, 20, y);

      y += 30;

      // 7. Data e Assinaturas
      const date = new Date(exchange.data_troca + 'T12:00:00');
      const months = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
      const dateStr = `Data: ${date.getDate()} de ${months[date.getMonth()]} de ${date.getFullYear()}`;
      doc.setFontSize(10);
      doc.setFont("helvetica", "bold");
      doc.text(dateStr, 20, y);

      y += 25;
      doc.setDrawColor(0, 0, 0);
      doc.line(20, y, 75, y); // Linha TI
      doc.line(120, y, 185, y); // Linha Colaborador

      doc.setFontSize(8);
      doc.setFont("helvetica", "normal");
      doc.text("Gilberto Araujo", 47.5, y + 4, { align: 'center' });
      doc.text(exchange.colaborador_nome, 152.5, y + 4, { align: 'center' });

      // Assinaturas Digitais (Estilo Caneta)
      doc.setFont("times", "italic");
      doc.setFontSize(22);
      doc.setTextColor(inkBlue);

      if (exchange.assinatura_ti) {
        doc.text(exchange.assinatura_ti, 47.5, y - 2, { align: 'center' });
      }

      if (exchange.assinatura_colaborador) {
        doc.text(exchange.assinatura_colaborador, 152.5, y - 2, { align: 'center' });
      }
    };

    // Gerar as duas páginas
    renderPage(true); // Termo de Entrega
    doc.addPage();
    renderPage(false); // Termo de Devolução

    doc.save(`Termo_Cirion_${exchange.colaborador_nome.replace(/\s+/g, '_')}.pdf`);
  } catch (error) {
    console.error("Erro ao gerar PDF:", error);
    alert("Erro ao processar o modelo do PDF.");
  }
};

