        // Parte Principal
        doc.setFont("helvetica", "bold");
        doc.setFontSize(28);
        doc.setTextColor(cirionShadow);
        doc.text(mainText, startX + 0.4, startY + 0.4);
        doc.setTextColor(cirionBlue);
        doc.text(mainText, startX, startY);

        // Subtexto
        doc.setFontSize(9);
        doc.setCharSpace(1.5);
        doc.setTextColor(cirionShadow);
        doc.text(subText, startX + 0.8, startY + 7.3);
        doc.setTextColor(cirionBlue);
        doc.text(subText, startX + 0.5, startY + 7);
        doc.setCharSpace(0);
      }

      // Título e Checkboxes
      doc.setFontSize(11);
      doc.setTextColor(boxBlue);
      const titleText = logoPref === 'cirion' ? "Declaração de Equipamento Cirion" : "Declaração de Entrega de Equipamento";
      doc.text(titleText, 85, 20);

      doc.setDrawColor(boxBlue);
      doc.setLineWidth(0.3);

      // Checkbox Entrega
      doc.rect(85, 23, 3, 3);
      if (isEntregue) doc.text("x", 86, 25.5);
      doc.setFontSize(9);
      doc.text("Entrega", 90, 25.5);

      // Checkbox Devolução
      doc.rect(110, 23, 3, 3);
      if (!isEntregue) doc.text("x", 111, 25.5);
      doc.text("Devolução", 115, 25.5);

      // 2. Texto de Introdução
      doc.setFontSize(9);
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "normal");
      doc.text("Eu, ", 20, 40);
      doc.line(26, 40.5, 95, 40.5);
      doc.setFont("helvetica", "bold");
      doc.text(exchange.colaborador_nome, 28, 40);
      doc.setFont("helvetica", "normal");
      doc.text("declaro ter recebido/devolvido o", 97, 40);
      doc.text("equipamento e acessórios abaixo descritos, em perfeitas condições de funcionamento.", 20, 45);

      // 3. Campos de Dados
      let y = 55;
      const LABEL_X = 20;
      const FIELD_X = 40;
      const BOX_WIDTH = 100;

      const drawField = (label: string, value: string, width: number = BOX_WIDTH, customX: number = FIELD_X) => {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(0, 0, 0);
        doc.text(label, LABEL_X, y + 4.5);

        doc.setDrawColor(boxBlue);
        doc.rect(customX, y, width, 6);
        doc.setFont("helvetica", "normal");
        doc.text(value || "", customX + 2, y + 4.5);
        y += 8;
      };

      drawField("Tipo:", String(exchange[`${prefix}tipo` as keyof AssetExchange]));
      drawField("Marca:", String(exchange[`${prefix}marca` as keyof AssetExchange]));
      drawField("Modelo:", String(exchange[`${prefix}modelo` as keyof AssetExchange]));
      drawField("Número de Serie / Imei:", String(exchange[`${prefix}serial` as keyof AssetExchange]), 82, 68);
      drawField("Estado:", String(exchange[`${prefix}condicao` as keyof AssetExchange]), 25);

      y += 2;
      doc.setFont("helvetica", "bold");
      doc.text("Tamanho do HD:", 20, y + 4.5);
      doc.rect(58, y, 30, 6);
      doc.setFont("helvetica", "normal");
      doc.text(String(exchange[`${prefix}armazenamento` as keyof AssetExchange]), 60, y + 4.5);
      y += 8;

      drawField("Processador:", String(exchange[`${prefix}processador` as keyof AssetExchange]), 150, 50);

      doc.setFont("helvetica", "bold");
      doc.text("Memória:", 20, y + 4.5);
      doc.rect(42, y, 25, 6);
      doc.setFont("helvetica", "normal");
      doc.text(String(exchange[`${prefix}memoria` as keyof AssetExchange]), 44, y + 4.5);
      y += 15;

      // 4. Caixa de Acessórios
      doc.setFontSize(12);
      doc.setFont("helvetica", "bold");
      doc.text("Acessórios:", 105, y, { align: "center" });
      y += 4;

      doc.setDrawColor(boxBlue);
      doc.rect(45, y, 120, 20);

      const accessories = ["Mouse", "Teclado", "Headset", "Mochila", "DockStation", "Monitor"];
      const selectedAccs = (exchange[`${prefix}acessorios` as keyof AssetExchange] as string[]) || [];

      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      let accX = 65;
      let accY = y + 5;

      accessories.forEach((acc, index) => {
        doc.rect(accX, accY - 2.5, 3, 3);
        if (selectedAccs.includes(acc)) doc.text("x", accX + 0.8, accY);
        doc.text(acc, accX + 5, accY);

        if (index === 2) {
          accX = 110;
          accY = y + 5;
        } else {
          accY += 6;
        }
      });

      y += 35;

      // 5. Observações
      doc.setFontSize(11);
      doc.setFont("helvetica", "bold");
      doc.text("Obs:", 20, y + 4.5);
      doc.rect(32, y, 150, 6);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.text(exchange.observacoes || "", 34, y + 4.5);

      y += 25;

      // 6. Rodapé Legal
      doc.setFontSize(8);
      doc.setDrawColor(0, 0, 0);
      doc.line(20, y, 85, y);

      doc.setFont("helvetica", "bold");
      doc.text(exchange.colaborador_nome, 52.5, y - 1, { align: 'center' });

      doc.setFont("helvetica", "normal");
      const footerCompany = logoPref === 'cirion' ? "Cirion Technologies" : "nossa organização";
      doc.text(`compromete-se a usar e devolver os equipamentos e acessórios`, 87, y);
      y += 4;
      const footerText = `fornecidos pela empresa em perfeitas condições e com todas as informações, arquivos, contatos, arquivos de dados pessoais, e-mails, documentos de propriedades da ${footerCompany} e / ou qualquer uma das suas filiais, no término do seu contrato de trabalho ou no final do período de autorização, sem as alterar, modificar, copiar, transferir, no estado em que foram entregues e sempre observando o princípio da confidencialidade. Se compromete em notificar o responsável de TI em caso de perda ou destruição do laptop, para que as medidas de segurança necessárias para a proteção de dados sejam aplicadas.`;
      const splitText = doc.splitTextToSize(footerText, 175);
      doc.text(splitText, 20, y);

      y += 30;

      // 7. Data e Assinaturas
      const date = new Date(exchange.data_troca + 'T12:00:00');
      const months = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
      const dateStr = `Data: ${date.getDate()} de ${months[date.getMonth()]} de ${date.getFullYear()}`;
      doc.setFontSize(10);
      doc.setFont("helvetica", "bold");
      doc.text(dateStr, 20, y);

      y += 25;
      doc.setDrawColor(0, 0, 0);
      doc.line(20, y, 75, y);
      doc.line(120, y, 185, y);

      doc.setFontSize(8);
      doc.setFont("helvetica", "normal");

      const tiLabel = logoPref === 'cirion' ? "TI - Cirion: Gilberto Araujo" : "Responsável TI: Gilberto Araujo";
      const colabLabel = logoPref === 'cirion' ? `Colaborador Cirion: ${exchange.colaborador_nome}` : `Colaborador: ${exchange.colaborador_nome}`;

      doc.text(tiLabel, 47.5, y + 4, { align: 'center' });
      doc.text(colabLabel, 152.5, y + 4, { align: 'center' });

      // Assinaturas Digitais
      doc.setFont("times", "italic");
      doc.setFontSize(18);
      doc.setTextColor(inkBlue);

      if (exchange.assinatura_ti) {
        doc.text(exchange.assinatura_ti, 47.5, y - 2, { align: 'center' });
      }

      if (exchange.assinatura_colaborador) {
        doc.text(exchange.assinatura_colaborador, 152.5, y - 2, { align: 'center' });
      }
    };

    renderPage(true);
    doc.addPage();
    renderPage(false);

    const fileNamePrefix = logoPref === 'cirion' ? 'Termo_Cirion' : 'Termo_Equipamento';
    doc.save(`${fileNamePrefix}_${exchange.colaborador_nome.replace(/\s+/g, '_')}.pdf`);
  } catch (error) {
    console.error("Erro ao gerar PDF:", error);
    alert("Erro ao processar o modelo do PDF.");
  }
};

import React, { useState, useEffect } from 'react';
import { PlusCircle, ClipboardList, LogOut, CheckCircle2, AlertCircle, Mail, Loader2, HardDrive, Settings, Image as ImageIcon } from 'lucide-react';
import { View, AssetExchange, MockEmail, LogoPreference } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';
import MockInbox from './components/MockInbox';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [emails, setEmails] = useState<MockEmail[]>([]);
  const [editingExchange, setEditingExchange] = useState<AssetExchange | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [logoPref, setLogoPref] = useState<LogoPreference>(
    (localStorage.getItem('logo_preference') as LogoPreference) || 'cirion'
  );

  useEffect(() => {
    loadData();
    const savedEmails = localStorage.getItem('mock_emails');
    if (savedEmails) setEmails(JSON.parse(savedEmails));
  }, []);

  const loadData = async () => {
    const data = await apiService.getAll();
    setExchanges(data);
  };

  useEffect(() => {
    localStorage.setItem('mock_emails', JSON.stringify(emails));
  }, [emails]);

  useEffect(() => {
    localStorage.setItem('logo_preference', logoPref);
  }, [logoPref]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  const handleSaveExchange = async (exchange: AssetExchange) => {
    setIsLoading(true);
    try {
      await apiService.save(exchange);
      await loadData();

      setEditingExchange(null);
      setCurrentView('inventory');
      showNotification("Registro gravado com sucesso.");
    } catch (error) {
      console.error("Erro ao gravar:", error);
      showNotification("Houve um erro ao salvar o registro.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkImport = async (data: AssetExchange[]) => {
    setIsLoading(true);
    try {
      for (const item of data) {
        await apiService.save(item);
      }
      await loadData();
      showNotification(`${data.length} registros importados/sincronizados.`);
    } catch (error) {
      showNotification("Falha na importação em massa.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignSender = async (id: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === id);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_ti: signature, 
      status: 'pending_receiver' 
    };

    await apiService.save(updated);
    await loadData();

    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: id,
      from: 'TI Infra - AssetFlow <infra@cirion.com>',
      to: exchange.colaborador_email,
      subject: `[AÇÃO NECESSÁRIA] Termo de Troca de Ativos - ${exchange.colaborador_nome}`,
      body: `Olá ${exchange.colaborador_nome},\n\nO seu novo equipamento foi registrado. Por favor, revise o termo de entrega e devolução em anexo, assine digitalmente e retorne para nós.\n\nAtenciosamente,\nEquipe de TI`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([newEmail, ...emails]);
    showNotification("Termo assinado e enviado para o Outlook.");
  };

  const handleSignReceiver = async (exchangeId: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === exchangeId);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_colaborador: signature, 
      status: 'completed' 
    };

    await apiService.save(updated);
    await loadData();

    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.colaborador_nome} <${exchange.colaborador_email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.colaborador_nome}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.colaborador_nome}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador.");
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Deseja realmente excluir este registro permanentemente?")) {
      await apiService.delete(id);
      await loadData();
      setEmails(prev => prev.filter(email => email.exchangeId !== id));
      showNotification("Registro removido.", "error");
    }
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-sky-50 text-slate-900 font-sans">
      <aside className="w-full md:w-64 bg-slate-900 text-white flex-shrink-0 flex flex-col shadow-2xl z-20">
        <div className="p-8 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <HardDrive className="text-white" size={20} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">AssetFlow</h1>
            <span className="text-[10px] text-indigo-400 font-bold tracking-widest uppercase">
              {logoPref === 'cirion' ? 'Cirion TI' : logoPref === 'generic' ? 'Gestão TI' : 'Admin'}
            </span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4">
          <button
            disabled={isLoading}
            onClick={() => { setEditingExchange(null); setCurrentView('form'); }}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'form' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <PlusCircle size={20} />
            <span className="font-semibold text-sm">Nova Troca</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => setCurrentView('inventory')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'inventory' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <ClipboardList size={20} />
            <span className="font-semibold text-sm">Inventário</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => setCurrentView('inbox')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 relative ${currentView === 'inbox' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <Mail size={20} />
            <span className="font-semibold text-sm">Outlook Mock</span>
            {emails.some(e => !e.read) && (
              <span className="absolute right-4 top-1/2 -translate-y-1/2 w-2 h-2 bg-indigo-400 rounded-full"></span>
            )}
          </button>
        </nav>

        {/* Logo Selection Menu */}
        <div className="px-4 py-6 border-t border-slate-800 space-y-3">
          <div className="flex items-center gap-2 text-[10px] text-slate-500 uppercase font-bold tracking-widest ml-2">
            <ImageIcon size={12} /> Config. Logotipo
          </div>
          <div className="grid grid-cols-1 gap-1">
            <button 
              onClick={() => setLogoPref('cirion')}
              className={`text-left px-4 py-2 rounded-lg text-xs font-bold transition-all ${logoPref === 'cirion' ? 'bg-slate-800 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Cirion Technologies
            </button>
            <button 
              onClick={() => setLogoPref('generic')}
              className={`text-left px-4 py-2 rounded-lg text-xs font-bold transition-all ${logoPref === 'generic' ? 'bg-slate-800 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Empresa Genérica
            </button>
            <button 
              onClick={() => setLogoPref('none')}
              className={`text-left px-4 py-2 rounded-lg text-xs font-bold transition-all ${logoPref === 'none' ? 'bg-slate-800 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Sem Logotipo
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <button className="w-full flex items-center gap-4 px-4 py-3 text-slate-500 hover:text-rose-400 transition-colors">
            <LogOut size={20} />
            <span className="font-semibold text-sm">Sair</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-auto p-6 md:p-10 relative">
        {notification && (
          <div className={`fixed top-6 right-6 z-[200] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border animate-in slide-in-from-top-6 duration-300 ${notification.type === 'success' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            <p className="font-bold text-sm">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto space-y-8">
          <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">
                {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
                 currentView === 'inventory' ? 'Inventário de Ativos' : 'Caixa de Entrada'}
              </h2>
              <p className="text-slate-500 font-medium">Modo Offline Seguro: LocalStorage + Excel Sync</p>
            </div>
            {isLoading && (
              <div className="flex items-center gap-2 text-indigo-600 font-bold bg-indigo-50 px-4 py-2 rounded-xl border border-indigo-100">
                <Loader2 className="animate-spin" size={18} />
                <span className="text-xs uppercase tracking-widest">Sincronizando Dados...</span>
              </div>
            )}
          </header>

          <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/60 border border-slate-100 overflow-hidden min-h-[600px]">
            {currentView === 'form' && (
              <AssetForm 
                onSave={handleSaveExchange} 
                editingExchange={editingExchange} 
                onCancel={() => setCurrentView('inventory')} 
                exchanges={exchanges}
              />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDelete} 
                onEdit={(ex) => { setEditingExchange(ex); setCurrentView('form'); }} 
                onNotify={showNotification}
                onSignSender={handleSignSender}
                onBulkImport={handleBulkImport}
                logoPref={logoPref}
              />
            )}
            {currentView === 'inbox' && (
              <MockInbox 
                emails={emails} 
                onUpdateEmails={setEmails} 
                exchanges={exchanges}
                onSignReceiver={handleSignReceiver}
                logoPref={logoPref}
              />
            )}
          </div>
        </div>

        <footer className="max-w-6xl mx-auto mt-12 flex justify-between items-center text-slate-400 text-[10px] font-bold uppercase tracking-wider px-4">
          <p>© 2025 AssetFlow Technologies</p>
          <div className="flex gap-4">
            <span>Logo Ativo: {logoPref === 'cirion' ? 'Cirion' : logoPref === 'generic' ? 'Genérico' : 'Nenhum'}</span>
            <span>Tipo: Armazenamento Local</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { AssetExchange, LogoPreference } from '../types';
import { FileDown, Trash2, Search, FileSpreadsheet, Pencil, Mail, Laptop, Smartphone, Cpu, Clock, Lock, FileCheck, Upload } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';
import { exportToExcel, importFromExcel } from '../services/excelService';
import SenderSignatureModal from './SenderSignatureModal';

interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
  onSignSender: (id: string, signature: string) => void;
  onBulkImport: (data: AssetExchange[]) => void;
  logoPref: LogoPreference;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify, onSignSender, onBulkImport, logoPref }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = exchanges.filter(e => 
    e.colaborador_nome.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.entregue_serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.devolvido_serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const data = await importFromExcel(file);
      if (confirm(`Deseja importar ${data.length} registros? Isso poderá sobrescrever dados existentes com o mesmo ID.`)) {
        onBulkImport(data);
        onNotify("Base de dados sincronizada com sucesso!", "success");
      }
    } catch (err) {
      onNotify("Erro ao ler arquivo Excel. Verifique o formato.", "error");
    }
    e.target.value = ''; // Reset input
  };

  const getIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('note')) return <Laptop size={14} />;
    if (t.includes('smart')) return <Smartphone size={14} />;
    return <Cpu size={14} />;
  };

  return (
    <div className="flex flex-col h-full">
      <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            placeholder="Buscar no banco de dados..."
            className="w-full pl-10 pr-4 py-2 rounded-xl border"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-2">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept=".xlsx, .xls" 
            className="hidden" 
          />
          <button 
            onClick={handleImportClick}
            className="flex items-center gap-2 bg-slate-100 text-slate-600 px-4 py-2 rounded-xl font-bold border border-slate-200 transition-all hover:bg-slate-200 active:scale-95"
          >
            <Upload size={18} /> Importar Base
          </button>
          <button 
            onClick={() => exportToExcel(exchanges)} 
            className="flex items-center gap-2 bg-emerald-600 text-white px-5 py-2 rounded-xl font-bold shadow-lg shadow-emerald-100 transition-all hover:bg-emerald-700 active:scale-95"
          >
            <FileSpreadsheet size={18} /> Exportar Excel
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Colaborador</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Entregue</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Devolvido</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-center">Status</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-right">Ações</th>
            </tr>
