                      <span className="inline-flex items-center gap-2 bg-slate-100 text-slate-600 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-slate-200">
                        <Pencil size={14} />
                        RASCUNHO
