                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      {ex.status === 'draft' && (
                        <button onClick={() => setSigningExchange(ex)} title="Enviar para assinatura" className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><Mail size={16}/></button>
                      )}
                      {ex.status !== 'completed' ? (
                        <button onClick={() => onEdit(ex)} title="Editar registro" className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Pencil size={16}/></button>
                      ) : (
                        <div className="p-2 text-slate-300" title="Registro Finalizado"><Lock size={16}/></div>
                      )}
                      <button onClick={() => generateAssetPDF(ex, logoPref)} title="Gerar PDF" className="p-2 text-slate-600 hover:bg-slate-50 rounded-lg"><FileDown size={16}/></button>
                      <button onClick={() => onDelete(ex.id)} title="Excluir" className="p-2 text-rose-600 hover:bg-rose-50 rounded-lg"><Trash2 size={16}/></button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {signingExchange && (
        <SenderSignatureModal 
          exchange={signingExchange}
          onClose={() => setSigningExchange(null)}
          onConfirm={(id, sig) => { onSignSender(id, sig); setSigningExchange(null); }}
        />
      )}
    </div>
  );
};

export default InventoryTable;

import React, { useState } from 'react';
import { MockEmail, AssetExchange, LogoPreference } from '../types';
import { Mail, Trash2, Clock, Paperclip, PenLine, ShieldCheck, X } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';

interface MockInboxProps {
  emails: MockEmail[];
  exchanges: AssetExchange[];
  onUpdateEmails: (emails: MockEmail[]) => void;
  onSignReceiver: (id: string, signature: string) => void;
  logoPref: LogoPreference;
}

const MockInbox: React.FC<MockInboxProps> = ({ emails, onUpdateEmails, exchanges, onSignReceiver, logoPref }) => {
  const [selectedId, setSelectedId] = useState<string | null>(emails[0]?.id || null);
  const [signingExchangeId, setSigningExchangeId] = useState<string | null>(null);
  const [receiverSignature, setReceiverSignature] = useState('');

  const selectedEmail = emails.find(e => e.id === selectedId);
  const currentExchange = exchanges.find(ex => ex.id === selectedEmail?.exchangeId);

  const markAsRead = (id: string) => {
    const updated = emails.map(e => e.id === id ? { ...e, read: true } : e);
    onUpdateEmails(updated);
    setSelectedId(id);
  };

  const handleReceiverSign = (e: React.FormEvent) => {
    e.preventDefault();
    if (!receiverSignature.trim() || !signingExchangeId) return;

    onSignReceiver(signingExchangeId, receiverSignature);
    setSigningExchangeId(null);
    setReceiverSignature('');
  };

  if (emails.length === 0) {
    return (
      <div className="p-20 flex flex-col items-center justify-center text-center bg-white h-[600px]">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <Mail className="text-slate-300" size={32} />
        </div>
        <h3 className="text-xl font-bold text-slate-800">Sua caixa do Outlook está vazia</h3>
        <p className="text-slate-500 mt-2 max-w-xs">E-mails de termos enviados para assinatura aparecerão aqui.</p>
      </div>
    );
  }

  return (
    <div className="flex h-[700px] bg-white text-slate-900">
      {/* Sidebar List */}
      <div className="w-1/3 border-r border-slate-100 flex flex-col">
        <div className="p-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Inbox - Outlook</span>
        </div>
        <div className="flex-1 overflow-auto">
          {emails.map(email => (
            <div
              key={email.id}
              onClick={() => markAsRead(email.id)}
              className={`p-4 cursor-pointer border-b border-slate-50 transition-colors relative group ${selectedId === email.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}
            >
              {!email.read && <div className="absolute left-1 top-1/2 -translate-y-1/2 w-1.5 h-1.5 bg-blue-600 rounded-full"></div>}
              <div className="flex justify-between items-start mb-1">
                <span className={`text-xs truncate max-w-[120px] ${!email.read ? 'font-bold text-slate-900' : 'text-slate-600'}`}>{email.from.split('<')[0]}</span>
                <span className="text-[10px] text-slate-400">{new Date(email.sentAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <h4 className={`text-xs truncate ${!email.read ? 'font-bold text-slate-800' : 'text-slate-500'}`}>{email.subject}</h4>

              <button 
                onClick={(e) => { e.stopPropagation(); onUpdateEmails(emails.filter(em => em.id !== email.id)); }}
                className="absolute right-2 bottom-2 p-1.5 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* Email Body */}
      <div className="flex-1 flex flex-col bg-white">
        {selectedEmail ? (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            <div className="p-8 border-b border-slate-100 bg-slate-50">
              <h2 className="text-2xl font-bold text-slate-800 mb-6">{selectedEmail.subject}</h2>
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold text-lg shadow-lg">
                  {selectedEmail.from.charAt(0)}
                </div>
                <div className="flex-1">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-slate-900">{selectedEmail.from}</span>
                    <div className="flex items-center gap-1 text-xs text-slate-400">
                      <Clock size={12} />
                      {new Date(selectedEmail.sentAt).toLocaleString('pt-BR')}
                    </div>
                  </div>
                  <div className="text-sm text-slate-500 font-medium">Para: Você ({selectedEmail.to})</div>
                </div>
              </div>
            </div>

            <div className="flex-1 p-8 overflow-auto">
              <div className="max-w-2xl bg-white border border-slate-100 rounded-2xl shadow-sm p-8 whitespace-pre-wrap text-slate-700 leading-relaxed font-sans">
                {selectedEmail.body}

                {selectedEmail.attachment && currentExchange && (
                  <div className="mt-12 pt-8 border-t border-slate-100">
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Anexo Seguro (PDF):</p>
                    <div 
                      onClick={() => generateAssetPDF(currentExchange, logoPref)}
                      className="flex items-center gap-3 p-4 bg-slate-50 rounded-xl border border-slate-200 w-fit group cursor-pointer hover:border-blue-300 transition-colors"
                    >
                      <div className="bg-rose-100 text-rose-600 p-2 rounded-lg">
                        <Paperclip size={20} />
                      </div>
                      <div>
                        <p className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors">Termo_Ativos.pdf</p>
                        <p className="text-[10px] text-slate-500">142 KB - PDF Gerado com Assinatura Digital</p>
                      </div>
                    </div>
                  </div>
                )}

                {currentExchange && currentExchange.status === 'pending_receiver' && (
                  <div className="mt-10 flex flex-col items-center gap-4 border-t border-blue-50 pt-8">
                    <p className="text-sm text-slate-500 italic text-center">A assinatura do TI já foi aplicada. Agora é sua vez.</p>
                    <button 
                      onClick={() => setSigningExchangeId(currentExchange.id)}
                      className="bg-blue-600 hover:bg-blue-700 text-white px-10 py-4 rounded-2xl font-bold shadow-xl shadow-blue-200 transition-all hover:scale-105"
                    >
                      REVISAR E ASSINAR TERMO
                    </button>
                  </div>
                )}

                {currentExchange && currentExchange.status === 'completed' && (
                  <div className="mt-10 flex flex-col items-center gap-3 p-6 bg-emerald-50 rounded-2xl border border-emerald-100">
                    <ShieldCheck className="text-emerald-600" size={32} />
                    <p className="text-emerald-800 font-bold">Documento Finalizado e Assinado por Ambas as Partes</p>
                    <button 
                      onClick={() => generateAssetPDF(currentExchange, logoPref)}
                      className="text-[11px] font-bold text-emerald-600 underline"
                    >
                      Baixar Versão Final com todas as assinaturas
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
            <Mail size={48} className="mb-4 opacity-10" />
            <p className="font-medium text-slate-400">Selecione uma mensagem do Outlook para visualizar</p>
          </div>
        )}
      </div>

      {/* Modal de Assinatura do Colaborador */}
      {signingExchangeId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-800 flex items-center gap-2">
                <PenLine className="text-blue-600" size={20} /> Assinatura do Colaborador
              </h3>
              <button onClick={() => setSigningExchangeId(null)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>
            <form onSubmit={handleReceiverSign} className="p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Sua Assinatura Digital</label>
                <input
                  required
                  autoFocus
                  type="text"
                  value={receiverSignature}
                  onChange={(e) => setReceiverSignature(e.target.value)}
                  placeholder="Seu nome conforme o crachá"
                  className="w-full h-24 bg-white border-2 border-dashed border-slate-200 rounded-2xl text-center font-signature text-5xl text-blue-800 focus:outline-none focus:border-blue-500 focus:bg-white placeholder:text-slate-200 placeholder:font-sans placeholder:text-base"
                />
              </div>
              <p className="text-xs text-slate-500 leading-relaxed">
                Ao clicar em confirmar, você declara estar de acordo com o termo de recebimento/devolução de equipamentos e uma cópia assinada será enviada automaticamente para a TI via Outlook.
              </p>
              <button
                type="submit"
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold shadow-xl transition-all"
              >
                Confirmar Assinatura e Devolver Termo
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MockInbox;

export enum EquipmentCondition {
  NEW = "Novo",
  USED = "Usado"
}

export type LogoPreference = 'cirion' | 'none';

export interface AssetExchange {
  id: string;
  status: 'draft' | 'pending_receiver' | 'completed';
  timestamp: number;

  // Dados do Colaborador
  colaborador_nome: string;
  colaborador_email: string;
  data_troca: string;
  observacoes: string;

  // Equipamento ENTREGUE
  entregue_tipo: string;
  entregue_marca: string;
  entregue_modelo: string;
  entregue_serial: string;
  entregue_processador: string;
  entregue_condicao: EquipmentCondition;
  entregue_memoria: string;
  entregue_armazenamento: string;
  entregue_acessorios: string[];

  // Equipamento DEVOLVIDO
  devolvido_tipo: string;
  devolvido_marca: string;
  devolvido_modelo: string;
  devolvido_serial: string;
  devolvido_processador: string;
  devolvido_condicao: EquipmentCondition;
  devolvido_memoria: string;
  devolvido_armazenamento: string;
  devolvido_acessorios: string[];

  // Assinaturas
  assinatura_ti?: string;
  assinatura_colaborador?: string;
}

export interface MockEmail {
  id: string;
  to: string;
  from: string;
  subject: string;
  body: string;
  sentAt: string;
  read: boolean;
  exchangeId: string;
  attachment?: boolean;
}

export type View = 'form' | 'inventory' | 'inbox';

import React, { useState, useEffect } from 'react';
import { PlusCircle, ClipboardList, LogOut, CheckCircle2, AlertCircle, Mail, Loader2, HardDrive, Settings, Image as ImageIcon } from 'lucide-react';
import { View, AssetExchange, MockEmail, LogoPreference } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';
import MockInbox from './components/MockInbox';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [emails, setEmails] = useState<MockEmail[]>([]);
  const [editingExchange, setEditingExchange] = useState<AssetExchange | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [logoPref, setLogoPref] = useState<LogoPreference>(() => {
    const saved = localStorage.getItem('logo_preference');
    return (saved === 'cirion' || saved === 'none') ? saved : 'cirion';
  });

  useEffect(() => {
    loadData();
    const savedEmails = localStorage.getItem('mock_emails');
    if (savedEmails) setEmails(JSON.parse(savedEmails));
  }, []);

  const loadData = async () => {
    const data = await apiService.getAll();
    setExchanges(data);
  };

  useEffect(() => {
    localStorage.setItem('mock_emails', JSON.stringify(emails));
  }, [emails]);

  useEffect(() => {
    localStorage.setItem('logo_preference', logoPref);
  }, [logoPref]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  const handleSaveExchange = async (exchange: AssetExchange) => {
    setIsLoading(true);
    try {
      await apiService.save(exchange);
      await loadData();

      setEditingExchange(null);
      setCurrentView('inventory');
      showNotification("Registro gravado com sucesso.");
    } catch (error) {
      console.error("Erro ao gravar:", error);
      showNotification("Houve um erro ao salvar o registro.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkImport = async (data: AssetExchange[]) => {
    setIsLoading(true);
    try {
      for (const item of data) {
        await apiService.save(item);
      }
      await loadData();
      showNotification(`${data.length} registros importados/sincronizados.`);
    } catch (error) {
      showNotification("Falha na importação em massa.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignSender = async (id: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === id);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_ti: signature, 
      status: 'pending_receiver' 
    };

    await apiService.save(updated);
    await loadData();

    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: id,
      from: 'TI Infra - AssetFlow <infra@cirion.com>',
      to: exchange.colaborador_email,
      subject: `[AÇÃO NECESSÁRIA] Termo de Troca de Ativos - ${exchange.colaborador_nome}`,
      body: `Olá ${exchange.colaborador_nome},\n\nO seu novo equipamento foi registrado. Por favor, revise o termo de entrega e devolução em anexo, assine digitalmente e retorne para nós.\n\nAtenciosamente,\nEquipe de TI`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([newEmail, ...emails]);
    showNotification("Termo assinado e enviado para o Outlook.");
  };

  const handleSignReceiver = async (exchangeId: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === exchangeId);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_colaborador: signature, 
      status: 'completed' 
    };

    await apiService.save(updated);
    await loadData();

    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.colaborador_nome} <${exchange.colaborador_email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.colaborador_nome}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.colaborador_nome}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador.");
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Deseja realmente excluir este registro permanentemente?")) {
      await apiService.delete(id);
      await loadData();
      setEmails(prev => prev.filter(email => email.exchangeId !== id));
      showNotification("Registro removido.", "error");
    }
  };

  return (
    <div className="flex flex-col md:flex-row min-h-screen bg-sky-50 text-slate-900 font-sans">
      <aside className="w-full md:w-64 bg-slate-900 text-white flex-shrink-0 flex flex-col shadow-2xl z-20">
        <div className="p-8 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <HardDrive className="text-white" size={20} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">AssetFlow</h1>
            <span className="text-[10px] text-indigo-400 font-bold tracking-widest uppercase">
              {logoPref === 'cirion' ? 'Cirion TI' : 'Admin'}
            </span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4">
          <button
            disabled={isLoading}
            onClick={() => { setEditingExchange(null); setCurrentView('form'); }}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'form' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <PlusCircle size={20} />
            <span className="font-semibold text-sm">Nova Troca</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => setCurrentView('inventory')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'inventory' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <ClipboardList size={20} />
            <span className="font-semibold text-sm">Inventário</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => setCurrentView('inbox')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 relative ${currentView === 'inbox' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <Mail size={20} />
            <span className="font-semibold text-sm">Outlook Mock</span>
            {emails.some(e => !e.read) && (
              <span className="absolute right-4 top-1/2 -translate-y-1/2 w-2 h-2 bg-indigo-400 rounded-full"></span>
            )}
          </button>
        </nav>

        {/* Logo Selection Menu */}
        <div className="px-4 py-6 border-t border-slate-800 space-y-3">
          <div className="flex items-center gap-2 text-[10px] text-slate-500 uppercase font-bold tracking-widest ml-2">
            <ImageIcon size={12} /> Config. Logotipo
          </div>
          <div className="grid grid-cols-1 gap-1">
            <button 
              onClick={() => setLogoPref('cirion')}
              className={`text-left px-4 py-2 rounded-lg text-xs font-bold transition-all ${logoPref === 'cirion' ? 'bg-slate-800 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Cirion Technologies
            </button>
            <button 
              onClick={() => setLogoPref('none')}
              className={`text-left px-4 py-2 rounded-lg text-xs font-bold transition-all ${logoPref === 'none' ? 'bg-slate-800 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Sem Logotipo
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <button className="w-full flex items-center gap-4 px-4 py-3 text-slate-500 hover:text-rose-400 transition-colors">
            <LogOut size={20} />
            <span className="font-semibold text-sm">Sair</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-auto p-6 md:p-10 relative">
        {notification && (
          <div className={`fixed top-6 right-6 z-[200] flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border animate-in slide-in-from-top-6 duration-300 ${notification.type === 'success' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
            <p className="font-bold text-sm">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto space-y-8">
          <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">
                {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
                 currentView === 'inventory' ? 'Inventário de Ativos' : 'Caixa de Entrada'}
              </h2>
              <p className="text-slate-500 font-medium">Modo Offline Seguro: LocalStorage + Excel Sync</p>
            </div>
            {isLoading && (
              <div className="flex items-center gap-2 text-indigo-600 font-bold bg-indigo-50 px-4 py-2 rounded-xl border border-indigo-100">
                <Loader2 className="animate-spin" size={18} />
                <span className="text-xs uppercase tracking-widest">Sincronizando Dados...</span>
              </div>
            )}
          </header>

          <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/60 border border-slate-100 overflow-hidden min-h-[600px]">
            {currentView === 'form' && (
              <AssetForm 
                onSave={handleSaveExchange} 
                editingExchange={editingExchange} 
                onCancel={() => setCurrentView('inventory')} 
                exchanges={exchanges}
              />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDelete} 
                onEdit={(ex) => { setEditingExchange(ex); setCurrentView('form'); }} 
                onNotify={showNotification}
                onSignSender={handleSignSender}
                onBulkImport={handleBulkImport}
                logoPref={logoPref}
              />
            )}
            {currentView === 'inbox' && (
              <MockInbox 
                emails={emails} 
                onUpdateEmails={setEmails} 
                exchanges={exchanges}
                onSignReceiver={handleSignReceiver}
                logoPref={logoPref}
              />
            )}
          </div>
        </div>

        <footer className="max-w-6xl mx-auto mt-12 flex justify-between items-center text-slate-400 text-[10px] font-bold uppercase tracking-wider px-4">
          <p>© 2025 AssetFlow Technologies</p>
          <div className="flex gap-4">
            <span>Logo Ativo: {logoPref === 'cirion' ? 'Cirion' : 'Nenhum'}</span>
            <span>Tipo: Armazenamento Local</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import { jsPDF } from 'jspdf';
import { AssetExchange, LogoPreference } from '../types';

export const generateAssetPDF = (exchange: AssetExchange, logoPref: LogoPreference = 'cirion') => {
  try {
    const doc = new jsPDF({
      orientation: 'p',
      unit: 'mm',
      format: 'a4'
    });

    // Cores extraídas para o efeito 3D e visual
    const cirionBlue = "#1a5edb"; 
    const cirionShadow = "#0a3a8a"; 
    const boxBlue = "#00158a"; 
    const inkBlue = "#003087";

    const renderPage = (isEntregue: boolean) => {
      const prefix = isEntregue ? 'entregue_' : 'devolvido_';

      // 1. Renderização condicional do logotipo
      if (logoPref === 'cirion') {
        const startX = 25;
        const startY = 25;
        const mainText = "CIRION";
        const subText = "TECHNOLOGIES";

        // Parte Principal
        doc.setFont("helvetica", "bold");
        doc.setFontSize(28);
        doc.setTextColor(cirionShadow);
        doc.text(mainText, startX + 0.4, startY + 0.4);
        doc.setTextColor(cirionBlue);
        doc.text(mainText, startX, startY);

        // Subtexto
        doc.setFontSize(9);
        doc.setCharSpace(1.5);
        doc.setTextColor(cirionShadow);
        doc.text(subText, startX + 0.8, startY + 7.3);
        doc.setTextColor(cirionBlue);
        doc.text(subText, startX + 0.5, startY + 7);
        doc.setCharSpace(0);
      }

      // Título e Checkboxes
      doc.setFontSize(11);
      doc.setTextColor(boxBlue);
      const titleText = logoPref === 'cirion' ? "Declaração de Equipamento Cirion" : "Declaração de Entrega de Equipamento";
      doc.text(titleText, 85, 20);

      doc.setDrawColor(boxBlue);
      doc.setLineWidth(0.3);

      // Checkbox Entrega
      doc.rect(85, 23, 3, 3);
      if (isEntregue) doc.text("x", 86, 25.5);
      doc.setFontSize(9);
      doc.text("Entrega", 90, 25.5);

      // Checkbox Devolução
      doc.rect(110, 23, 3, 3);
      if (!isEntregue) doc.text("x", 111, 25.5);
      doc.text("Devolução", 115, 25.5);

      // 2. Texto de Introdução
      doc.setFontSize(9);
      doc.setTextColor(0, 0, 0);
      doc.setFont("helvetica", "normal");
      doc.text("Eu, ", 20, 40);
      doc.line(26, 40.5, 95, 40.5);
      doc.setFont("helvetica", "bold");
      doc.text(exchange.colaborador_nome, 28, 40);
      doc.setFont("helvetica", "normal");
      doc.text("declaro ter recebido/devolvido o", 97, 40);
      doc.text("equipamento e acessórios abaixo descritos, em perfeitas condições de funcionamento.", 20, 45);

      // 3. Campos de Dados
      let y = 55;
      const LABEL_X = 20;
      const FIELD_X = 40;
      const BOX_WIDTH = 100;

      const drawField = (label: string, value: string, width: number = BOX_WIDTH, customX: number = FIELD_X) => {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(0, 0, 0);
        doc.text(label, LABEL_X, y + 4.5);

        doc.setDrawColor(boxBlue);
        doc.rect(customX, y, width, 6);
        doc.setFont("helvetica", "normal");
        doc.text(value || "", customX + 2, y + 4.5);
        y += 8;
      };

      drawField("Tipo:", String(exchange[`${prefix}tipo` as keyof AssetExchange]));
      drawField("Marca:", String(exchange[`${prefix}marca` as keyof AssetExchange]));
      drawField("Modelo:", String(exchange[`${prefix}modelo` as keyof AssetExchange]));
      drawField("Número de Serie / Imei:", String(exchange[`${prefix}serial` as keyof AssetExchange]), 82, 68);
      drawField("Estado:", String(exchange[`${prefix}condicao` as keyof AssetExchange]), 25);

      y += 2;
      doc.setFont("helvetica", "bold");
      doc.text("Tamanho do HD:", 20, y + 4.5);
      doc.rect(58, y, 30, 6);
      doc.setFont("helvetica", "normal");
      doc.text(String(exchange[`${prefix}armazenamento` as keyof AssetExchange]), 60, y + 4.5);
      y += 8;

      drawField("Processador:", String(exchange[`${prefix}processador` as keyof AssetExchange]), 150, 50);

      doc.setFont("helvetica", "bold");
      doc.text("Memória:", 20, y + 4.5);
      doc.rect(42, y, 25, 6);
      doc.setFont("helvetica", "normal");
      doc.text(String(exchange[`${prefix}memoria` as keyof AssetExchange]), 44, y + 4.5);
      y += 15;

      // 4. Caixa de Acessórios
      doc.setFontSize(12);
      doc.setFont("helvetica", "bold");
      doc.text("Acessórios:", 105, y, { align: "center" });
      y += 4;

      doc.setDrawColor(boxBlue);
      doc.rect(45, y, 120, 20);

      const accessories = ["Mouse", "Teclado", "Headset", "Mochila", "DockStation", "Monitor"];
      const selectedAccs = (exchange[`${prefix}acessorios` as keyof AssetExchange] as string[]) || [];

      doc.setFontSize(10);
      doc.setFont("helvetica", "normal");
      let accX = 65;
      let accY = y + 5;

      accessories.forEach((acc, index) => {
        doc.rect(accX, accY - 2.5, 3, 3);
        if (selectedAccs.includes(acc)) doc.text("x", accX + 0.8, accY);
        doc.text(acc, accX + 5, accY);

        if (index === 2) {
          accX = 110;
          accY = y + 5;
        } else {
          accY += 6;
        }
      });

      y += 35;

      // 5. Observações
      doc.setFontSize(11);
      doc.setFont("helvetica", "bold");
      doc.text("Obs:", 20, y + 4.5);
      doc.rect(32, y, 150, 6);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.text(exchange.observacoes || "", 34, y + 4.5);

      y += 25;

      // 6. Rodapé Legal
      doc.setFontSize(8);
      doc.setDrawColor(0, 0, 0);
      doc.line(20, y, 85, y);

      doc.setFont("helvetica", "bold");
      doc.text(exchange.colaborador_nome, 52.5, y - 1, { align: 'center' });

      doc.setFont("helvetica", "normal");
      const footerCompany = logoPref === 'cirion' ? "Cirion Technologies" : "nossa organização";
      doc.text(`compromete-se a usar e devolver os equipamentos e acessórios`, 87, y);
      y += 4;
      const footerText = `fornecidos pela empresa em perfeitas condições e com todas as informações, arquivos, contatos, arquivos de dados pessoais, e-mails, documentos de propriedades da ${footerCompany} e / ou qualquer uma das suas filiais, no término do seu contrato de trabalho ou no final do período de autorização, sem as alterar, modificar, copiar, transferir, no estado em que foram entregues e sempre observando o princípio da confidencialidade. Se compromete em notificar o responsável de TI em caso de perda ou destruição do laptop, para que as medidas de segurança necessárias para a proteção de dados sejam aplicadas.`;
      const splitText = doc.splitTextToSize(footerText, 175);
      doc.text(splitText, 20, y);

      y += 30;

      // 7. Data e Assinaturas
      const date = new Date(exchange.data_troca + 'T12:00:00');
      const months = ["janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
      const dateStr = `Data: ${date.getDate()} de ${months[date.getMonth()]} de ${date.getFullYear()}`;
      doc.setFontSize(10);
      doc.setFont("helvetica", "bold");
      doc.text(dateStr, 20, y);

      y += 25;
      doc.setDrawColor(0, 0, 0);
      doc.line(20, y, 75, y);
      doc.line(120, y, 185, y);

      doc.setFontSize(8);
      doc.setFont("helvetica", "normal");

      const tiLabel = logoPref === 'cirion' ? "TI - Cirion: Gilberto Araujo" : "Responsável TI: Gilberto Araujo";
      const colabLabel = logoPref === 'cirion' ? `Colaborador Cirion: ${exchange.colaborador_nome}` : `Colaborador: ${exchange.colaborador_nome}`;

      doc.text(tiLabel, 47.5, y + 4, { align: 'center' });
      doc.text(colabLabel, 152.5, y + 4, { align: 'center' });

      // Assinaturas Digitais
      doc.setFont("times", "italic");
      doc.setFontSize(18);
      doc.setTextColor(inkBlue);

      if (exchange.assinatura_ti) {
        doc.text(exchange.assinatura_ti, 47.5, y - 2, { align: 'center' });
      }

      if (exchange.assinatura_colaborador) {
        doc.text(exchange.assinatura_colaborador, 152.5, y - 2, { align: 'center' });
      }
    };

    renderPage(true);
    doc.addPage();
    renderPage(false);

    const fileNamePrefix = logoPref === 'cirion' ? 'Termo_Cirion' : 'Termo_Equipamento';
    doc.save(`${fileNamePrefix}_${exchange.colaborador_nome.replace(/\s+/g, '_')}.pdf`);
  } catch (error) {
    console.error("Erro ao gerar PDF:", error);
    alert("Erro ao processar o modelo do PDF.");
  }
};

import React, { useState, useEffect } from 'react';
import { PlusCircle, ClipboardList, LogOut, CheckCircle2, AlertCircle, Mail, Loader2, HardDrive, Menu, X, Image as ImageIcon } from 'lucide-react';
import { View, AssetExchange, MockEmail, LogoPreference } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';
import MockInbox from './components/MockInbox';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [emails, setEmails] = useState<MockEmail[]>([]);
  const [editingExchange, setEditingExchange] = useState<AssetExchange | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [logoPref, setLogoPref] = useState<LogoPreference>(() => {
    const saved = localStorage.getItem('logo_preference');
    return (saved === 'cirion' || saved === 'none') ? saved : 'cirion';
  });

  useEffect(() => {
    loadData();
    const savedEmails = localStorage.getItem('mock_emails');
    if (savedEmails) setEmails(JSON.parse(savedEmails));
  }, []);

  const loadData = async () => {
    const data = await apiService.getAll();
    setExchanges(data);
  };

  useEffect(() => {
    localStorage.setItem('mock_emails', JSON.stringify(emails));
  }, [emails]);

  useEffect(() => {
    localStorage.setItem('logo_preference', logoPref);
  }, [logoPref]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  const handleSaveExchange = async (exchange: AssetExchange) => {
    setIsLoading(true);
    try {
      await apiService.save(exchange);
      await loadData();

      setEditingExchange(null);
      setCurrentView('inventory');
      showNotification("Registro gravado com sucesso.");
    } catch (error) {
      console.error("Erro ao gravar:", error);
      showNotification("Houve um erro ao salvar o registro.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkImport = async (data: AssetExchange[]) => {
    setIsLoading(true);
    try {
      for (const item of data) {
        await apiService.save(item);
      }
      await loadData();
      showNotification(`${data.length} registros importados/sincronizados.`);
    } catch (error) {
      showNotification("Falha na importação em massa.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignSender = async (id: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === id);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_ti: signature, 
      status: 'pending_receiver' 
    };

    await apiService.save(updated);
    await loadData();

    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: id,
      from: 'TI Infra - AssetFlow <infra@cirion.com>',
      to: exchange.colaborador_email,
      subject: `[AÇÃO NECESSÁRIA] Termo de Troca de Ativos - ${exchange.colaborador_nome}`,
      body: `Olá ${exchange.colaborador_nome},\n\nO seu novo equipamento foi registrado. Por favor, revise o termo de entrega e devolução em anexo, assine digitalmente e retorne para nós.\n\nAtenciosamente,\nEquipe de TI`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([newEmail, ...emails]);
    showNotification("Termo assinado e enviado para o Outlook.");
  };

  const handleSignReceiver = async (exchangeId: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === exchangeId);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_colaborador: signature, 
      status: 'completed' 
    };

    await apiService.save(updated);
    await loadData();

    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.colaborador_nome} <${exchange.colaborador_email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.colaborador_nome}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.colaborador_nome}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador.");
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Deseja realmente excluir este registro permanentemente?")) {
      await apiService.delete(id);
      await loadData();
      setEmails(prev => prev.filter(email => email.exchangeId !== id));
      showNotification("Registro removido.", "error");
    }
  };

  const navTo = (view: View) => {
    setEditingExchange(null);
    setCurrentView(view);
    setIsMobileMenuOpen(false);
  };

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-sky-50 text-slate-900 font-sans">
      {/* Mobile Top Header */}
      <header className="lg:hidden bg-slate-900 text-white p-4 flex items-center justify-between sticky top-0 z-[60] shadow-md">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
            <HardDrive className="text-white" size={16} />
          </div>
          <h1 className="text-lg font-bold tracking-tight">AssetFlow</h1>
        </div>
        <button 
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          className="p-2 hover:bg-slate-800 rounded-lg transition-colors"
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {/* Sidebar Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 text-white flex-shrink-0 flex flex-col shadow-2xl z-50 transition-transform duration-300 transform lg:relative lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 hidden lg:flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <HardDrive className="text-white" size={20} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight text-white">AssetFlow</h1>
            <span className="text-[10px] text-indigo-400 font-bold tracking-widest uppercase">
              {logoPref === 'cirion' ? 'Cirion TI' : 'Admin'}
            </span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4 mt-16 lg:mt-0">
          <button
            disabled={isLoading}
            onClick={() => navTo('form')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'form' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <PlusCircle size={20} />
            <span className="font-semibold text-sm">Nova Troca</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inventory')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'inventory' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <ClipboardList size={20} />
            <span className="font-semibold text-sm">Inventário</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inbox')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 relative ${currentView === 'inbox' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white disabled:opacity-50'}`}
          >
            <Mail size={20} />
            <span className="font-semibold text-sm">Outlook Mock</span>
            {emails.some(e => !e.read) && (
              <span className="absolute right-4 top-1/2 -translate-y-1/2 w-2.5 h-2.5 bg-indigo-400 rounded-full border-2 border-slate-900"></span>
            )}
          </button>
        </nav>

        {/* Logo Selection Menu */}
        <div className="px-4 py-6 border-t border-slate-800 space-y-3">
          <div className="flex items-center gap-2 text-[10px] text-slate-500 uppercase font-bold tracking-widest ml-2">
            <ImageIcon size={12} /> Config. Logotipo
          </div>
          <div className="grid grid-cols-1 gap-1">
            <button 
              onClick={() => { setLogoPref('cirion'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
              className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'cirion' ? 'bg-slate-800 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Cirion Technologies
            </button>
            <button 
              onClick={() => { setLogoPref('none'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
              className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'none' ? 'bg-slate-800 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Sem Logotipo
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <button className="w-full flex items-center gap-4 px-4 py-3 text-slate-500 hover:text-rose-400 transition-colors">
            <LogOut size={20} />
            <span className="font-semibold text-sm">Sair</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-x-hidden overflow-y-auto p-4 md:p-10 relative">
        {notification && (
          <div className={`fixed top-4 right-4 md:top-6 md:right-6 z-[200] flex items-center gap-3 px-4 md:px-6 py-3 md:py-4 rounded-xl md:rounded-2xl shadow-2xl border animate-in slide-in-from-top-6 duration-300 w-[calc(100%-2rem)] md:w-auto ${notification.type === 'success' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} className="shrink-0" /> : <AlertCircle size={20} className="shrink-0" />}
            <p className="font-bold text-sm leading-tight">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto space-y-6 md:space-y-8">
          <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-2xl md:text-3xl font-extrabold text-slate-900 tracking-tight">
                {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
                 currentView === 'inventory' ? 'Inventário de Ativos' : 'Caixa de Entrada'}
              </h2>
              <p className="text-slate-500 font-medium text-sm">Modo Offline Seguro: LocalStorage + Excel Sync</p>
            </div>
            {isLoading && (
              <div className="flex items-center gap-2 text-indigo-600 font-bold bg-indigo-50 px-4 py-2 rounded-xl border border-indigo-100 self-start md:self-end">
                <Loader2 className="animate-spin" size={18} />
                <span className="text-xs uppercase tracking-widest">Sincronizando...</span>
              </div>
            )}
          </header>

          <div className="bg-white rounded-2xl md:rounded-[2.5rem] shadow-xl shadow-slate-200/60 border border-slate-100 overflow-hidden min-h-[500px] lg:min-h-[600px]">
            {currentView === 'form' && (
              <AssetForm 
                onSave={handleSaveExchange} 
                editingExchange={editingExchange} 
                onCancel={() => navTo('inventory')} 
                exchanges={exchanges}
              />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDelete} 
                onEdit={(ex) => { setEditingExchange(ex); setCurrentView('form'); }} 
                onNotify={showNotification}
                onSignSender={handleSignSender}
                onBulkImport={handleBulkImport}
                logoPref={logoPref}
              />
            )}
            {currentView === 'inbox' && (
              <MockInbox 
                emails={emails} 
                onUpdateEmails={setEmails} 
                exchanges={exchanges}
                onSignReceiver={handleSignReceiver}
                logoPref={logoPref}
              />
            )}
          </div>
        </div>

        <footer className="max-w-6xl mx-auto mt-8 md:mt-12 flex flex-col sm:flex-row justify-between items-center text-slate-400 text-[10px] font-bold uppercase tracking-wider px-4 gap-2 mb-8 md:mb-0">
          <p>© 2025 AssetFlow Technologies</p>
          <div className="flex gap-4">
            <span>Logo: {logoPref === 'cirion' ? 'Cirion' : 'Nenhum'}</span>
            <span>Armazenamento Local</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS_LIST, PROCESSORS_LIST, MODEL_PROCESSOR_MAP, MEMORY_LIST, STORAGE_LIST } from '../constants';
import { User, Package, History, Send, ScanLine, Lock, MousePointer2, Loader2, CheckSquare } from 'lucide-react';
import BarcodeScannerModal from './BarcodeScannerModal';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => Promise<void> | void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = ["Mouse", "Mochila", "Teclado", "DockStation", "Headset", "Monitor"];

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel }) => {
  const isReadOnly = editingExchange?.status === 'completed';
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState<AssetExchange>({
    id: '',
    status: 'draft',
    timestamp: Date.now(),
    colaborador_nome: '',
    colaborador_email: '',
    data_troca: new Date().toISOString().split('T')[0],
    observacoes: '',
    entregue_tipo: EQUIPMENT_TYPES[0],
    entregue_marca: BRANDS[0],
    entregue_modelo: MODELS_LIST[0],
    entregue_serial: '',
    entregue_processador: PROCESSORS_LIST[0],
    entregue_condicao: EquipmentCondition.NEW,
    entregue_memoria: MEMORY_LIST[2], // Default 16GB
    entregue_armazenamento: STORAGE_LIST[3], // Default 512GB
    entregue_acessorios: [],
    devolvido_tipo: EQUIPMENT_TYPES[0],
    devolvido_marca: BRANDS[0],
    devolvido_modelo: MODELS_LIST[0],
    devolvido_serial: '',
    devolvido_processador: PROCESSORS_LIST[0],
    devolvido_condicao: EquipmentCondition.USED,
    devolvido_memoria: MEMORY_LIST[2], // Default 16GB
    devolvido_armazenamento: STORAGE_LIST[3], // Default 512GB
    devolvido_acessorios: []
  });

  const [scannerConfig, setScannerConfig] = useState<{ isOpen: boolean; target: 'entregue' | 'devolvido' }>({
    isOpen: false,
    target: 'entregue'
  });

  useEffect(() => {
    if (editingExchange) {
      setFormData({ ...editingExchange });
    }
  }, [editingExchange]);

  const handleBrandChange = (brand: string, target: 'entregue' | 'devolvido') => {
    if (target === 'entregue') {
      setFormData({ ...formData, entregue_marca: brand });
    } else {
      setFormData({ ...formData, devolvido_marca: brand });
    }
  };

  const handleModelChange = (model: string, target: 'entregue' | 'devolvido') => {
    const mappedProcessor = MODEL_PROCESSOR_MAP[model];

    if (target === 'entregue') {
      setFormData(prev => ({ 
        ...prev, 
        entregue_modelo: model,
        entregue_processador: mappedProcessor || prev.entregue_processador 
      }));
    } else {
      setFormData(prev => ({ 
        ...prev, 
        devolvido_modelo: model,
        devolvido_processador: mappedProcessor || prev.devolvido_processador 
      }));
    }
  };

  const handleAccessoryToggle = (acc: string, target: 'entregue' | 'devolvido') => {
    const field = target === 'entregue' ? 'entregue_acessorios' : 'devolvido_acessorios';
    const current = formData[field] as string[];
    const updated = current.includes(acc) ? current.filter(i => i !== acc) : [...current, acc];
    setFormData({ ...formData, [field]: updated });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload = {
        ...formData,
        id: formData.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        timestamp: formData.timestamp || Date.now()
      };
      await onSave(payload);
    } catch (err) {
      console.error("Erro ao salvar formulário:", err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-4 md:mb-6 pb-2 border-b border-slate-100">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={18} className="text-white" />
      </div>
      <h3 className="text-base md:text-lg font-semibold text-slate-800">{title}</h3>
    </div>
  );

  return (
    <>
      <form onSubmit={handleSubmit} className="p-4 md:p-8 space-y-8 md:space-y-12">
        {isReadOnly && (
          <div className="bg-amber-50 border border-amber-200 p-4 rounded-xl md:rounded-2xl flex items-center gap-4">
            <Lock size={20} className="text-amber-700 shrink-0" />
            <p className="text-amber-900 text-sm font-bold">Registro Bloqueado por Assinatura</p>
          </div>
        )}

        <section>
          <SectionHeader icon={User} title="Dados do Colaborador" color="bg-indigo-600" />
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 uppercase">Nome Completo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required
                placeholder="Ex: João Silva"
                className="w-full px-4 py-2.5 rounded-xl border bg-white focus:ring-2 focus:ring-indigo-100 transition-all text-sm"
                value={formData.colaborador_nome}
                onChange={e => setFormData({ ...formData, colaborador_nome: e.target.value })}
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 uppercase">E-mail Corporativo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="email"
                placeholder="joao.silva@cirion.com"
                className="w-full px-4 py-2.5 rounded-xl border bg-white focus:ring-2 focus:ring-indigo-100 transition-all text-sm"
                value={formData.colaborador_email}
                onChange={e => setFormData({ ...formData, colaborador_email: e.target.value })}
              />
            </div>
            <div className="space-y-1.5 sm:col-span-2 md:col-span-1">
              <label className="text-xs font-bold text-slate-500 uppercase">Data da Troca</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="date"
                className="w-full px-4 py-2.5 rounded-xl border bg-white focus:ring-2 focus:ring-indigo-100 transition-all text-sm"
                value={formData.data_troca}
                onChange={e => setFormData({ ...formData, data_troca: e.target.value })}
              />
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
          {/* Entregue */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 border border-slate-100">
            <SectionHeader icon={Package} title="Equipamento Entregue" color="bg-emerald-600" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.entregue_tipo} onChange={e => setFormData({...formData, entregue_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.entregue_marca} onChange={e => handleBrandChange(e.target.value, 'entregue')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Modelo</label>
                <select 
                  disabled={isReadOnly || isSubmitting} 
                  className="w-full px-3 py-2 rounded-lg border bg-white text-sm" 
                  value={formData.entregue_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'entregue')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white font-mono text-sm pr-10" value={formData.entregue_serial} onChange={e => setFormData({...formData, entregue_serial: e.target.value})} />
                  {!isReadOnly && !isSubmitting && <button type="button" onClick={() => setScannerConfig({isOpen: true, target: 'entregue'})} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600 transition-colors p-1"><ScanLine size={18}/></button>}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Estado</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.entregue_condicao} onChange={e => setFormData({...formData, entregue_condicao: e.target.value as EquipmentCondition})}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Memória RAM</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.entregue_memoria} onChange={e => setFormData({...formData, entregue_memoria: e.target.value})}>
                  {MEMORY_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Processador</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-[10px]" value={formData.entregue_processador} onChange={e => setFormData({...formData, entregue_processador: e.target.value})}>
                  {PROCESSORS_LIST.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Armazenamento</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.entregue_armazenamento} onChange={e => setFormData({...formData, entregue_armazenamento: e.target.value})}>
                  {STORAGE_LIST.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="mt-6">
              <label className="text-[10px] font-bold text-slate-500 uppercase block mb-3">Acessórios Entregues</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label 
                    key={acc} 
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border cursor-pointer transition-all text-xs font-medium ${formData.entregue_acessorios.includes(acc) ? 'bg-emerald-50 border-emerald-200 text-emerald-700 ring-2 ring-emerald-100' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-200'}`}
                  >
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={formData.entregue_acessorios.includes(acc)} 
                      onChange={() => handleAccessoryToggle(acc, 'entregue')} 
                      disabled={isReadOnly || isSubmitting} 
                    />
                    <CheckSquare size={14} className={`shrink-0 ${formData.entregue_acessorios.includes(acc) ? 'opacity-100' : 'opacity-20'}`} />
                    <span className="truncate">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>

          {/* Devolvido */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 border border-slate-100">
            <SectionHeader icon={History} title="Equipamento Devolvido" color="bg-rose-600" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.devolvido_tipo} onChange={e => setFormData({...formData, devolvido_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.devolvido_marca} onChange={e => handleBrandChange(e.target.value, 'devolvido')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Modelo</label>
