                  value={formData.devolvido_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'devolvido')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Serial / IMEI</label>
                <div className="relative">
