                <label className="text-[10px] font-bold text-slate-500 uppercase">Estado</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.devolvido_condicao} onChange={e => setFormData({...formData, devolvido_condicao: e.target.value as EquipmentCondition})}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Memória RAM</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.devolvido_memoria} onChange={e => setFormData({...formData, devolvido_memoria: e.target.value})}>
                  {MEMORY_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Processador</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-[10px]" value={formData.devolvido_processador} onChange={e => setFormData({...formData, devolvido_processador: e.target.value})}>
                  {PROCESSORS_LIST.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Armazenamento</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white text-sm" value={formData.devolvido_armazenamento} onChange={e => setFormData({...formData, devolvido_armazenamento: e.target.value})}>
                  {STORAGE_LIST.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="mt-6">
              <label className="text-[10px] font-bold text-slate-500 uppercase block mb-3">Acessórios Devolvidos</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label 
                    key={acc} 
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border cursor-pointer transition-all text-xs font-medium ${formData.devolvido_acessorios.includes(acc) ? 'bg-rose-50 border-rose-200 text-rose-700 ring-2 ring-rose-100' : 'bg-white border-slate-200 text-slate-500 hover:border-rose-200'}`}
                  >
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={formData.devolvido_acessorios.includes(acc)} 
                      onChange={() => handleAccessoryToggle(acc, 'devolvido')} 
                      disabled={isReadOnly || isSubmitting} 
                    />
                    <CheckSquare size={14} className={`shrink-0 ${formData.devolvido_acessorios.includes(acc) ? 'opacity-100' : 'opacity-20'}`} />
                    <span className="truncate">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>
        </div>

        <section>
          <SectionHeader icon={MousePointer2} title="Observações Internas" color="bg-slate-700" />
          <textarea 
            disabled={isReadOnly || isSubmitting}
            placeholder="Ex: Teclado do notebook entregue está com a tecla 'A' frouxa."
            className="w-full p-4 rounded-xl md:rounded-2xl border bg-white h-24 focus:ring-2 focus:ring-slate-100 transition-all resize-none text-sm" 
            value={formData.observacoes}
            onChange={e => setFormData({ ...formData, observacoes: e.target.value })}
          />
        </section>

        <div className="flex flex-col-reverse sm:flex-row justify-end items-stretch sm:items-center gap-3 sm:gap-4">
          <button 
            type="button" 
            onClick={onCancel} 
            disabled={isSubmitting}
            className="px-8 py-3.5 rounded-xl md:rounded-2xl font-bold text-slate-500 hover:bg-slate-100 transition-colors disabled:opacity-30 text-sm"
          >
            Cancelar
          </button>
          {!isReadOnly && (
            <button 
              type="submit" 
              disabled={isSubmitting}
              className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-8 md:px-10 py-3.5 rounded-xl md:rounded-2xl font-bold shadow-xl shadow-indigo-600/20 transition-all active:scale-95 disabled:bg-indigo-400 text-sm"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="animate-spin" size={18} />
                  <span>Gravando...</span>
                </>
              ) : (
                <>
                  <Send size={18} />
                  <span>{editingExchange ? 'Salvar Registro' : 'Gravar Registro'}</span>
                </>
              )}
            </button>
          )}
        </div>
      </form>

      {scannerConfig.isOpen && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'entregue' ? 'Lendo Serial Entregue' : 'Lendo Serial Devolvido'}
          onScan={(text) => {
            const processed = text.trim();
            if (scannerConfig.target === 'entregue') setFormData({...formData, entregue_serial: processed});
            else setFormData({...formData, devolvido_serial: processed});
            setScannerConfig({...scannerConfig, isOpen: false});
          }}
          onClose={() => setScannerConfig({...scannerConfig, isOpen: false})}
        />
      )}
    </>
  );
};

