interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
  onSignSender: (id: string, signature: string) => void;
  onBulkImport: (data: AssetExchange[]) => void;
  logoPref: LogoPreference;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify, onSignSender, onBulkImport, logoPref }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = exchanges.filter(e => 
    e.colaborador_nome.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.entregue_serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.devolvido_serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const data = await importFromExcel(file);
      if (confirm(`Deseja importar ${data.length} registros? Isso poderá sobrescrever dados existentes com o mesmo ID.`)) {
        onBulkImport(data);
        onNotify("Base de dados sincronizada com sucesso!", "success");
      }
    } catch (err) {
      onNotify("Erro ao ler arquivo Excel. Verifique o formato.", "error");
    }
    e.target.value = ''; // Reset input
  };

  const getIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('note')) return <Laptop size={14} />;
    if (t.includes('smart')) return <Smartphone size={14} />;
    return <Cpu size={14} />;
  };

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="p-4 md:p-6 border-b flex flex-col xl:flex-row xl:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-full xl:max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            placeholder="Buscar por nome ou serial..."
            className="w-full pl-10 pr-4 py-2.5 rounded-xl border bg-slate-50 focus:bg-white transition-all text-sm outline-none focus:ring-2 focus:ring-indigo-100"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept=".xlsx, .xls" 
            className="hidden" 
          />
          <button 
            onClick={handleImportClick}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-slate-100 text-slate-600 px-4 py-2.5 rounded-xl font-bold border border-slate-200 transition-all hover:bg-slate-200 active:scale-95 text-xs"
          >
            <Upload size={16} /> Importar Base
          </button>
          <button 
            onClick={() => exportToExcel(exchanges)} 
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-emerald-600 text-white px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-emerald-100 transition-all hover:bg-emerald-700 active:scale-95 text-xs"
          >
            <FileSpreadsheet size={16} /> Exportar Excel
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-x-auto custom-scrollbar">
        <table className="w-full text-left min-w-[900px]">
          <thead className="bg-slate-50 sticky top-0 z-10">
            <tr>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider">Colaborador</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider">Equip. Entregue</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider">Equip. Devolvido</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-center tracking-wider">Status</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-right tracking-wider">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-slate-400 italic bg-white">
                  <div className="flex flex-col items-center gap-2">
                    <Search size={32} className="opacity-10" />
                    <p>Nenhum registro encontrado.</p>
                  </div>
                </td>
              </tr>
            ) : (
              filtered.map(ex => (
                <tr key={ex.id} className="hover:bg-slate-50/80 group transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 text-sm">{ex.colaborador_nome}</span>
                      <span className="text-[10px] text-slate-400 font-medium">{ex.colaborador_email}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-[10px] font-bold text-emerald-600 uppercase flex items-center gap-1 mb-0.5">
                        {getIcon(ex.entregue_tipo)} {ex.entregue_tipo}
                      </span>
                      <span className="text-xs font-semibold text-slate-700">{ex.entregue_marca} {ex.entregue_modelo}</span>
                      <span className="text-[10px] font-mono text-slate-400 mt-0.5">S/N: {ex.entregue_serial}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-[10px] font-bold text-rose-600 uppercase flex items-center gap-1 mb-0.5">
                        {getIcon(ex.devolvido_tipo)} {ex.devolvido_tipo}
                      </span>
                      <span className="text-xs font-semibold text-slate-700">{ex.devolvido_marca} {ex.devolvido_modelo}</span>
                      <span className="text-[10px] font-mono text-slate-400 mt-0.5">S/N: {ex.devolvido_serial}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    {ex.status === 'completed' ? (
                      <button 
                        onClick={() => generateAssetPDF(ex, logoPref)}
                        className="inline-flex items-center gap-2 bg-emerald-50 text-emerald-700 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-emerald-100 shadow-sm hover:bg-emerald-100 transition-all active:scale-95 whitespace-nowrap"
                      >
                        <FileCheck size={14} />
                        TERMO ASSINADO
                      </button>
                    ) : ex.status === 'pending_receiver' ? (
                      <span className="inline-flex items-center gap-2 bg-blue-50 text-blue-700 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-blue-100 whitespace-nowrap">
                        <Clock size={14} />
                        AGUARDANDO ASSINATURA
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-2 bg-slate-100 text-slate-600 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-slate-200 whitespace-nowrap">
                        <Pencil size={14} />
                        RASCUNHO
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 group-hover:opacity-100 transition-opacity">
                      {ex.status === 'draft' && (
                        <button onClick={() => setSigningExchange(ex)} title="Enviar para assinatura" className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-xl transition-colors"><Mail size={16}/></button>
                      )}
                      {ex.status !== 'completed' ? (
                        <button onClick={() => onEdit(ex)} title="Editar registro" className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-xl transition-colors"><Pencil size={16}/></button>
                      ) : (
                        <div className="p-2.5 text-slate-300" title="Registro Finalizado"><Lock size={16}/></div>
                      )}
                      <button onClick={() => generateAssetPDF(ex, logoPref)} title="Gerar PDF" className="p-2.5 text-slate-600 hover:bg-slate-50 rounded-xl transition-colors"><FileDown size={16}/></button>
                      <button onClick={() => onDelete(ex.id)} title="Excluir" className="p-2.5 text-rose-600 hover:bg-rose-50 rounded-xl transition-colors"><Trash2 size={16}/></button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {signingExchange && (
        <SenderSignatureModal 
          exchange={signingExchange}
          onClose={() => setSigningExchange(null)}
          onConfirm={(id, sig) => { onSignSender(id, sig); setSigningExchange(null); }}
        />
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          height: 6px;
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #94a3b8;
        }
      `}</style>
    </div>
  );
};

export default InventoryTable;

import React, { useState } from 'react';
import { MockEmail, AssetExchange, LogoPreference } from '../types';
import { Mail, Trash2, Clock, Paperclip, PenLine, ShieldCheck, X, ChevronLeft } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';

interface MockInboxProps {
  emails: MockEmail[];
  exchanges: AssetExchange[];
  onUpdateEmails: (emails: MockEmail[]) => void;
  onSignReceiver: (id: string, signature: string) => void;
  logoPref: LogoPreference;
}

const MockInbox: React.FC<MockInboxProps> = ({ emails, onUpdateEmails, exchanges, onSignReceiver, logoPref }) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [signingExchangeId, setSigningExchangeId] = useState<string | null>(null);
  const [receiverSignature, setReceiverSignature] = useState('');

  const selectedEmail = emails.find(e => e.id === selectedId);
  const currentExchange = exchanges.find(ex => ex.id === selectedEmail?.exchangeId);

  const markAsRead = (id: string) => {
    const updated = emails.map(e => e.id === id ? { ...e, read: true } : e);
    onUpdateEmails(updated);
    setSelectedId(id);
  };

  const handleReceiverSign = (e: React.FormEvent) => {
    e.preventDefault();
    if (!receiverSignature.trim() || !signingExchangeId) return;

    onSignReceiver(signingExchangeId, receiverSignature);
    setSigningExchangeId(null);
    setReceiverSignature('');
  };

  if (emails.length === 0) {
    return (
      <div className="p-10 md:p-20 flex flex-col items-center justify-center text-center bg-white h-[500px] md:h-[600px]">
        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <Mail className="text-slate-300" size={32} />
        </div>
        <h3 className="text-lg md:text-xl font-bold text-slate-800">Sua caixa do Outlook está vazia</h3>
        <p className="text-slate-500 mt-2 max-w-xs text-sm">E-mails de termos enviados para assinatura aparecerão aqui.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col lg:flex-row h-[600px] lg:h-[700px] bg-white text-slate-900 overflow-hidden">
      {/* Sidebar List */}
      <div className={`w-full lg:w-1/3 border-r border-slate-100 flex flex-col h-full bg-white ${selectedId ? 'hidden lg:flex' : 'flex'}`}>
        <div className="p-4 bg-slate-50 border-b border-slate-100 flex items-center justify-between">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Inbox - Outlook ({emails.length})</span>
        </div>
        <div className="flex-1 overflow-y-auto">
          {emails.map(email => (
            <div
              key={email.id}
              onClick={() => markAsRead(email.id)}
              className={`p-4 cursor-pointer border-b border-slate-50 transition-colors relative group ${selectedId === email.id ? 'bg-blue-50/70 border-l-4 border-l-blue-600' : 'hover:bg-slate-50'}`}
            >
              {!email.read && <div className="absolute left-1 top-1/2 -translate-y-1/2 w-2 h-2 bg-blue-600 rounded-full shadow-sm"></div>}
              <div className="flex justify-between items-start mb-1">
                <span className={`text-xs truncate max-w-[150px] ${!email.read ? 'font-bold text-slate-900' : 'text-slate-600'}`}>{email.from.split('<')[0]}</span>
                <span className="text-[10px] text-slate-400 font-medium">{new Date(email.sentAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <h4 className={`text-xs truncate ${!email.read ? 'font-bold text-slate-800' : 'text-slate-500'}`}>{email.subject}</h4>
              <p className="text-[10px] text-slate-400 truncate mt-1">{email.body.substring(0, 50)}...</p>

              <button 
                onClick={(e) => { e.stopPropagation(); onUpdateEmails(emails.filter(em => em.id !== email.id)); if(selectedId === email.id) setSelectedId(null); }}
                className="absolute right-2 bottom-2 p-1.5 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all rounded-lg hover:bg-rose-50"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* Email Body */}
      <div className={`flex-1 flex flex-col bg-white h-full relative ${!selectedId ? 'hidden lg:flex' : 'flex'}`}>
        {selectedEmail ? (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            {/* Header / Mobile Back Button */}
            <div className="p-4 md:p-8 border-b border-slate-100 bg-slate-50 flex flex-col gap-4">
              <div className="flex items-center gap-2 lg:hidden">
                <button 
                  onClick={() => setSelectedId(null)}
                  className="flex items-center gap-1 text-blue-600 text-sm font-bold p-1 hover:bg-blue-50 rounded-lg transition-colors"
                >
                  <ChevronLeft size={20} /> Voltar
                </button>
              </div>

              <h2 className="text-xl md:text-2xl font-bold text-slate-800 leading-tight">{selectedEmail.subject}</h2>
              <div className="flex items-center gap-3 md:gap-4">
                <div className="w-10 h-10 md:w-12 md:h-12 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold text-base md:text-lg shadow-lg shrink-0">
                  {selectedEmail.from.charAt(0)}
                </div>
                <div className="flex-1 overflow-hidden">
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1">
                    <span className="font-bold text-slate-900 text-sm truncate">{selectedEmail.from}</span>
                    <div className="flex items-center gap-1 text-[10px] text-slate-400 font-medium">
                      <Clock size={12} />
                      {new Date(selectedEmail.sentAt).toLocaleString('pt-BR')}
                    </div>
                  </div>
                  <div className="text-xs text-slate-500 font-medium truncate">Para: Você ({selectedEmail.to})</div>
                </div>
              </div>
            </div>

            <div className="flex-1 p-4 md:p-8 overflow-y-auto">
              <div className="max-w-3xl mx-auto bg-white border border-slate-100 rounded-2xl shadow-sm p-4 md:p-8 whitespace-pre-wrap text-slate-700 leading-relaxed font-sans text-sm md:text-base">
                {selectedEmail.body}

                {selectedEmail.attachment && currentExchange && (
                  <div className="mt-8 md:mt-12 pt-6 md:pt-8 border-t border-slate-100">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Anexo Seguro (PDF):</p>
                    <div 
                      onClick={() => generateAssetPDF(currentExchange, logoPref)}
                      className="flex items-center gap-3 p-3 md:p-4 bg-slate-50 rounded-xl border border-slate-200 w-full sm:w-fit group cursor-pointer hover:border-blue-300 transition-colors"
                    >
                      <div className="bg-rose-100 text-rose-600 p-2 rounded-lg shrink-0">
                        <Paperclip size={20} />
                      </div>
                      <div className="overflow-hidden">
                        <p className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors truncate">Termo_Ativos.pdf</p>
                        <p className="text-[10px] text-slate-500">142 KB - PDF Gerado Digitalmente</p>
                      </div>
                    </div>
                  </div>
                )}

                {currentExchange && currentExchange.status === 'pending_receiver' && (
                  <div className="mt-10 flex flex-col items-center gap-4 border-t border-blue-50 pt-8">
                    <p className="text-xs md:text-sm text-slate-500 italic text-center px-4">A assinatura do TI já foi aplicada. Revise o documento para finalizar.</p>
                    <button 
                      onClick={() => setSigningExchangeId(currentExchange.id)}
                      className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white px-8 md:px-12 py-3.5 md:py-4 rounded-xl md:rounded-2xl font-bold shadow-xl shadow-blue-200 transition-all hover:scale-[1.02] active:scale-95 text-sm"
                    >
                      REVISAR E ASSINAR TERMO
                    </button>
                  </div>
                )}

                {currentExchange && currentExchange.status === 'completed' && (
                  <div className="mt-10 flex flex-col items-center gap-3 p-4 md:p-6 bg-emerald-50 rounded-2xl border border-emerald-100">
                    <ShieldCheck className="text-emerald-600 shrink-0" size={32} />
                    <p className="text-emerald-800 font-bold text-center text-sm md:text-base">Documento Finalizado e Assinado por Ambas as Partes</p>
                    <button 
                      onClick={() => generateAssetPDF(currentExchange, logoPref)}
                      className="text-[11px] font-bold text-emerald-600 underline hover:text-emerald-700 transition-colors"
                    >
                      Baixar Versão Final com todas as assinaturas
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400 p-10 text-center">
            <Mail size={48} className="mb-4 opacity-10" />
            <p className="font-medium text-slate-400 text-sm">Selecione uma mensagem para visualizar o conteúdo</p>
          </div>
        )}
      </div>

      {/* Modal de Assinatura do Colaborador */}
      {signingExchangeId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in fade-in">
          <div className="bg-white w-full max-w-md rounded-2xl md:rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
            <div className="p-4 md:p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm md:text-base">
                <PenLine className="text-blue-600 shrink-0" size={20} /> Assinatura do Colaborador
              </h3>
              <button onClick={() => setSigningExchangeId(null)} className="p-1 text-slate-400 hover:text-slate-600 rounded-lg hover:bg-slate-100 transition-colors"><X size={20} /></button>
            </div>
            <form onSubmit={handleReceiverSign} className="p-6 md:p-8 space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sua Assinatura Digital</label>
                <div className="relative group">
                   <input
                    required
                    autoFocus
                    type="text"
                    value={receiverSignature}
                    onChange={(e) => setReceiverSignature(e.target.value)}
                    placeholder="Seu nome"
                    className="w-full h-24 bg-white border-2 border-dashed border-slate-200 rounded-2xl text-center font-signature text-4xl md:text-5xl text-blue-800 focus:outline-none focus:border-blue-500 focus:bg-blue-50/30 transition-all placeholder:text-slate-200 placeholder:font-sans placeholder:text-sm"
                  />
                  <div className="absolute inset-0 pointer-events-none border-2 border-transparent group-focus-within:border-blue-500/10 rounded-2xl transition-all"></div>
                </div>
              </div>
              <p className="text-[11px] text-slate-500 leading-relaxed text-center">
                Ao clicar em confirmar, você declara estar de acordo com o termo de recebimento/devolução de equipamentos e uma cópia assinada será arquivada.
              </p>
              <button
                type="submit"
                className="w-full py-3.5 md:py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl md:rounded-2xl font-bold shadow-xl transition-all active:scale-95 text-sm"
              >
                Confirmar Assinatura e Devolver
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MockInbox;

import React, { useState, useEffect } from 'react';
import { PlusCircle, ClipboardList, LogOut, CheckCircle2, AlertCircle, Mail, Loader2, HardDrive, Menu, X, Image as ImageIcon, Sun, Moon } from 'lucide-react';
import { View, AssetExchange, MockEmail, LogoPreference } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';
import MockInbox from './components/MockInbox';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [emails, setEmails] = useState<MockEmail[]>([]);
  const [editingExchange, setEditingExchange] = useState<AssetExchange | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    return (saved === 'light' || saved === 'dark') ? saved : 'light';
  });
  const [logoPref, setLogoPref] = useState<LogoPreference>(() => {
    const saved = localStorage.getItem('logo_preference');
    return (saved === 'cirion' || saved === 'none') ? saved : 'cirion';
  });

  useEffect(() => {
    loadData();
    const savedEmails = localStorage.getItem('mock_emails');
    if (savedEmails) setEmails(JSON.parse(savedEmails));
  }, []);

  const loadData = async () => {
    const data = await apiService.getAll();
    setExchanges(data);
  };

  useEffect(() => {
    localStorage.setItem('mock_emails', JSON.stringify(emails));
  }, [emails]);

  useEffect(() => {
    localStorage.setItem('logo_preference', logoPref);
  }, [logoPref]);

  useEffect(() => {
    localStorage.setItem('theme', theme);
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  const handleSaveExchange = async (exchange: AssetExchange) => {
    setIsLoading(true);
    try {
      await apiService.save(exchange);
      await loadData();

      setEditingExchange(null);
      setCurrentView('inventory');
      showNotification("Registro gravado com sucesso.");
    } catch (error) {
      console.error("Erro ao gravar:", error);
      showNotification("Houve um erro ao salvar o registro.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkImport = async (data: AssetExchange[]) => {
    setIsLoading(true);
    try {
      for (const item of data) {
        await apiService.save(item);
      }
      await loadData();
      showNotification(`${data.length} registros importados/sincronizados.`);
    } catch (error) {
      showNotification("Falha na importação em massa.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignSender = async (id: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === id);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_ti: signature, 
      status: 'pending_receiver' 
    };

    await apiService.save(updated);
    await loadData();

    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: id,
      from: 'TI Infra - AssetFlow <infra@cirion.com>',
      to: exchange.colaborador_email,
      subject: `[AÇÃO NECESSÁRIA] Termo de Troca de Ativos - ${exchange.colaborador_nome}`,
      body: `Olá ${exchange.colaborador_nome},\n\nO seu novo equipamento foi registrado. Por favor, revise o termo de entrega e devolução em anexo, assine digitalmente e retorne para nós.\n\nAtenciosamente,\nEquipe de TI`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([newEmail, ...emails]);
    showNotification("Termo assinado e enviado para o Outlook.");
  };

  const handleSignReceiver = async (exchangeId: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === exchangeId);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_colaborador: signature, 
      status: 'completed' 
    };

    await apiService.save(updated);
    await loadData();

    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.colaborador_nome} <${exchange.colaborador_email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.colaborador_nome}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.colaborador_nome}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador.");
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Deseja realmente excluir este registro permanentemente?")) {
      await apiService.delete(id);
      await loadData();
      setEmails(prev => prev.filter(email => email.exchangeId !== id));
      showNotification("Registro removido.", "error");
    }
  };

  const navTo = (view: View) => {
    setEditingExchange(null);
    setCurrentView(view);
    setIsMobileMenuOpen(false);
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-sky-50 dark:bg-[#1e1e1e] text-slate-900 dark:text-[#cccccc] font-sans transition-colors duration-200">
      {/* Mobile Top Header */}
      <header className="lg:hidden bg-slate-900 dark:bg-[#252526] text-white p-4 flex items-center justify-between sticky top-0 z-[60] shadow-md">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
            <HardDrive className="text-white" size={16} />
          </div>
          <h1 className="text-lg font-bold tracking-tight">AssetFlow</h1>
        </div>
        <div className="flex items-center gap-2">
          <button 
            onClick={toggleTheme}
            className="p-2 hover:bg-slate-800 rounded-lg transition-colors text-slate-300"
          >
            {theme === 'light' ? <Moon size={20} /> : <Sun size={20} />}
          </button>
          <button 
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="p-2 hover:bg-slate-800 rounded-lg transition-colors"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </header>

      {/* Sidebar Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 dark:bg-[#252526] text-white flex-shrink-0 flex flex-col shadow-2xl z-50 transition-transform duration-300 transform lg:relative lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 hidden lg:flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <HardDrive className="text-white" size={20} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight text-white">AssetFlow</h1>
            <span className="text-[10px] text-indigo-400 font-bold tracking-widest uppercase">
              {logoPref === 'cirion' ? 'Cirion TI' : 'Admin'}
            </span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4 mt-16 lg:mt-0">
          <button
            disabled={isLoading}
            onClick={() => navTo('form')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'form' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 dark:text-[#858585] hover:bg-slate-800 dark:hover:bg-[#37373d] hover:text-white disabled:opacity-50'}`}
          >
            <PlusCircle size={20} />
            <span className="font-semibold text-sm">Nova Troca</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inventory')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'inventory' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 dark:text-[#858585] hover:bg-slate-800 dark:hover:bg-[#37373d] hover:text-white disabled:opacity-50'}`}
          >
            <ClipboardList size={20} />
            <span className="font-semibold text-sm">Inventário</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inbox')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 relative ${currentView === 'inbox' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 dark:text-[#858585] hover:bg-slate-800 dark:hover:bg-[#37373d] hover:text-white disabled:opacity-50'}`}
          >
            <Mail size={20} />
            <span className="font-semibold text-sm">Outlook Mock</span>
            {emails.some(e => !e.read) && (
              <span className="absolute right-4 top-1/2 -translate-y-1/2 w-2.5 h-2.5 bg-indigo-400 rounded-full border-2 border-slate-900 dark:border-[#252526]"></span>
            )}
          </button>
        </nav>

        {/* Configuration Footer Menu */}
        <div className="px-4 py-6 border-t border-slate-800 dark:border-[#333333] space-y-6">
          {/* Logo Selection */}
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-[10px] text-slate-500 dark:text-[#858585] uppercase font-bold tracking-widest ml-2">
              <ImageIcon size={12} /> Config. Logotipo
            </div>
            <div className="grid grid-cols-1 gap-1">
              <button 
                onClick={() => { setLogoPref('cirion'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
                className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'cirion' ? 'bg-slate-800 dark:bg-[#37373d] text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Cirion Technologies
              </button>
              <button 
                onClick={() => { setLogoPref('none'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
                className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'none' ? 'bg-slate-800 dark:bg-[#37373d] text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Sem Logotipo
              </button>
            </div>
          </div>

          {/* Theme Selection */}
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-[10px] text-slate-500 dark:text-[#858585] uppercase font-bold tracking-widest ml-2">
              {theme === 'light' ? <Moon size={12} /> : <Sun size={12} />} Tema Visual
            </div>
            <div className="flex p-1 bg-slate-800 dark:bg-[#1e1e1e] rounded-xl border border-slate-700 dark:border-[#333333]">
              <button 
                onClick={() => setTheme('light')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-[10px] font-bold transition-all ${theme === 'light' ? 'bg-slate-700 text-white' : 'text-slate-500 hover:text-slate-300'}`}
              >
                <Sun size={12} /> Claro
              </button>
              <button 
                onClick={() => setTheme('dark')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-[10px] font-bold transition-all ${theme === 'dark' ? 'bg-slate-700 dark:bg-[#37373d] text-white' : 'text-slate-500 hover:text-slate-300'}`}
              >
                <Moon size={12} /> Escuro
              </button>
            </div>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800 dark:border-[#333333]">
          <button className="w-full flex items-center gap-4 px-4 py-3 text-slate-500 dark:text-[#858585] hover:text-rose-400 transition-colors">
            <LogOut size={20} />
            <span className="font-semibold text-sm">Sair</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-x-hidden overflow-y-auto p-4 md:p-10 relative">
        {notification && (
          <div className={`fixed top-4 right-4 md:top-6 md:right-6 z-[200] flex items-center gap-3 px-4 md:px-6 py-3 md:py-4 rounded-xl md:rounded-2xl shadow-2xl border animate-in slide-in-from-top-6 duration-300 w-[calc(100%-2rem)] md:w-auto ${notification.type === 'success' ? 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 border-emerald-100 dark:border-emerald-800' : 'bg-rose-50 dark:bg-rose-900/30 text-rose-700 dark:text-rose-400 border-rose-100 dark:border-rose-800'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} className="shrink-0" /> : <AlertCircle size={20} className="shrink-0" />}
            <p className="font-bold text-sm leading-tight">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto space-y-6 md:space-y-8">
          <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">
                {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
                 currentView === 'inventory' ? 'Inventário de Ativos' : 'Caixa de Entrada'}
              </h2>
              <p className="text-slate-500 dark:text-[#858585] font-medium text-sm">Modo Offline Seguro: LocalStorage + Excel Sync</p>
            </div>
            {isLoading && (
              <div className="flex items-center gap-2 text-indigo-600 dark:text-indigo-400 font-bold bg-indigo-50 dark:bg-indigo-900/20 px-4 py-2 rounded-xl border border-indigo-100 dark:border-indigo-800 self-start md:self-end">
                <Loader2 className="animate-spin" size={18} />
                <span className="text-xs uppercase tracking-widest">Sincronizando...</span>
              </div>
            )}
          </header>

          <div className="bg-white dark:bg-[#1e1e1e] rounded-2xl md:rounded-[2.5rem] shadow-xl shadow-slate-200/60 dark:shadow-black/20 border border-slate-100 dark:border-[#333333] overflow-hidden min-h-[500px] lg:min-h-[600px] transition-colors duration-200">
            {currentView === 'form' && (
              <AssetForm 
                onSave={handleSaveExchange} 
                editingExchange={editingExchange} 
                onCancel={() => navTo('inventory')} 
                exchanges={exchanges}
              />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDelete} 
                onEdit={(ex) => { setEditingExchange(ex); setCurrentView('form'); }} 
                onNotify={showNotification}
                onSignSender={handleSignSender}
                onBulkImport={handleBulkImport}
                logoPref={logoPref}
              />
            )}
            {currentView === 'inbox' && (
              <MockInbox 
                emails={emails} 
                onUpdateEmails={setEmails} 
                exchanges={exchanges}
                onSignReceiver={handleSignReceiver}
                logoPref={logoPref}
              />
            )}
          </div>
        </div>

        <footer className="max-w-6xl mx-auto mt-8 md:mt-12 flex flex-col sm:flex-row justify-between items-center text-slate-400 dark:text-[#858585] text-[10px] font-bold uppercase tracking-wider px-4 gap-2 mb-8 md:mb-0">
          <p>© 2025 AssetFlow Technologies</p>
          <div className="flex gap-4">
            <span>Logo: {logoPref === 'cirion' ? 'Cirion' : 'Nenhum'}</span>
            <span>Tema: {theme === 'light' ? 'Claro' : 'Escuro (Visual Studio)'}</span>
            <span>Armazenamento Local</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS_LIST, PROCESSORS_LIST, MODEL_PROCESSOR_MAP, MEMORY_LIST, STORAGE_LIST } from '../constants';
import { User, Package, History, Send, ScanLine, Lock, MousePointer2, Loader2, CheckSquare } from 'lucide-react';
import BarcodeScannerModal from './BarcodeScannerModal';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => Promise<void> | void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = ["Mouse", "Mochila", "Teclado", "DockStation", "Headset", "Monitor"];

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel }) => {
  const isReadOnly = editingExchange?.status === 'completed';
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState<AssetExchange>({
    id: '',
    status: 'draft',
    timestamp: Date.now(),
    colaborador_nome: '',
    colaborador_email: '',
    data_troca: new Date().toISOString().split('T')[0],
    observacoes: '',
    entregue_tipo: EQUIPMENT_TYPES[0],
    entregue_marca: BRANDS[0],
    entregue_modelo: MODELS_LIST[0],
    entregue_serial: '',
    entregue_processador: PROCESSORS_LIST[0],
    entregue_condicao: EquipmentCondition.NEW,
    entregue_memoria: MEMORY_LIST[2], // Default 16GB
    entregue_armazenamento: STORAGE_LIST[3], // Default 512GB
    entregue_acessorios: [],
    devolvido_tipo: EQUIPMENT_TYPES[0],
    devolvido_marca: BRANDS[0],
    devolvido_modelo: MODELS_LIST[0],
    devolvido_serial: '',
    devolvido_processador: PROCESSORS_LIST[0],
    devolvido_condicao: EquipmentCondition.USED,
    devolvido_memoria: MEMORY_LIST[2], // Default 16GB
    devolvido_armazenamento: STORAGE_LIST[3], // Default 512GB
    devolvido_acessorios: []
  });

  const [scannerConfig, setScannerConfig] = useState<{ isOpen: boolean; target: 'entregue' | 'devolvido' }>({
    isOpen: false,
    target: 'entregue'
  });

  useEffect(() => {
    if (editingExchange) {
      setFormData({ ...editingExchange });
    }
  }, [editingExchange]);

  const handleBrandChange = (brand: string, target: 'entregue' | 'devolvido') => {
    if (target === 'entregue') {
      setFormData({ ...formData, entregue_marca: brand });
    } else {
      setFormData({ ...formData, devolvido_marca: brand });
    }
  };

  const handleModelChange = (model: string, target: 'entregue' | 'devolvido') => {
    const mappedProcessor = MODEL_PROCESSOR_MAP[model];

    if (target === 'entregue') {
      setFormData(prev => ({ 
        ...prev, 
        entregue_modelo: model,
        entregue_processador: mappedProcessor || prev.entregue_processador 
      }));
    } else {
      setFormData(prev => ({ 
        ...prev, 
        devolvido_modelo: model,
        devolvido_processador: mappedProcessor || prev.devolvido_processador 
      }));
    }
  };

  const handleAccessoryToggle = (acc: string, target: 'entregue' | 'devolvido') => {
    const field = target === 'entregue' ? 'entregue_acessorios' : 'devolvido_acessorios';
    const current = formData[field] as string[];
    const updated = current.includes(acc) ? current.filter(i => i !== acc) : [...current, acc];
    setFormData({ ...formData, [field]: updated });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload = {
        ...formData,
        id: formData.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        timestamp: formData.timestamp || Date.now()
      };
      await onSave(payload);
    } catch (err) {
      console.error("Erro ao salvar formulário:", err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-4 md:mb-6 pb-2 border-b border-slate-100 dark:border-[#333333]">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={18} className="text-white" />
      </div>
      <h3 className="text-base md:text-lg font-semibold text-slate-800 dark:text-white">{title}</h3>
    </div>
  );

  return (
    <>
      <form onSubmit={handleSubmit} className="p-4 md:p-8 space-y-8 md:space-y-12 transition-colors duration-200">
        {isReadOnly && (
          <div className="bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 p-4 rounded-xl md:rounded-2xl flex items-center gap-4">
            <Lock size={20} className="text-amber-700 dark:text-amber-400 shrink-0" />
            <p className="text-amber-900 dark:text-amber-300 text-sm font-bold">Registro Bloqueado por Assinatura</p>
          </div>
        )}

        <section>
          <SectionHeader icon={User} title="Dados do Colaborador" color="bg-indigo-600" />
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 dark:text-[#858585] uppercase">Nome Completo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required
                placeholder="Ex: João Silva"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900/30 transition-all text-sm outline-none"
                value={formData.colaborador_nome}
                onChange={e => setFormData({ ...formData, colaborador_nome: e.target.value })}
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 dark:text-[#858585] uppercase">E-mail Corporativo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="email"
                placeholder="joao.silva@cirion.com"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900/30 transition-all text-sm outline-none"
                value={formData.colaborador_email}
                onChange={e => setFormData({ ...formData, colaborador_email: e.target.value })}
              />
            </div>
            <div className="space-y-1.5 sm:col-span-2 md:col-span-1">
              <label className="text-xs font-bold text-slate-500 dark:text-[#858585] uppercase">Data da Troca</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="date"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900/30 transition-all text-sm outline-none"
                value={formData.data_troca}
                onChange={e => setFormData({ ...formData, data_troca: e.target.value })}
              />
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
          {/* Entregue */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 dark:bg-[#252526] border border-slate-100 dark:border-[#333333]">
            <SectionHeader icon={Package} title="Equipamento Entregue" color="bg-emerald-600" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.entregue_tipo} onChange={e => setFormData({...formData, entregue_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.entregue_marca} onChange={e => handleBrandChange(e.target.value, 'entregue')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Modelo</label>
                <select 
                  disabled={isReadOnly || isSubmitting} 
                  className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" 
                  value={formData.entregue_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'entregue')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white font-mono text-sm pr-10 outline-none" value={formData.entregue_serial} onChange={e => setFormData({...formData, entregue_serial: e.target.value})} />
                  {!isReadOnly && !isSubmitting && <button type="button" onClick={() => setScannerConfig({isOpen: true, target: 'entregue'})} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 dark:text-[#858585] hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors p-1"><ScanLine size={18}/></button>}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Estado</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.entregue_condicao} onChange={e => setFormData({...formData, entregue_condicao: e.target.value as EquipmentCondition})}>
