              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Memória RAM</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.entregue_memoria} onChange={e => setFormData({...formData, entregue_memoria: e.target.value})}>
