                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-[10px]" value={formData.entregue_processador} onChange={e => setFormData({...formData, entregue_processador: e.target.value})}>
                  {PROCESSORS_LIST.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
