                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.entregue_armazenamento} onChange={e => setFormData({...formData, entregue_armazenamento: e.target.value})}>
                  {STORAGE_LIST.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="mt-6">
              <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] block mb-3 uppercase tracking-wider">Acessórios Entregues</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label 
                    key={acc} 
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border cursor-pointer transition-all text-xs font-medium ${formData.entregue_acessorios.includes(acc) ? 'bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 dark:border-emerald-800 text-emerald-700 dark:text-emerald-400 ring-2 ring-emerald-100 dark:ring-emerald-900/30' : 'bg-white dark:bg-[#3c3c3c] border-slate-200 dark:border-[#333333] text-slate-500 dark:text-[#858585] hover:border-emerald-200'}`}
                  >
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={formData.entregue_acessorios.includes(acc)} 
                      onChange={() => handleAccessoryToggle(acc, 'entregue')} 
                      disabled={isReadOnly || isSubmitting} 
                    />
                    <CheckSquare size={14} className={`shrink-0 ${formData.entregue_acessorios.includes(acc) ? 'opacity-100' : 'opacity-20'}`} />
                    <span className="truncate">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>

          {/* Devolvido */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 dark:bg-[#252526] border border-slate-100 dark:border-[#333333]">
            <SectionHeader icon={History} title="Equipamento Devolvido" color="bg-rose-600" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.devolvido_tipo} onChange={e => setFormData({...formData, devolvido_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.devolvido_marca} onChange={e => handleBrandChange(e.target.value, 'devolvido')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Modelo</label>
                <select 
                  disabled={isReadOnly || isSubmitting} 
                  className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" 
                  value={formData.devolvido_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'devolvido')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white font-mono text-sm pr-10 outline-none" value={formData.devolvido_serial} onChange={e => setFormData({...formData, devolvido_serial: e.target.value})} />
                  {!isReadOnly && !isSubmitting && <button type="button" onClick={() => setScannerConfig({isOpen: true, target: 'devolvido'})} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 dark:text-[#858585] hover:text-rose-600 dark:hover:text-rose-400 transition-colors p-1"><ScanLine size={18}/></button>}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Estado</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.devolvido_condicao} onChange={e => setFormData({...formData, devolvido_condicao: e.target.value as EquipmentCondition})}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Memória RAM</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.devolvido_memoria} onChange={e => setFormData({...formData, devolvido_memoria: e.target.value})}>
                  {MEMORY_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Processador</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-[10px]" value={formData.devolvido_processador} onChange={e => setFormData({...formData, devolvido_processador: e.target.value})}>
                  {PROCESSORS_LIST.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] uppercase">Armazenamento</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white text-sm" value={formData.devolvido_armazenamento} onChange={e => setFormData({...formData, devolvido_armazenamento: e.target.value})}>
                  {STORAGE_LIST.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="mt-6">
              <label className="text-[10px] font-bold text-slate-500 dark:text-[#858585] block mb-3 uppercase tracking-wider">Acessórios Devolvidos</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label 
                    key={acc} 
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border cursor-pointer transition-all text-xs font-medium ${formData.devolvido_acessorios.includes(acc) ? 'bg-rose-50 dark:bg-rose-900/20 border-rose-200 dark:border-rose-800 text-rose-700 dark:text-rose-400 ring-2 ring-rose-100 dark:ring-rose-900/30' : 'bg-white dark:bg-[#3c3c3c] border-slate-200 dark:border-[#333333] text-slate-500 dark:text-[#858585] hover:border-rose-200'}`}
                  >
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={formData.devolvido_acessorios.includes(acc)} 
                      onChange={() => handleAccessoryToggle(acc, 'devolvido')} 
                      disabled={isReadOnly || isSubmitting} 
                    />
                    <CheckSquare size={14} className={`shrink-0 ${formData.devolvido_acessorios.includes(acc) ? 'opacity-100' : 'opacity-20'}`} />
                    <span className="truncate">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>
        </div>

        <section>
          <SectionHeader icon={MousePointer2} title="Observações Internas" color="bg-slate-700" />
          <textarea 
            disabled={isReadOnly || isSubmitting}
            placeholder="Ex: Teclado do notebook entregue está com a tecla 'A' frouxa."
            className="w-full p-4 rounded-xl md:rounded-2xl border bg-white dark:bg-[#3c3c3c] dark:border-[#333333] dark:text-white h-24 focus:ring-2 focus:ring-slate-100 dark:focus:ring-slate-900/30 transition-all resize-none text-sm outline-none" 
            value={formData.observacoes}
            onChange={e => setFormData({ ...formData, observacoes: e.target.value })}
          />
        </section>

        <div className="flex flex-col-reverse sm:flex-row justify-end items-stretch sm:items-center gap-3 sm:gap-4">
          <button 
            type="button" 
            onClick={onCancel} 
            disabled={isSubmitting}
            className="px-8 py-3.5 rounded-xl md:rounded-2xl font-bold text-slate-500 dark:text-[#858585] hover:bg-slate-100 dark:hover:bg-[#37373d] transition-colors disabled:opacity-30 text-sm"
          >
            Cancelar
          </button>
          {!isReadOnly && (
            <button 
              type="submit" 
              disabled={isSubmitting}
              className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-8 md:px-10 py-3.5 rounded-xl md:rounded-2xl font-bold shadow-xl shadow-indigo-600/20 transition-all active:scale-95 disabled:bg-indigo-400 text-sm"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="animate-spin" size={18} />
                  <span>Gravando...</span>
                </>
              ) : (
                <>
                  <Send size={18} />
                  <span>{editingExchange ? 'Salvar Registro' : 'Gravar Registro'}</span>
                </>
              )}
            </button>
          )}
        </div>
      </form>

      {scannerConfig.isOpen && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'entregue' ? 'Lendo Serial Entregue' : 'Lendo Serial Devolvido'}
          onScan={(text) => {
            const processed = text.trim();
            if (scannerConfig.target === 'entregue') setFormData({...formData, entregue_serial: processed});
            else setFormData({...formData, devolvido_serial: processed});
            setScannerConfig({...scannerConfig, isOpen: false});
          }}
          onClose={() => setScannerConfig({...scannerConfig, isOpen: false})}
        />
      )}
    </>
  );
};

export default AssetForm;

import React, { useState, useRef } from 'react';
import { AssetExchange, LogoPreference } from '../types';
import { FileDown, Trash2, Search, FileSpreadsheet, Pencil, Mail, Laptop, Smartphone, Cpu, Clock, Lock, FileCheck, Upload } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';
import { exportToExcel, importFromExcel } from '../services/excelService';
import SenderSignatureModal from './SenderSignatureModal';

interface InventoryTableProps {
  exchanges: AssetExchange[];
  onDelete: (id: string) => void;
  onEdit: (exchange: AssetExchange) => void;
  onNotify: (message: string, type: 'success' | 'error') => void;
  onSignSender: (id: string, signature: string) => void;
  onBulkImport: (data: AssetExchange[]) => void;
  logoPref: LogoPreference;
}

const InventoryTable: React.FC<InventoryTableProps> = ({ exchanges, onDelete, onEdit, onNotify, onSignSender, onBulkImport, logoPref }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [signingExchange, setSigningExchange] = useState<AssetExchange | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filtered = exchanges.filter(e => 
    e.colaborador_nome.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.entregue_serial.toLowerCase().includes(searchTerm.toLowerCase()) ||
    e.devolvido_serial.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const data = await importFromExcel(file);
      if (confirm(`Deseja importar ${data.length} registros? Isso poderá sobrescrever dados existentes com o mesmo ID.`)) {
        onBulkImport(data);
        onNotify("Base de dados sincronizada com sucesso!", "success");
      }
    } catch (err) {
      onNotify("Erro ao ler arquivo Excel. Verifique o formato.", "error");
    }
    e.target.value = ''; // Reset input
  };

  const getIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('note')) return <Laptop size={14} />;
    if (t.includes('smart')) return <Smartphone size={14} />;
    return <Cpu size={14} />;
  };

  return (
    <div className="flex flex-col h-full overflow-hidden transition-colors duration-200">
      <div className="p-4 md:p-6 border-b dark:border-[#333333] flex flex-col xl:flex-row xl:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-full xl:max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-[#858585]" size={18} />
          <input 
            placeholder="Buscar por nome ou serial..."
            className="w-full pl-10 pr-4 py-2.5 rounded-xl border dark:border-[#333333] bg-slate-50 dark:bg-[#3c3c3c] dark:text-white focus:bg-white dark:focus:bg-[#1e1e1e] transition-all text-sm outline-none focus:ring-2 focus:ring-indigo-100 dark:focus:ring-indigo-900/30"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept=".xlsx, .xls" 
            className="hidden" 
          />
          <button 
            onClick={handleImportClick}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-slate-100 dark:bg-[#37373d] text-slate-600 dark:text-[#cccccc] px-4 py-2.5 rounded-xl font-bold border border-slate-200 dark:border-[#333333] transition-all hover:bg-slate-200 dark:hover:bg-[#3e3e42] active:scale-95 text-xs"
          >
            <Upload size={16} /> Importar Base
          </button>
          <button 
            onClick={() => exportToExcel(exchanges)} 
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-emerald-600 text-white px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-emerald-100 dark:shadow-black/20 transition-all hover:bg-emerald-700 active:scale-95 text-xs"
          >
            <FileSpreadsheet size={16} /> Exportar Excel
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-x-auto custom-scrollbar">
        <table className="w-full text-left min-w-[900px]">
          <thead className="bg-slate-50 dark:bg-[#252526] sticky top-0 z-10 border-b dark:border-[#333333]">
            <tr>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 dark:text-[#858585] tracking-wider">Colaborador</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 dark:text-[#858585] tracking-wider">Equip. Entregue</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 dark:text-[#858585] tracking-wider">Equip. Devolvido</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 dark:text-[#858585] text-center tracking-wider">Status</th>
              <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 dark:text-[#858585] text-right tracking-wider">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y dark:divide-[#333333]">
            {filtered.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-20 text-center text-slate-400 dark:text-[#858585] italic bg-white dark:bg-[#1e1e1e]">
                  <div className="flex flex-col items-center gap-2">
                    <Search size={32} className="opacity-10 dark:opacity-5" />
                    <p>Nenhum registro encontrado.</p>
                  </div>
                </td>
              </tr>
            ) : (
              filtered.map(ex => (
                <tr key={ex.id} className="hover:bg-slate-50/80 dark:hover:bg-[#2a2d2e] group transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="font-bold text-slate-900 dark:text-white text-sm">{ex.colaborador_nome}</span>
                      <span className="text-[10px] text-slate-400 dark:text-[#858585] font-medium">{ex.colaborador_email}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 uppercase flex items-center gap-1 mb-0.5">
                        {getIcon(ex.entregue_tipo)} {ex.entregue_tipo}
                      </span>
                      <span className="text-xs font-semibold text-slate-700 dark:text-[#cccccc]">{ex.entregue_marca} {ex.entregue_modelo}</span>
                      <span className="text-[10px] font-mono text-slate-400 dark:text-[#858585] mt-0.5">S/N: {ex.entregue_serial}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col">
                      <span className="text-[10px] font-bold text-rose-600 dark:text-rose-400 uppercase flex items-center gap-1 mb-0.5">
                        {getIcon(ex.devolvido_tipo)} {ex.devolvido_tipo}
                      </span>
                      <span className="text-xs font-semibold text-slate-700 dark:text-[#cccccc]">{ex.devolvido_marca} {ex.devolvido_modelo}</span>
                      <span className="text-[10px] font-mono text-slate-400 dark:text-[#858585] mt-0.5">S/N: {ex.devolvido_serial}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    {ex.status === 'completed' ? (
                      <button 
                        onClick={() => generateAssetPDF(ex, logoPref)}
                        className="inline-flex items-center gap-2 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-700 dark:text-emerald-400 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-emerald-100 dark:border-emerald-800 shadow-sm hover:bg-emerald-100 dark:hover:bg-emerald-800/40 transition-all active:scale-95 whitespace-nowrap"
                      >
                        <FileCheck size={14} />
                        TERMO ASSINADO
                      </button>
                    ) : ex.status === 'pending_receiver' ? (
                      <span className="inline-flex items-center gap-2 bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-400 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-blue-100 dark:border-blue-800 whitespace-nowrap">
                        <Clock size={14} />
                        AGUARDANDO ASSINATURA
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-2 bg-slate-100 dark:bg-[#3c3c3c] text-slate-600 dark:text-[#858585] px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-wider border border-slate-200 dark:border-[#333333] whitespace-nowrap">
                        <Pencil size={14} />
                        RASCUNHO
                      </span>
                    )}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      {ex.status === 'draft' && (
                        <button onClick={() => setSigningExchange(ex)} title="Enviar para assinatura" className="p-2.5 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl transition-colors"><Mail size={16}/></button>
                      )}
                      {ex.status !== 'completed' ? (
                        <button onClick={() => onEdit(ex)} title="Editar registro" className="p-2.5 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-xl transition-colors"><Pencil size={16}/></button>
                      ) : (
                        <div className="p-2.5 text-slate-300 dark:text-[#333333]" title="Registro Finalizado"><Lock size={16}/></div>
                      )}
                      <button onClick={() => generateAssetPDF(ex, logoPref)} title="Gerar PDF" className="p-2.5 text-slate-600 dark:text-[#cccccc] hover:bg-slate-50 dark:hover:bg-[#3e3e42] rounded-xl transition-colors"><FileDown size={16}/></button>
                      <button onClick={() => onDelete(ex.id)} title="Excluir" className="p-2.5 text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl transition-colors"><Trash2 size={16}/></button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {signingExchange && (
        <SenderSignatureModal 
          exchange={signingExchange}
          onClose={() => setSigningExchange(null)}
          onConfirm={(id, sig) => { onSignSender(id, sig); setSigningExchange(null); }}
        />
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          height: 6px;
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .dark .custom-scrollbar::-webkit-scrollbar-track {
          background: #1e1e1e;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb {
