export default SenderSignatureModal;

import React, { useState, useEffect } from 'react';
import { PlusCircle, ClipboardList, LogOut, CheckCircle2, AlertCircle, Mail, Loader2, HardDrive, Menu, X, Image as ImageIcon, Sun, Moon } from 'lucide-react';
import { View, AssetExchange, MockEmail, LogoPreference } from './types';
import AssetForm from './components/AssetForm';
import InventoryTable from './components/InventoryTable';
import MockInbox from './components/MockInbox';
import { apiService } from './services/apiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('form');
  const [exchanges, setExchanges] = useState<AssetExchange[]>([]);
  const [emails, setEmails] = useState<MockEmail[]>([]);
  const [editingExchange, setEditingExchange] = useState<AssetExchange | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    return (saved === 'light' || saved === 'dark') ? saved : 'light';
  });

  const [logoPref, setLogoPref] = useState<LogoPreference>(() => {
    const saved = localStorage.getItem('logo_preference');
    return (saved === 'cirion' || saved === 'none') ? saved : 'cirion';
  });

  useEffect(() => {
    loadData();
    const savedEmails = localStorage.getItem('mock_emails');
    if (savedEmails) setEmails(JSON.parse(savedEmails));
  }, []);

  const loadData = async () => {
    const data = await apiService.getAll();
    setExchanges(data);
  };

  useEffect(() => {
    localStorage.setItem('mock_emails', JSON.stringify(emails));
  }, [emails]);

  useEffect(() => {
    localStorage.setItem('logo_preference', logoPref);
  }, [logoPref]);

  useEffect(() => {
    localStorage.setItem('theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 5000);
  };

  const handleSaveExchange = async (exchange: AssetExchange) => {
    setIsLoading(true);
    try {
      await apiService.save(exchange);
      await loadData();

      setEditingExchange(null);
      setCurrentView('inventory');
      showNotification("Registro gravado com sucesso.");
    } catch (error) {
      console.error("Erro ao gravar:", error);
      showNotification("Houve um erro ao salvar o registro.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkImport = async (data: AssetExchange[]) => {
    setIsLoading(true);
    try {
      for (const item of data) {
        await apiService.save(item);
      }
      await loadData();
      showNotification(`${data.length} registros importados/sincronizados.`);
    } catch (error) {
      showNotification("Falha na importação em massa.", "error");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSignSender = async (id: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === id);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_ti: signature, 
      status: 'pending_receiver' 
    };

    await apiService.save(updated);
    await loadData();

    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: id,
      from: 'TI Infra - AssetFlow <infra@cirion.com>',
      to: exchange.colaborador_email,
      subject: `[AÇÃO NECESSÁRIA] Termo de Troca de Ativos - ${exchange.colaborador_nome}`,
      body: `Olá ${exchange.colaborador_nome},\n\nO seu novo equipamento foi registrado. Por favor, revise o termo de entrega e devolução em anexo, assine digitalmente e retorne para nós.\n\nAtenciosamente,\nEquipe de TI`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([newEmail, ...emails]);
    showNotification("Termo assinado e enviado para o Outlook.");
  };

  const handleSignReceiver = async (exchangeId: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === exchangeId);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_colaborador: signature, 
      status: 'completed' 
    };

    await apiService.save(updated);
    await loadData();

    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.colaborador_nome} <${exchange.colaborador_email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.colaborador_nome}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.colaborador_nome}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador.");
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Deseja realmente excluir este registro permanentemente?")) {
      await apiService.delete(id);
      await loadData();
      setEmails(prev => prev.filter(email => email.exchangeId !== id));
      showNotification("Registro removido.", "error");
    }
  };

  const navTo = (view: View) => {
    setEditingExchange(null);
    setCurrentView(view);
    setIsMobileMenuOpen(false);
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-sky-50 dark:bg-[#1e1e1e] text-slate-900 dark:text-[#cccccc] font-sans transition-colors duration-200">
      {/* Mobile Top Header */}
      <header className="lg:hidden bg-slate-900 dark:bg-[#252526] text-white p-4 flex items-center justify-between sticky top-0 z-[60] shadow-md">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
            <HardDrive className="text-white" size={16} />
          </div>
          <h1 className="text-lg font-bold tracking-tight">AssetFlow</h1>
        </div>
        <div className="flex items-center gap-2">
          <button 
            onClick={toggleTheme}
            className="p-2 hover:bg-slate-800 rounded-lg transition-colors text-slate-300"
          >
            {theme === 'light' ? <Moon size={20} /> : <Sun size={20} />}
          </button>
          <button 
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="p-2 hover:bg-slate-800 rounded-lg transition-colors"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </header>

      {/* Sidebar Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 dark:bg-[#252526] text-white flex-shrink-0 flex flex-col shadow-2xl z-50 transition-transform duration-300 transform lg:relative lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 hidden lg:flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <HardDrive className="text-white" size={20} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight text-white">AssetFlow</h1>
            <span className="text-[10px] text-indigo-400 font-bold tracking-widest uppercase">
              {logoPref === 'cirion' ? 'Cirion TI' : 'Admin'}
            </span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4 mt-16 lg:mt-0">
          <button
            disabled={isLoading}
            onClick={() => navTo('form')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'form' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 dark:text-[#858585] hover:bg-slate-800 dark:hover:bg-[#37373d] hover:text-white disabled:opacity-50'}`}
          >
            <PlusCircle size={20} />
            <span className="font-semibold text-sm">Nova Troca</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inventory')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'inventory' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 dark:text-[#858585] hover:bg-slate-800 dark:hover:bg-[#37373d] hover:text-white disabled:opacity-50'}`}
          >
            <ClipboardList size={20} />
            <span className="font-semibold text-sm">Inventário</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inbox')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 relative ${currentView === 'inbox' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-400 dark:text-[#858585] hover:bg-slate-800 dark:hover:bg-[#37373d] hover:text-white disabled:opacity-50'}`}
          >
            <Mail size={20} />
            <span className="font-semibold text-sm">Outlook Mock</span>
            {emails.some(e => !e.read) && (
              <span className="absolute right-4 top-1/2 -translate-y-1/2 w-2.5 h-2.5 bg-indigo-400 rounded-full border-2 border-slate-900 dark:border-[#252526]"></span>
            )}
          </button>
        </nav>

        {/* Configuration Footer Menu */}
        <div className="px-4 py-6 border-t border-slate-800 dark:border-[#333333] space-y-6">
          {/* Logo Selection */}
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-[10px] text-slate-500 dark:text-[#858585] uppercase font-bold tracking-widest ml-2">
              <ImageIcon size={12} /> Config. Logotipo
            </div>
            <div className="grid grid-cols-1 gap-1">
              <button 
                onClick={() => { setLogoPref('cirion'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
                className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'cirion' ? 'bg-slate-800 dark:bg-[#37373d] text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Cirion Technologies
              </button>
              <button 
                onClick={() => { setLogoPref('none'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
                className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'none' ? 'bg-slate-800 dark:bg-[#37373d] text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Sem Logotipo
              </button>
            </div>
          </div>

          {/* Theme Selection */}
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-[10px] text-slate-500 dark:text-[#858585] uppercase font-bold tracking-widest ml-2">
              {theme === 'light' ? <Moon size={12} /> : <Sun size={12} />} Tema Visual
            </div>
            <div className="flex p-1 bg-slate-800 dark:bg-[#1e1e1e] rounded-xl border border-slate-700 dark:border-[#333333]">
              <button 
                onClick={() => setTheme('light')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-[10px] font-bold transition-all ${theme === 'light' ? 'bg-slate-700 text-white' : 'text-slate-500 hover:text-slate-300'}`}
              >
                <Sun size={12} /> Claro
              </button>
              <button 
                onClick={() => setTheme('dark')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-[10px] font-bold transition-all ${theme === 'dark' ? 'bg-slate-700 dark:bg-[#37373d] text-white' : 'text-slate-500 hover:text-slate-300'}`}
              >
                <Moon size={12} /> Escuro
              </button>
            </div>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800 dark:border-[#333333]">
          <button className="w-full flex items-center gap-4 px-4 py-3 text-slate-500 dark:text-[#858585] hover:text-rose-400 transition-colors">
            <LogOut size={20} />
            <span className="font-semibold text-sm">Sair</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-x-hidden overflow-y-auto p-4 md:p-10 relative">
        {notification && (
          <div className={`fixed top-4 right-4 md:top-6 md:right-6 z-[200] flex items-center gap-3 px-4 md:px-6 py-3 md:py-4 rounded-xl md:rounded-2xl shadow-2xl border animate-in slide-in-from-top-6 duration-300 w-[calc(100%-2rem)] md:w-auto ${notification.type === 'success' ? 'bg-emerald-50 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 border-emerald-100 dark:border-emerald-800' : 'bg-rose-50 dark:bg-rose-900/30 text-rose-700 dark:text-rose-400 border-rose-100 dark:border-rose-800'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} className="shrink-0" /> : <AlertCircle size={20} className="shrink-0" />}
            <p className="font-bold text-sm leading-tight">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto space-y-6 md:space-y-8">
          <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">
                {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
                 currentView === 'inventory' ? 'Inventário de Ativos' : 'Caixa de Entrada'}
              </h2>
              <p className="text-slate-500 dark:text-[#858585] font-medium text-sm">Modo Offline Seguro: LocalStorage + Excel Sync</p>
            </div>
            {isLoading && (
              <div className="flex items-center gap-2 text-indigo-600 dark:text-indigo-400 font-bold bg-indigo-50 dark:bg-indigo-900/20 px-4 py-2 rounded-xl border border-indigo-100 dark:border-indigo-800 self-start md:self-end">
                <Loader2 className="animate-spin" size={18} />
                <span className="text-xs uppercase tracking-widest">Sincronizando...</span>
              </div>
            )}
          </header>

          <div className="bg-white dark:bg-[#1e1e1e] rounded-2xl md:rounded-[2.5rem] shadow-xl shadow-slate-200/60 dark:shadow-black/20 border border-slate-100 dark:border-[#333333] overflow-hidden min-h-[500px] lg:min-h-[600px] transition-colors duration-200">
            {currentView === 'form' && (
              <AssetForm 
                onSave={handleSaveExchange} 
                editingExchange={editingExchange} 
                onCancel={() => navTo('inventory')} 
                exchanges={exchanges}
              />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDelete} 
                onEdit={(ex) => { setEditingExchange(ex); setCurrentView('form'); }} 
                onNotify={showNotification}
                onSignSender={handleSignSender}
                onBulkImport={handleBulkImport}
                logoPref={logoPref}
              />
            )}
            {currentView === 'inbox' && (
              <MockInbox 
                emails={emails} 
                onUpdateEmails={setEmails} 
                exchanges={exchanges}
                onSignReceiver={handleSignReceiver}
                logoPref={logoPref}
              />
            )}
          </div>
        </div>

        <footer className="max-w-6xl mx-auto mt-8 md:mt-12 flex flex-col sm:flex-row justify-between items-center text-slate-400 dark:text-[#858585] text-[10px] font-bold uppercase tracking-wider px-4 gap-2 mb-8 md:mb-0">
          <p>© 2025 AssetFlow Technologies</p>
          <div className="flex gap-4">
            <span>Logo: {logoPref === 'cirion' ? 'Cirion' : 'Nenhum'}</span>
            <span>Tema: {theme === 'light' ? 'Claro' : 'Escuro (Visual Studio)'}</span>
            <span>Armazenamento Local</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

