    }
  };

  const handleSignSender = async (id: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === id);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_ti: signature, 
      status: 'pending_receiver' 
    };

    await apiService.save(updated);
    await loadData();

    const newEmail: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: id,
      from: 'TI Infra - AssetFlow <infra@cirion.com>',
      to: exchange.colaborador_email,
      subject: `[AÇÃO NECESSÁRIA] Termo de Troca de Ativos - ${exchange.colaborador_nome}`,
      body: `Olá ${exchange.colaborador_nome},\n\nO seu novo equipamento foi registrado. Por favor, revise o termo de entrega e devolução em anexo, assine digitalmente e retorne para nós.\n\nAtenciosamente,\nEquipe de TI`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([newEmail, ...emails]);
    showNotification("Termo assinado e enviado para o Outlook.");
  };

  const handleSignReceiver = async (exchangeId: string, signature: string) => {
    const exchange = exchanges.find(e => e.id === exchangeId);
    if (!exchange) return;

    const updated: AssetExchange = { 
      ...exchange, 
      assinatura_colaborador: signature, 
      status: 'completed' 
    };

    await apiService.save(updated);
    await loadData();

    const reply: MockEmail = {
      id: Math.random().toString(36).substr(2, 9),
      exchangeId: exchangeId,
      from: `${exchange.colaborador_nome} <${exchange.colaborador_email}>`,
      to: 'TI Infra <infra@cirion.com>',
      subject: `RES: Termo de Troca Assinado - ${exchange.colaborador_nome}`,
      body: `Prezada equipe de TI,\n\nSegue em anexo o termo devidamente assinado conforme solicitado.\n\nAtenciosamente,\n${exchange.colaborador_nome}`,
      sentAt: new Date().toISOString(),
      read: false,
      attachment: true
    };
    setEmails([reply, ...emails]);
    showNotification("Termo assinado pelo colaborador.");
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Deseja realmente excluir este registro permanentemente?")) {
      await apiService.delete(id);
      await loadData();
      setEmails(prev => prev.filter(email => email.exchangeId !== id));
      showNotification("Registro removido.", "error");
    }
  };

  const navTo = (view: View) => {
    setEditingExchange(null);
    setCurrentView(view);
    setIsMobileMenuOpen(false);
  };

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  return (
    <div className="flex flex-col lg:flex-row min-h-screen bg-sky-50 dark:bg-dracula-bg text-slate-900 dark:text-dracula-fg font-sans transition-colors duration-200">
      {/* Mobile Top Header */}
      <header className="lg:hidden bg-slate-900 dark:bg-dracula-darker text-white p-4 flex items-center justify-between sticky top-0 z-[60] shadow-md">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-dracula-purple rounded-lg flex items-center justify-center">
            <HardDrive className="text-white" size={16} />
          </div>
          <h1 className="text-lg font-bold tracking-tight">AssetFlow</h1>
        </div>
        <div className="flex items-center gap-2">
          <button 
            onClick={toggleTheme}
            className="p-2 hover:bg-slate-800 dark:hover:bg-dracula-current rounded-lg transition-colors text-slate-300"
          >
            {theme === 'light' ? <Moon size={20} /> : <Sun size={20} />}
          </button>
          <button 
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="p-2 hover:bg-slate-800 dark:hover:bg-dracula-current rounded-lg transition-colors"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </header>

      {/* Sidebar Overlay for Mobile */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 dark:bg-dracula-darker/80 backdrop-blur-sm z-50 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`fixed inset-y-0 left-0 w-72 bg-slate-900 dark:bg-dracula-darker text-white flex-shrink-0 flex flex-col shadow-2xl z-50 transition-transform duration-300 transform lg:relative lg:translate-x-0 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 hidden lg:flex items-center gap-3">
          <div className="w-10 h-10 bg-dracula-purple rounded-xl flex items-center justify-center shadow-lg shadow-dracula-purple/20">
            <HardDrive className="text-white" size={20} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight text-white">AssetFlow</h1>
            <span className="text-[10px] text-dracula-cyan font-bold tracking-widest uppercase">
              {logoPref === 'cirion' ? 'Cirion TI' : 'Admin'}
            </span>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 py-4 mt-16 lg:mt-0">
          <button
            disabled={isLoading}
            onClick={() => navTo('form')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'form' ? 'bg-dracula-purple text-white shadow-lg shadow-dracula-purple/20' : 'text-slate-400 dark:text-dracula-comment hover:bg-slate-800 dark:hover:bg-dracula-current hover:text-white disabled:opacity-50'}`}
          >
            <PlusCircle size={20} />
            <span className="font-semibold text-sm">Nova Troca</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inventory')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 ${currentView === 'inventory' ? 'bg-dracula-purple text-white shadow-lg shadow-dracula-purple/20' : 'text-slate-400 dark:text-dracula-comment hover:bg-slate-800 dark:hover:bg-dracula-current hover:text-white disabled:opacity-50'}`}
          >
            <ClipboardList size={20} />
            <span className="font-semibold text-sm">Inventário</span>
          </button>

          <button
            disabled={isLoading}
            onClick={() => navTo('inbox')}
            className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all duration-200 relative ${currentView === 'inbox' ? 'bg-dracula-purple text-white shadow-lg shadow-dracula-purple/20' : 'text-slate-400 dark:text-dracula-comment hover:bg-slate-800 dark:hover:bg-dracula-current hover:text-white disabled:opacity-50'}`}
          >
            <Mail size={20} />
            <span className="font-semibold text-sm">Outlook Mock</span>
            {emails.some(e => !e.read) && (
              <span className="absolute right-4 top-1/2 -translate-y-1/2 w-2.5 h-2.5 bg-dracula-pink rounded-full border-2 border-slate-900 dark:border-dracula-darker"></span>
            )}
          </button>
        </nav>

        {/* Configuration Footer Menu */}
        <div className="px-4 py-6 border-t border-slate-800 dark:border-dracula-current space-y-6">
          {/* Logo Selection */}
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-[10px] text-slate-500 dark:text-dracula-comment uppercase font-bold tracking-widest ml-2">
              <ImageIcon size={12} /> Config. Logotipo
            </div>
            <div className="grid grid-cols-1 gap-1">
              <button 
                onClick={() => { setLogoPref('cirion'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
                className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'cirion' ? 'bg-slate-800 dark:bg-dracula-current text-dracula-cyan' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Cirion Technologies
              </button>
              <button 
                onClick={() => { setLogoPref('none'); if(window.innerWidth < 1024) setIsMobileMenuOpen(false); }}
                className={`text-left px-4 py-2.5 rounded-lg text-xs font-bold transition-all ${logoPref === 'none' ? 'bg-slate-800 dark:bg-dracula-current text-dracula-cyan' : 'text-slate-500 hover:text-slate-300'}`}
              >
                Sem Logotipo
              </button>
            </div>
          </div>

          {/* Theme Selection */}
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-[10px] text-slate-500 dark:text-dracula-comment uppercase font-bold tracking-widest ml-2">
              {theme === 'light' ? <Moon size={12} /> : <Sun size={12} />} Tema Visual
            </div>
            <div className="flex p-1 bg-slate-800 dark:bg-dracula-bg rounded-xl border border-slate-700 dark:border-dracula-current">
              <button 
                onClick={() => setTheme('light')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-[10px] font-bold transition-all ${theme === 'light' ? 'bg-slate-700 dark:bg-dracula-current text-white' : 'text-slate-500 hover:text-slate-300'}`}
              >
                <Sun size={12} /> Claro
              </button>
              <button 
                onClick={() => setTheme('dark')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-[10px] font-bold transition-all ${theme === 'dark' ? 'bg-slate-700 dark:bg-dracula-current text-white' : 'text-slate-500 hover:text-slate-300'}`}
              >
                <Moon size={12} /> Dracula
              </button>
            </div>
          </div>
        </div>

        <div className="p-4 border-t border-slate-800 dark:border-dracula-current">
          <button className="w-full flex items-center gap-4 px-4 py-3 text-slate-500 dark:text-dracula-comment hover:text-dracula-red transition-colors">
            <LogOut size={20} />
            <span className="font-semibold text-sm">Sair</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-x-hidden overflow-y-auto p-4 md:p-10 relative">
        {notification && (
          <div className={`fixed top-4 right-4 md:top-6 md:right-6 z-[200] flex items-center gap-3 px-4 md:px-6 py-3 md:py-4 rounded-xl md:rounded-2xl shadow-2xl border animate-in slide-in-from-top-6 duration-300 w-[calc(100%-2rem)] md:w-auto ${notification.type === 'success' ? 'bg-emerald-50 dark:bg-dracula-green/20 text-emerald-700 dark:text-dracula-green border-emerald-100 dark:border-dracula-green/40' : 'bg-rose-50 dark:bg-dracula-red/20 text-rose-700 dark:text-dracula-red border-rose-100 dark:border-dracula-red/40'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={20} className="shrink-0" /> : <AlertCircle size={20} className="shrink-0" />}
            <p className="font-bold text-sm leading-tight">{notification.message}</p>
          </div>
        )}

        <div className="max-w-6xl mx-auto space-y-6 md:space-y-8">
          <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div className="space-y-1">
              <h2 className="text-2xl md:text-3xl font-extrabold text-slate-900 dark:text-dracula-fg tracking-tight">
                {currentView === 'form' ? (editingExchange ? 'Editar Troca' : 'Nova Troca') : 
                 currentView === 'inventory' ? 'Inventário de Ativos' : 'Caixa de Entrada'}
              </h2>
              <p className="text-slate-500 dark:text-dracula-comment font-medium text-sm">Modo Offline Seguro: LocalStorage + Excel Sync</p>
            </div>
            {isLoading && (
              <div className="flex items-center gap-2 text-dracula-purple font-bold bg-dracula-purple/10 px-4 py-2 rounded-xl border border-dracula-purple/20 self-start md:self-end">
                <Loader2 className="animate-spin" size={18} />
                <span className="text-xs uppercase tracking-widest">Sincronizando...</span>
              </div>
            )}
          </header>

          <div className="bg-white dark:bg-dracula-darker rounded-2xl md:rounded-[2.5rem] shadow-xl shadow-slate-200/60 dark:shadow-black/40 border border-slate-100 dark:border-dracula-current overflow-hidden min-h-[500px] lg:min-h-[600px] transition-colors duration-200">
            {currentView === 'form' && (
              <AssetForm 
                onSave={handleSaveExchange} 
                editingExchange={editingExchange} 
                onCancel={() => navTo('inventory')} 
                exchanges={exchanges}
              />
            )}
            {currentView === 'inventory' && (
              <InventoryTable 
                exchanges={exchanges} 
                onDelete={handleDelete} 
                onEdit={(ex) => { setEditingExchange(ex); setCurrentView('form'); }} 
                onNotify={showNotification}
                onSignSender={handleSignSender}
                onBulkImport={handleBulkImport}
                logoPref={logoPref}
              />
            )}
            {currentView === 'inbox' && (
              <MockInbox 
                emails={emails} 
                onUpdateEmails={setEmails} 
                exchanges={exchanges}
                onSignReceiver={handleSignReceiver}
                logoPref={logoPref}
              />
            )}
          </div>
        </div>

        <footer className="max-w-6xl mx-auto mt-8 md:mt-12 flex flex-col sm:flex-row justify-between items-center text-slate-400 dark:text-dracula-comment text-[10px] font-bold uppercase tracking-wider px-4 gap-2 mb-8 md:mb-0">
          <p>© 2025 AssetFlow Technologies</p>
          <div className="flex gap-4">
            <span>Logo: {logoPref === 'cirion' ? 'Cirion' : 'Nenhum'}</span>
            <span>Tema: {theme === 'light' ? 'Claro' : 'Dracula Dark'}</span>
            <span>Armazenamento Local</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS_LIST, PROCESSORS_LIST, MODEL_PROCESSOR_MAP, MEMORY_LIST, STORAGE_LIST } from '../constants';
import { User, Package, History, Send, ScanLine, Lock, MousePointer2, Loader2, CheckSquare } from 'lucide-react';
import BarcodeScannerModal from './BarcodeScannerModal';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => Promise<void> | void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = ["Mouse", "Mochila", "Teclado", "DockStation", "Headset", "Monitor"];

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel }) => {
  const isReadOnly = editingExchange?.status === 'completed';
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState<AssetExchange>({
    id: '',
    status: 'draft',
    timestamp: Date.now(),
    colaborador_nome: '',
    colaborador_email: '',
    data_troca: new Date().toISOString().split('T')[0],
    observacoes: '',
    entregue_tipo: EQUIPMENT_TYPES[0],
    entregue_marca: BRANDS[0],
    entregue_modelo: MODELS_LIST[0],
    entregue_serial: '',
    entregue_processador: PROCESSORS_LIST[0],
    entregue_condicao: EquipmentCondition.NEW,
    entregue_memoria: MEMORY_LIST[2], // Default 16GB
    entregue_armazenamento: STORAGE_LIST[3], // Default 512GB
    entregue_acessorios: [],
    devolvido_tipo: EQUIPMENT_TYPES[0],
    devolvido_marca: BRANDS[0],
    devolvido_modelo: MODELS_LIST[0],
    devolvido_serial: '',
    devolvido_processador: PROCESSORS_LIST[0],
    devolvido_condicao: EquipmentCondition.USED,
    devolvido_memoria: MEMORY_LIST[2], // Default 16GB
    devolvido_armazenamento: STORAGE_LIST[3], // Default 512GB
    devolvido_acessorios: []
  });

  const [scannerConfig, setScannerConfig] = useState<{ isOpen: boolean; target: 'entregue' | 'devolvido' }>({
    isOpen: false,
    target: 'entregue'
  });

  useEffect(() => {
    if (editingExchange) {
      setFormData({ ...editingExchange });
    }
  }, [editingExchange]);

  const handleBrandChange = (brand: string, target: 'entregue' | 'devolvido') => {
    if (target === 'entregue') {
      setFormData({ ...formData, entregue_marca: brand });
    } else {
      setFormData({ ...formData, devolvido_marca: brand });
    }
  };

  const handleModelChange = (model: string, target: 'entregue' | 'devolvido') => {
    const mappedProcessor = MODEL_PROCESSOR_MAP[model];

    if (target === 'entregue') {
      setFormData(prev => ({ 
        ...prev, 
        entregue_modelo: model,
        entregue_processador: mappedProcessor || prev.entregue_processador 
      }));
    } else {
      setFormData(prev => ({ 
        ...prev, 
        devolvido_modelo: model,
        devolvido_processador: mappedProcessor || prev.devolvido_processador 
      }));
    }
  };

  const handleAccessoryToggle = (acc: string, target: 'entregue' | 'devolvido') => {
    const field = target === 'entregue' ? 'entregue_acessorios' : 'devolvido_acessorios';
    const current = formData[field] as string[];
    const updated = current.includes(acc) ? current.filter(i => i !== acc) : [...current, acc];
    setFormData({ ...formData, [field]: updated });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload = {
        ...formData,
        id: formData.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        timestamp: formData.timestamp || Date.now()
      };
      await onSave(payload);
    } catch (err) {
      console.error("Erro ao salvar formulário:", err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-4 md:mb-6 pb-2 border-b border-slate-100 dark:border-dracula-current">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={18} className="text-white" />
      </div>
      <h3 className="text-base md:text-lg font-semibold text-slate-800 dark:text-dracula-fg">{title}</h3>
    </div>
  );

  return (
    <>
      <form onSubmit={handleSubmit} className="p-4 md:p-8 space-y-8 md:space-y-12 transition-colors duration-200">
        {isReadOnly && (
          <div className="bg-amber-50 dark:bg-dracula-orange/10 border border-amber-200 dark:border-dracula-orange/40 p-4 rounded-xl md:rounded-2xl flex items-center gap-4">
            <Lock size={20} className="text-amber-700 dark:text-dracula-orange shrink-0" />
            <p className="text-amber-900 dark:text-dracula-orange text-sm font-bold">Registro Bloqueado por Assinatura</p>
          </div>
        )}

        <section>
          <SectionHeader icon={User} title="Dados do Colaborador" color="bg-dracula-purple" />
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">Nome Completo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required
                placeholder="Ex: João Silva"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none"
                value={formData.colaborador_nome}
                onChange={e => setFormData({ ...formData, colaborador_nome: e.target.value })}
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">E-mail Corporativo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="email"
                placeholder="joao.silva@cirion.com"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none"
                value={formData.colaborador_email}
                onChange={e => setFormData({ ...formData, colaborador_email: e.target.value })}
              />
            </div>
            <div className="space-y-1.5 sm:col-span-2 md:col-span-1">
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">Data da Troca</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="date"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none"
                value={formData.data_troca}
                onChange={e => setFormData({ ...formData, data_troca: e.target.value })}
              />
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
          {/* Entregue */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 dark:bg-dracula-bg/50 border border-slate-100 dark:border-dracula-current">
            <SectionHeader icon={Package} title="Equipamento Entregue" color="bg-dracula-green" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_tipo} onChange={e => setFormData({...formData, entregue_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_marca} onChange={e => handleBrandChange(e.target.value, 'entregue')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Modelo</label>
                <select 
                  disabled={isReadOnly || isSubmitting} 
                  className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" 
                  value={formData.entregue_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'entregue')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg font-mono text-sm pr-10 outline-none" value={formData.entregue_serial} onChange={e => setFormData({...formData, entregue_serial: e.target.value})} />
