import React, { useState } from 'react';
import { MockEmail, AssetExchange, LogoPreference } from '../types';
import { Mail, Trash2, Clock, Paperclip, PenLine, ShieldCheck, X, ChevronLeft } from 'lucide-react';
import { generateAssetPDF } from '../services/pdfService';

interface MockInboxProps {
  emails: MockEmail[];
  exchanges: AssetExchange[];
  onUpdateEmails: (emails: MockEmail[]) => void;
  onSignReceiver: (id: string, signature: string) => void;
  logoPref: LogoPreference;
}

const MockInbox: React.FC<MockInboxProps> = ({ emails, onUpdateEmails, exchanges, onSignReceiver, logoPref }) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [signingExchangeId, setSigningExchangeId] = useState<string | null>(null);
  const [receiverSignature, setReceiverSignature] = useState('');

  const selectedEmail = emails.find(e => e.id === selectedId);
  const currentExchange = exchanges.find(ex => ex.id === selectedEmail?.exchangeId);

  const markAsRead = (id: string) => {
    const updated = emails.map(e => e.id === id ? { ...e, read: true } : e);
    onUpdateEmails(updated);
    setSelectedId(id);
  };

  const handleReceiverSign = (e: React.FormEvent) => {
    e.preventDefault();
    if (!receiverSignature.trim() || !signingExchangeId) return;

    onSignReceiver(signingExchangeId, receiverSignature);
    setSigningExchangeId(null);
    setReceiverSignature('');
  };

  if (emails.length === 0) {
    return (
      <div className="p-10 md:p-20 flex flex-col items-center justify-center text-center bg-white dark:bg-dracula-bg h-[500px] md:h-[600px] transition-colors duration-200">
        <div className="w-16 h-16 bg-slate-100 dark:bg-dracula-darker rounded-full flex items-center justify-center mb-4 border dark:border-dracula-current">
          <Mail className="text-slate-300 dark:text-dracula-comment" size={32} />
        </div>
