                      <button onClick={() => generateAssetPDF(ex, logoPref)} title="Gerar PDF" className="p-2.5 text-slate-600 dark:text-dracula-fg hover:bg-slate-50 dark:hover:bg-dracula-current rounded-xl transition-colors"><FileDown size={16}/></button>
                      <button onClick={() => onDelete(ex.id)} title="Excluir" className="p-2.5 text-rose-600 dark:text-dracula-red hover:bg-rose-50 dark:hover:bg-dracula-red/10 rounded-xl transition-colors"><Trash2 size={16}/></button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          height: 6px;
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #f1f5f9;
        }
        .dark .custom-scrollbar::-webkit-scrollbar-track {
          background: #282a36;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #44475a;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #94a3b8;
        }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #6272a4;
        }
      `}</style>
    </div>
  );
};

