import React, { useState } from 'react';
import { X, Send, ShieldCheck, Mail } from 'lucide-react';
import { AssetExchange } from '../types';

interface SenderSignatureModalProps {
  exchange: AssetExchange;
  onClose: () => void;
  onConfirm: (id: string, signature: string) => void;
}

const SenderSignatureModal: React.FC<SenderSignatureModalProps> = ({ exchange, onClose, onConfirm }) => {
  const [step, setStep] = useState<'sign' | 'sending'>('sign');
  const [senderSignature, setSenderSignature] = useState('Gilberto Araujo');

  const handleSignAndSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!senderSignature.trim()) return;

    setStep('sending');
    setTimeout(() => {
      onConfirm(exchange.id, senderSignature);
    }, 1500);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 dark:bg-dracula-bg/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white dark:bg-dracula-bg w-full max-w-md rounded-3xl shadow-2xl overflow-hidden border border-slate-200 dark:border-dracula-current">
        <div className="p-6 border-b border-slate-100 dark:border-dracula-current flex items-center justify-between bg-white dark:bg-dracula-darker">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-600 dark:bg-dracula-purple text-white rounded-lg shadow-lg shadow-blue-200 dark:shadow-black/20">
              <Mail size={20} />
            </div>
            <div>
              <h3 className="font-bold text-slate-800 dark:text-dracula-fg leading-none">Outlook AssetFlow</h3>
              <p className="text-[10px] text-slate-400 dark:text-dracula-comment mt-1 uppercase tracking-wider font-bold">Assinatura de TI</p>
            </div>
          </div>
          <button 
            onClick={onClose} 
            disabled={step === 'sending'}
            className="p-2 hover:bg-slate-100 dark:hover:bg-dracula-current rounded-xl transition-colors text-slate-500 dark:text-dracula-comment disabled:opacity-30"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-8">
          {step === 'sign' ? (
            <form onSubmit={handleSignAndSend} className="space-y-6">
              <div className="p-4 bg-blue-50 dark:bg-dracula-cyan/10 border border-blue-100 dark:border-dracula-cyan/20 rounded-2xl">
                <p className="text-sm text-blue-800 dark:text-dracula-cyan leading-relaxed">
                  Ao assinar, o sistema anexará o PDF no seu Outlook e enviará para <strong>{exchange.colaborador_email}</strong>.
                </p>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 dark:text-dracula-comment uppercase tracking-wider">Sua Assinatura (TI)</label>
                <div className="relative">
                  <input
                    autoFocus
                    type="text"
                    value={senderSignature}
                    onChange={(e) => setSenderSignature(e.target.value)}
                    placeholder="Seu nome completo"
                    className="w-full h-24 bg-white dark:bg-dracula-darker border-2 border-dashed border-slate-200 dark:border-dracula-current rounded-xl px-4 text-center font-signature text-5xl text-blue-800 dark:text-dracula-purple focus:border-blue-500 dark:focus:border-dracula-purple focus:bg-white dark:focus:bg-dracula-bg focus:outline-none transition-all placeholder:text-slate-200 dark:placeholder-dracula-comment placeholder:font-sans placeholder:text-base"
                  />
                  <div className="absolute bottom-2 right-2 text-[10px] text-slate-300 dark:text-dracula-comment flex items-center gap-1">
                    <ShieldCheck size={10} /> Validado pela Infra TI
                  </div>
                </div>
              </div>

              <button
                type="submit"
                disabled={!senderSignature.trim()}
                className="w-full py-4 bg-blue-600 dark:bg-dracula-purple hover:bg-blue-700 dark:hover:bg-dracula-purple/80 text-white rounded-xl md:rounded-2xl font-bold shadow-xl shadow-blue-600/20 dark:shadow-black/20 transition-all flex items-center justify-center gap-2 group disabled:bg-slate-300 dark:disabled:bg-dracula-comment dark:disabled:text-dracula-fg/50"
              >
                <Send size={18} className="group-hover:translate-x-1 transition-transform" />
                Assinar e Enviar via Outlook
              </button>
            </form>
          ) : (
            <div className="py-10 flex flex-col items-center justify-center text-center space-y-6 transition-colors duration-200">
              <div className="relative">
                <div className="w-24 h-24 border-4 border-blue-50 dark:border-dracula-current border-t-blue-600 dark:border-t-dracula-purple rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center text-blue-600 dark:text-dracula-purple">
                  <Mail size={32} className="animate-pulse" />
                </div>
              </div>
              <div className="space-y-2">
                <h4 className="font-bold text-slate-800 dark:text-dracula-fg text-xl">Gerando Termo</h4>
                <p className="text-slate-500 dark:text-dracula-comment text-sm max-w-[250px] mx-auto">
                  Preparando PDF e enviando e-mail...
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
