import React, { useState, useEffect, useRef } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS_LIST, PROCESSORS_LIST, MODEL_PROCESSOR_MAP, MEMORY_LIST, STORAGE_LIST, AD_USERS } from '../constants';
import { User, Package, History, Send, ScanLine, Lock, MousePointer2, Loader2, CheckSquare, Search } from 'lucide-react';
import BarcodeScannerModal from './BarcodeScannerModal';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => Promise<void> | void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = ["Mouse", "Mochila", "Teclado", "DockStation", "Headset", "Monitor"];

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel }) => {
  const isReadOnly = editingExchange?.status === 'completed';
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showADSuggestions, setShowADSuggestions] = useState(false);
  const [adFilter, setAdFilter] = useState('');
  const adRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState<AssetExchange>({
    id: '',
    status: 'draft',
    timestamp: Date.now(),
    colaborador_nome: '',
    colaborador_email: '',
    data_troca: new Date().toISOString().split('T')[0],
    observacoes: '',
    entregue_tipo: EQUIPMENT_TYPES[0],
    entregue_marca: BRANDS[0],
    entregue_modelo: MODELS_LIST[0],
    entregue_serial: '',
    entregue_processador: PROCESSORS_LIST[0],
    entregue_condicao: EquipmentCondition.NEW,
    entregue_memoria: MEMORY_LIST[2], // Default 16GB
    entregue_armazenamento: STORAGE_LIST[3], // Default 512GB
    entregue_acessorios: [],
    devolvido_tipo: EQUIPMENT_TYPES[0],
    devolvido_marca: BRANDS[0],
    devolvido_modelo: MODELS_LIST[0],
    devolvido_serial: '',
    devolvido_processador: PROCESSORS_LIST[0],
    devolvido_condicao: EquipmentCondition.USED,
    devolvido_memoria: MEMORY_LIST[2], // Default 16GB
    devolvido_armazenamento: STORAGE_LIST[3], // Default 512GB
    devolvido_acessorios: []
  });

  const [scannerConfig, setScannerConfig] = useState<{ isOpen: boolean; target: 'entregue' | 'devolvido' }>({
    isOpen: false,
    target: 'entregue'
  });

  useEffect(() => {
    if (editingExchange) {
      setFormData({ ...editingExchange });
    }
  }, [editingExchange]);

  // Fechar dropdown do AD ao clicar fora
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (adRef.current && !adRef.current.contains(event.target as Node)) {
        setShowADSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleBrandChange = (brand: string, target: 'entregue' | 'devolvido') => {
    if (target === 'entregue') {
      setFormData({ ...formData, entregue_marca: brand });
    } else {
      setFormData({ ...formData, devolvido_marca: brand });
    }
  };

  const handleModelChange = (model: string, target: 'entregue' | 'devolvido') => {
    const mappedProcessor = MODEL_PROCESSOR_MAP[model];

    if (target === 'entregue') {
      setFormData(prev => ({ 
        ...prev, 
        entregue_modelo: model,
        entregue_processador: mappedProcessor || prev.entregue_processador 
      }));
    } else {
      setFormData(prev => ({ 
        ...prev, 
        devolvido_modelo: model,
        devolvido_processador: mappedProcessor || prev.devolvido_processador 
      }));
    }
  };

  const handleAccessoryToggle = (acc: string, target: 'entregue' | 'devolvido') => {
    const field = target === 'entregue' ? 'entregue_acessorios' : 'devolvido_acessorios';
    const current = formData[field] as string[];
    const updated = current.includes(acc) ? current.filter(i => i !== acc) : [...current, acc];
    setFormData({ ...formData, [field]: updated });
  };

  const handleNameInput = (value: string) => {
    setFormData({ ...formData, colaborador_nome: value });
    setAdFilter(value);
    setShowADSuggestions(value.length > 1);
  };

  const selectADUser = (user: { nome: string, email: string }) => {
    setFormData({ 
      ...formData, 
      colaborador_nome: user.nome, 
      colaborador_email: user.email 
    });
    setShowADSuggestions(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload = {
        ...formData,
        id: formData.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        timestamp: formData.timestamp || Date.now()
      };
      await onSave(payload);
    } catch (err) {
      console.error("Erro ao salvar formulário:", err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const filteredADUsers = AD_USERS.filter(user => 
    user.nome.toLowerCase().includes(adFilter.toLowerCase()) || 
    user.email.toLowerCase().includes(adFilter.toLowerCase())
  ).slice(0, 5);

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-4 md:mb-6 pb-2 border-b border-slate-100 dark:border-dracula-current">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={18} className="text-white" />
      </div>
      <h3 className="text-base md:text-lg font-semibold text-slate-800 dark:text-dracula-fg">{title}</h3>
    </div>
  );

  return (
    <>
      <form onSubmit={handleSubmit} className="p-4 md:p-8 space-y-8 md:space-y-12 transition-colors duration-200">
        {isReadOnly && (
          <div className="bg-amber-50 dark:bg-dracula-orange/10 border border-amber-200 dark:border-dracula-orange/40 p-4 rounded-xl md:rounded-2xl flex items-center gap-4">
            <Lock size={20} className="text-amber-700 dark:text-dracula-orange shrink-0" />
            <p className="text-amber-900 dark:text-dracula-orange text-sm font-bold">Registro Bloqueado por Assinatura</p>
          </div>
        )}

        <section>
          <SectionHeader icon={User} title="Dados do Colaborador" color="bg-dracula-purple" />
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
            <div className="space-y-1.5 relative" ref={adRef}>
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">Nome Completo</label>
              <div className="relative group">
                <input 
                  disabled={isReadOnly || isSubmitting} required
                  placeholder="Busque pelo nome..."
                  autoComplete="off"
                  className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none pl-10"
                  value={formData.colaborador_nome}
                  onChange={e => handleNameInput(e.target.value)}
                  onFocus={() => formData.colaborador_nome.length > 1 && setShowADSuggestions(true)}
                />
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-dracula-comment" />
              </div>

              {showADSuggestions && filteredADUsers.length > 0 && (
                <div className="absolute top-full left-0 w-full z-50 mt-1 bg-white dark:bg-dracula-current rounded-xl shadow-2xl border border-slate-100 dark:border-dracula-comment overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  {filteredADUsers.map((user, idx) => (
                    <button
                      key={idx}
                      type="button"
                      onClick={() => selectADUser(user)}
                      className="w-full px-4 py-3 text-left hover:bg-slate-50 dark:hover:bg-dracula-bg transition-colors flex flex-col gap-0.5"
                    >
                      <span className="font-bold text-sm text-slate-900 dark:text-dracula-fg">{user.nome}</span>
                      <span className="text-[10px] text-slate-500 dark:text-dracula-cyan">{user.email}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">E-mail Corporativo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="email"
                placeholder="joao.silva@cirion.com"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none"
                value={formData.colaborador_email}
                onChange={e => setFormData({ ...formData, colaborador_email: e.target.value })}
              />
            </div>

            <div className="space-y-1.5 sm:col-span-2 md:col-span-1">
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">Data da Troca</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="date"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none"
                value={formData.data_troca}
                onChange={e => setFormData({ ...formData, data_troca: e.target.value })}
              />
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
          {/* Entregue */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 dark:bg-dracula-bg/50 border border-slate-100 dark:border-dracula-current">
            <SectionHeader icon={Package} title="Equipamento Entregue" color="bg-dracula-green" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_tipo} onChange={e => setFormData({...formData, entregue_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_marca} onChange={e => handleBrandChange(e.target.value, 'entregue')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Modelo</label>
                <select 
                  disabled={isReadOnly || isSubmitting} 
                  className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" 
                  value={formData.entregue_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'entregue')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg font-mono text-sm pr-10 outline-none" value={formData.entregue_serial} onChange={e => setFormData({...formData, entregue_serial: e.target.value})} />
                  {!isReadOnly && !isSubmitting && <button type="button" onClick={() => setScannerConfig({isOpen: true, target: 'entregue'})} className="absolute right-2 top-1/2 -translate-y-1/2 text-dracula-comment hover:text-dracula-purple transition-colors p-1"><ScanLine size={18}/></button>}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Estado</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_condicao} onChange={e => setFormData({...formData, entregue_condicao: e.target.value as EquipmentCondition})}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Memória RAM</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_memoria} onChange={e => setFormData({...formData, entregue_memoria: e.target.value})}>
                  {MEMORY_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Processador</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-[10px]" value={formData.entregue_processador} onChange={e => setFormData({...formData, entregue_processador: e.target.value})}>
                  {PROCESSORS_LIST.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Armazenamento</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_armazenamento} onChange={e => setFormData({...formData, entregue_armazenamento: e.target.value})}>
                  {STORAGE_LIST.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="mt-6">
              <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment block mb-3 uppercase tracking-wider">Acessórios Entregues</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label 
                    key={acc} 
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border cursor-pointer transition-all text-xs font-medium ${formData.entregue_acessorios.includes(acc) ? 'bg-dracula-green/10 border-dracula-green/40 text-dracula-green ring-2 ring-dracula-green/10' : 'bg-white dark:bg-dracula-bg border-slate-200 dark:border-dracula-current text-slate-500 dark:text-dracula-comment hover:border-dracula-green'}`}
                  >
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={formData.entregue_acessorios.includes(acc)} 
                      onChange={() => handleAccessoryToggle(acc, 'entregue')} 
                      disabled={isReadOnly || isSubmitting} 
                    />
                    <CheckSquare size={14} className={`shrink-0 ${formData.entregue_acessorios.includes(acc) ? 'opacity-100' : 'opacity-20'}`} />
                    <span className="truncate">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>

          {/* Devolvido */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 dark:bg-dracula-bg/50 border border-slate-100 dark:border-dracula-current">
            <SectionHeader icon={History} title="Equipamento Devolvido" color="bg-dracula-red" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.devolvido_tipo} onChange={e => setFormData({...formData, devolvido_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.devolvido_marca} onChange={e => handleBrandChange(e.target.value, 'devolvido')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Modelo</label>
                <select 
                  disabled={isReadOnly || isSubmitting} 
                  className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" 
                  value={formData.devolvido_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'devolvido')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Serial / IMEI</label>
                <div className="relative">
                  <input disabled={isReadOnly || isSubmitting} required className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg font-mono text-sm pr-10 outline-none" value={formData.devolvido_serial} onChange={e => setFormData({...formData, devolvido_serial: e.target.value})} />
                  {!isReadOnly && !isSubmitting && <button type="button" onClick={() => setScannerConfig({isOpen: true, target: 'devolvido'})} className="absolute right-2 top-1/2 -translate-y-1/2 text-dracula-comment hover:text-dracula-red transition-colors p-1"><ScanLine size={18}/></button>}
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Estado</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.devolvido_condicao} onChange={e => setFormData({...formData, devolvido_condicao: e.target.value as EquipmentCondition})}>
                  <option value={EquipmentCondition.NEW}>Novo</option>
                  <option value={EquipmentCondition.USED}>Usado</option>
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Memória RAM</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.devolvido_memoria} onChange={e => setFormData({...formData, devolvido_memoria: e.target.value})}>
                  {MEMORY_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Processador</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-[10px]" value={formData.devolvido_processador} onChange={e => setFormData({...formData, devolvido_processador: e.target.value})}>
                  {PROCESSORS_LIST.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>
              <div className="space-y-1 sm:col-span-2">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Armazenamento</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.devolvido_armazenamento} onChange={e => setFormData({...formData, devolvido_armazenamento: e.target.value})}>
                  {STORAGE_LIST.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="mt-6">
              <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment block mb-3 uppercase tracking-wider">Acessórios Devolvidos</label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {ACCESSORIES_OPTIONS.map(acc => (
                  <label 
                    key={acc} 
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border cursor-pointer transition-all text-xs font-medium ${formData.devolvido_acessorios.includes(acc) ? 'bg-dracula-red/10 border-dracula-red/40 text-dracula-red ring-2 ring-dracula-red/10' : 'bg-white dark:bg-dracula-bg border-slate-200 dark:border-dracula-current text-slate-500 dark:text-dracula-comment hover:border-dracula-red'}`}
                  >
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={formData.devolvido_acessorios.includes(acc)} 
                      onChange={() => handleAccessoryToggle(acc, 'devolvido')} 
                      disabled={isReadOnly || isSubmitting} 
                    />
                    <CheckSquare size={14} className={`shrink-0 ${formData.devolvido_acessorios.includes(acc) ? 'opacity-100' : 'opacity-20'}`} />
                    <span className="truncate">{acc}</span>
                  </label>
                ))}
              </div>
            </div>
          </section>
        </div>

        <section>
          <SectionHeader icon={MousePointer2} title="Observações Internas" color="bg-dracula-comment" />
          <textarea 
            disabled={isReadOnly || isSubmitting}
            placeholder="Ex: Teclado do notebook entregue está com a tecla 'A' frouxa."
            className="w-full p-4 rounded-xl md:rounded-2xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg h-24 focus:ring-2 focus:ring-dracula-purple/20 transition-all resize-none text-sm outline-none" 
            value={formData.observacoes}
            onChange={e => setFormData({ ...formData, observacoes: e.target.value })}
          />
        </section>

        <div className="flex flex-col-reverse sm:flex-row justify-end items-stretch sm:items-center gap-3 sm:gap-4">
          <button 
            type="button" 
            onClick={onCancel} 
            disabled={isSubmitting}
            className="px-8 py-3.5 rounded-xl md:rounded-2xl font-bold text-slate-500 dark:text-dracula-comment hover:bg-slate-100 dark:hover:bg-dracula-current transition-colors disabled:opacity-30 text-sm"
          >
            Cancelar
          </button>
          {!isReadOnly && (
            <button 
              type="submit" 
              disabled={isSubmitting}
              className="flex items-center justify-center gap-2 bg-dracula-purple hover:bg-dracula-purple/80 text-white px-8 md:px-10 py-3.5 rounded-xl md:rounded-2xl font-bold shadow-xl shadow-dracula-purple/20 transition-all active:scale-95 disabled:bg-dracula-purple/50 text-sm"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="animate-spin" size={18} />
                  <span>Gravando...</span>
                </>
              ) : (
                <>
                  <Send size={18} />
                  <span>{editingExchange ? 'Salvar Registro' : 'Gravar Registro'}</span>
                </>
              )}
            </button>
          )}
        </div>
      </form>

      {scannerConfig.isOpen && (
        <BarcodeScannerModal 
          title={scannerConfig.target === 'entregue' ? 'Lendo Serial Entregue' : 'Lendo Serial Devolvido'}
          onScan={(text) => {
            const processed = text.trim();
            if (scannerConfig.target === 'entregue') setFormData({...formData, entregue_serial: processed});
            else setFormData({...formData, devolvido_serial: processed});
            setScannerConfig({...scannerConfig, isOpen: false});
          }}
          onClose={() => setScannerConfig({...scannerConfig, isOpen: false})}
        />
      )}
    </>
  );
};

export default AssetForm;

import React, { useState, useEffect, useRef } from 'react';
import { AssetExchange, EquipmentCondition } from '../types';
import { EQUIPMENT_TYPES, BRANDS, MODELS_LIST, PROCESSORS_LIST, MODEL_PROCESSOR_MAP, MEMORY_LIST, STORAGE_LIST, AD_USERS } from '../constants';
import { User, Package, History, Send, ScanLine, Lock, MousePointer2, Loader2, CheckSquare, Search } from 'lucide-react';
import BarcodeScannerModal from './BarcodeScannerModal';

interface AssetFormProps {
  onSave: (exchange: AssetExchange) => Promise<void> | void;
  editingExchange?: AssetExchange | null;
  onCancel?: () => void;
  exchanges?: AssetExchange[];
}

const ACCESSORIES_OPTIONS = ["Mouse", "Mochila", "Teclado", "DockStation", "Headset", "Monitor"];

const AssetForm: React.FC<AssetFormProps> = ({ onSave, editingExchange, onCancel }) => {
  const isReadOnly = editingExchange?.status === 'completed';
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showADSuggestions, setShowADSuggestions] = useState(false);
  const [adFilter, setAdFilter] = useState('');
  const adRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState<AssetExchange>({
    id: '',
    status: 'draft',
    timestamp: Date.now(),
    colaborador_nome: '',
    colaborador_email: '',
    data_troca: new Date().toISOString().split('T')[0],
    observacoes: '',
    entregue_tipo: EQUIPMENT_TYPES[0],
    entregue_marca: BRANDS[0],
    entregue_modelo: MODELS_LIST[0],
    entregue_serial: '',
    entregue_processador: PROCESSORS_LIST[0],
    entregue_condicao: EquipmentCondition.NEW,
    entregue_memoria: MEMORY_LIST[2], // Default 16GB
    entregue_armazenamento: STORAGE_LIST[3], // Default 512GB
    entregue_acessorios: [],
    devolvido_tipo: EQUIPMENT_TYPES[0],
    devolvido_marca: BRANDS[0],
    devolvido_modelo: MODELS_LIST[0],
    devolvido_serial: '',
    devolvido_processador: PROCESSORS_LIST[0],
    devolvido_condicao: EquipmentCondition.USED,
    devolvido_memoria: MEMORY_LIST[2], // Default 16GB
    devolvido_armazenamento: STORAGE_LIST[3], // Default 512GB
    devolvido_acessorios: []
  });

  const [scannerConfig, setScannerConfig] = useState<{ isOpen: boolean; target: 'entregue' | 'devolvido' }>({
    isOpen: false,
    target: 'entregue'
  });

  useEffect(() => {
    if (editingExchange) {
      setFormData({ ...editingExchange });
    }
  }, [editingExchange]);

  // Fechar dropdown do AD ao clicar fora
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (adRef.current && !adRef.current.contains(event.target as Node)) {
        setShowADSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleBrandChange = (brand: string, target: 'entregue' | 'devolvido') => {
    if (target === 'entregue') {
      setFormData({ ...formData, entregue_marca: brand });
    } else {
      setFormData({ ...formData, devolvido_marca: brand });
    }
  };

  const handleModelChange = (model: string, target: 'entregue' | 'devolvido') => {
    const mappedProcessor = MODEL_PROCESSOR_MAP[model];

    if (target === 'entregue') {
      setFormData(prev => ({ 
        ...prev, 
        entregue_modelo: model,
        entregue_processador: mappedProcessor || prev.entregue_processador 
      }));
    } else {
      setFormData(prev => ({ 
        ...prev, 
        devolvido_modelo: model,
        devolvido_processador: mappedProcessor || prev.devolvido_processador 
      }));
    }
  };

  const handleAccessoryToggle = (acc: string, target: 'entregue' | 'devolvido') => {
    const field = target === 'entregue' ? 'entregue_acessorios' : 'devolvido_acessorios';
    const current = formData[field] as string[];
    const updated = current.includes(acc) ? current.filter(i => i !== acc) : [...current, acc];
    setFormData({ ...formData, [field]: updated });
  };

  const handleNameInput = (value: string) => {
    setFormData({ ...formData, colaborador_nome: value });
    setAdFilter(value);
    setShowADSuggestions(value.length > 1);
  };

  const selectADUser = (user: { nome: string, email: string }) => {
    setFormData({ 
      ...formData, 
      colaborador_nome: user.nome, 
      colaborador_email: user.email 
    });
    setShowADSuggestions(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    try {
      const payload = {
        ...formData,
        id: formData.id || Math.random().toString(36).substr(2, 9).toUpperCase(),
        timestamp: formData.timestamp || Date.now()
      };
      await onSave(payload);
    } catch (err) {
      console.error("Erro ao salvar formulário:", err);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Filtramos e mostramos os top 10 resultados para dar mais opções
  const filteredADUsers = AD_USERS.filter(user => 
    user.nome.toLowerCase().includes(adFilter.toLowerCase()) || 
    user.email.toLowerCase().includes(adFilter.toLowerCase())
  ).slice(0, 10);

  const SectionHeader = ({ icon: Icon, title, color }: { icon: any, title: string, color: string }) => (
    <div className="flex items-center gap-3 mb-4 md:mb-6 pb-2 border-b border-slate-100 dark:border-dracula-current">
      <div className={`p-2 rounded-lg ${color}`}>
        <Icon size={18} className="text-white" />
      </div>
      <h3 className="text-base md:text-lg font-semibold text-slate-800 dark:text-dracula-fg">{title}</h3>
    </div>
  );

  return (
    <>
      <form onSubmit={handleSubmit} className="p-4 md:p-8 space-y-8 md:space-y-12 transition-colors duration-200">
        {isReadOnly && (
          <div className="bg-amber-50 dark:bg-dracula-orange/10 border border-amber-200 dark:border-dracula-orange/40 p-4 rounded-xl md:rounded-2xl flex items-center gap-4">
            <Lock size={20} className="text-amber-700 dark:text-dracula-orange shrink-0" />
            <p className="text-amber-900 dark:text-dracula-orange text-sm font-bold">Registro Bloqueado por Assinatura</p>
          </div>
        )}

        <section>
          <SectionHeader icon={User} title="Dados do Colaborador" color="bg-dracula-purple" />
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
            <div className="space-y-1.5 relative" ref={adRef}>
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">Nome Completo</label>
              <div className="relative group">
                <input 
                  disabled={isReadOnly || isSubmitting} required
                  placeholder="Busque pelo nome..."
                  autoComplete="off"
                  className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none pl-10"
                  value={formData.colaborador_nome}
                  onChange={e => handleNameInput(e.target.value)}
                  onFocus={() => formData.colaborador_nome.length > 1 && setShowADSuggestions(true)}
                />
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 dark:text-dracula-comment" />
              </div>

              {showADSuggestions && filteredADUsers.length > 0 && (
                <div className="absolute top-full left-0 w-full z-[70] mt-1 bg-white dark:bg-dracula-current rounded-xl shadow-2xl border border-slate-100 dark:border-dracula-comment overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200 max-h-64 overflow-y-auto ad-scrollbar">
                  {filteredADUsers.map((user, idx) => (
                    <button
                      key={idx}
                      type="button"
                      onClick={() => selectADUser(user)}
                      className="w-full px-4 py-3 text-left hover:bg-slate-50 dark:hover:bg-dracula-bg transition-colors flex flex-col gap-0.5 border-b border-slate-50 dark:border-dracula-darker last:border-0"
                    >
                      <span className="font-bold text-sm text-slate-900 dark:text-dracula-fg">{user.nome}</span>
                      <span className="text-[10px] text-slate-500 dark:text-dracula-cyan">{user.email}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">E-mail Corporativo</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="email"
                placeholder="joao.silva@cirion.com"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none"
                value={formData.colaborador_email}
                onChange={e => setFormData({ ...formData, colaborador_email: e.target.value })}
              />
            </div>

            <div className="space-y-1.5 sm:col-span-2 md:col-span-1">
              <label className="text-xs font-bold text-slate-500 dark:text-dracula-comment uppercase">Data da Troca</label>
              <input 
                disabled={isReadOnly || isSubmitting} required type="date"
                className="w-full px-4 py-2.5 rounded-xl border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg focus:ring-2 focus:ring-dracula-purple/20 transition-all text-sm outline-none"
                value={formData.data_troca}
                onChange={e => setFormData({ ...formData, data_troca: e.target.value })}
              />
            </div>
          </div>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
          {/* Entregue */}
          <section className="p-4 md:p-6 rounded-2xl bg-slate-50 dark:bg-dracula-bg/50 border border-slate-100 dark:border-dracula-current">
            <SectionHeader icon={Package} title="Equipamento Entregue" color="bg-dracula-green" />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Tipo</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_tipo} onChange={e => setFormData({...formData, entregue_tipo: e.target.value})}>
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Marca</label>
                <select disabled={isReadOnly || isSubmitting} className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" value={formData.entregue_marca} onChange={e => handleBrandChange(e.target.value, 'entregue')}>
                  {BRANDS.map(b => <option key={b} value={b}>{b}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Modelo</label>
                <select 
                  disabled={isReadOnly || isSubmitting} 
                  className="w-full px-3 py-2 rounded-lg border bg-white dark:bg-dracula-bg dark:border-dracula-current dark:text-dracula-fg text-sm" 
                  value={formData.entregue_modelo} 
                  onChange={e => handleModelChange(e.target.value, 'entregue')}
                >
                  {MODELS_LIST.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 dark:text-dracula-comment uppercase">Serial / IMEI</label>
